function buildRoundedWorldPath(points) {
  const format = (value) => Number(value.toFixed(1));
  let path = `M ${format(points[0].x)} ${format(points[0].y)}`;

  for (let index = 0; index < points.length - 1; index += 1) {
    const current = points[index];
    const next = points[index + 1];
    const middleY = (current.y + next.y) / 2;
    path += ` C ${format(current.x)} ${format(middleY)}`
      + ` ${format(next.x)} ${format(middleY)}`
      + ` ${format(next.x)} ${format(next.y)}`;
  }

  return path;
}

function buildWorldChapterPathData() {
  const points = [{ x: 180, y: WORLD_CHAPTER_TRACK_HEIGHT }];
  WORLD_LEVEL_PATTERN.forEach((position) => {
    points.push({
      x: (position.x / 100) * 360,
      y: (position.y / 100) * WORLD_CHAPTER_TRACK_HEIGHT,
    });
  });
  points.push({ x: 180, y: 0 });
  return buildRoundedWorldPath(points);
}

function buildGardenWorldPathData() {
  const points = [];

  for (let index = 0; index < GARDEN_WORLD_CHAPTERS * WORLD_CHAPTER_SIZE; index += 1) {
    const chapterIndex = Math.floor(index / WORLD_CHAPTER_SIZE);
    const position = WORLD_LEVEL_PATTERN[index % WORLD_CHAPTER_SIZE];
    points.push({
      x: (position.x / 100) * 360,
      y: (GARDEN_WORLD_CHAPTERS - chapterIndex - 1) * WORLD_CHAPTER_TRACK_HEIGHT
        + (position.y / 100) * WORLD_CHAPTER_TRACK_HEIGHT,
    });
  }

  points.push({ x: 180, y: 0 });
  return buildRoundedWorldPath(points);
}

