const assetGroupPromises = new Map();
const LEVELS_PER_DATA_SECTION = 10;
const LEVEL_DATA_VERSION = "v8-kitchen-webs-2";
const levelSectionPromises = new Map();
globalThis.__MOUSE_MAZE_PREGENERATED_LEVELS__ ??= [];

function levelSectionNumber(levelNumber) {
  return Math.floor((levelNumber - 1) / LEVELS_PER_DATA_SECTION) + 1;
}

function levelSectionIsLoaded(sectionNumber) {
  const firstLevelIndex = (sectionNumber - 1) * LEVELS_PER_DATA_SECTION;
  return Boolean(globalThis.__MOUSE_MAZE_PREGENERATED_LEVELS__?.[firstLevelIndex]?.length);
}

function ensureLevelSectionForLevel(levelNumber) {
  const sectionNumber = levelSectionNumber(levelNumber);
  if (levelSectionIsLoaded(sectionNumber)) return Promise.resolve();
  if (levelSectionPromises.has(sectionNumber)) return levelSectionPromises.get(sectionNumber);

  const promise = new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.async = true;
    script.src = `levels/section-${sectionNumber}.js?v=${LEVEL_DATA_VERSION}`;
    script.addEventListener("load", () => {
      script.remove();
      if (levelSectionIsLoaded(sectionNumber)) resolve();
      else reject(new Error(`Level section ${sectionNumber} did not register its variants.`));
    }, { once: true });
    script.addEventListener("error", () => {
      script.remove();
      reject(new Error(`Unable to load level section ${sectionNumber}.`));
    }, { once: true });
    document.head.append(script);
  }).catch((error) => {
    levelSectionPromises.delete(sectionNumber);
    throw error;
  });
  levelSectionPromises.set(sectionNumber, promise);
  return promise;
}

function loadSprite(sprite, source) {
  if (sprite.src) return sprite.decode?.().catch(() => undefined) ?? Promise.resolve();
  return new Promise((resolve) => {
    const finish = () => resolve();
    sprite.addEventListener("load", finish, { once: true });
    sprite.addEventListener("error", finish, { once: true });
    sprite.src = source;
  });
}

const greenScreenSpriteCache = new WeakMap();

function prepareGreenScreenSprite(sprite) {
  if (!sprite?.complete || !sprite.naturalWidth) return null;
  if (greenScreenSpriteCache.has(sprite)) return greenScreenSpriteCache.get(sprite);

  try {
    const canvas = document.createElement("canvas");
    canvas.width = sprite.naturalWidth;
    canvas.height = sprite.naturalHeight;
    const context = canvas.getContext("2d", { willReadFrequently: true });
    context.drawImage(sprite, 0, 0);
    const pixels = context.getImageData(0, 0, canvas.width, canvas.height);

    for (let index = 0; index < pixels.data.length; index += 4) {
      const red = pixels.data[index];
      const green = pixels.data[index + 1];
      const blue = pixels.data[index + 2];
      const dominantGreen = green - Math.max(red, blue);
      if (green < 105 || dominantGreen < 24) continue;

      const removal = clamp((dominantGreen - 24) / 92, 0, 1);
      pixels.data[index + 3] = Math.round(pixels.data[index + 3] * (1 - removal));
      if (pixels.data[index + 3] > 0) {
        pixels.data[index + 1] = Math.min(green, Math.max(red, blue) + 14);
      }
    }

    context.putImageData(pixels, 0, 0);
    greenScreenSpriteCache.set(sprite, canvas);
    return canvas;
  } catch {
    return null;
  }
}

function loadAssetGroup(groupName) {
  if (assetGroupPromises.has(groupName)) return assetGroupPromises.get(groupName);
  const entries = ASSET_GROUPS[groupName] ?? [];
  const promise = Promise.all(entries.map(([sprite, source]) => loadSprite(sprite, source)))
    .then(() => {
      if (groupName === "milk") {
        prepareGreenScreenSprite(milkSpillUpSprite);
        prepareGreenScreenSprite(milkSpillDownSprite);
      }
      document.querySelectorAll?.(`[data-asset-group="${groupName}"]`).forEach((image) => {
        if (!image.getAttribute("src") && image.dataset.src) image.src = image.dataset.src;
      });
      applySelectedSkinPreviewToPowerIcons();
      renderAlbinoShopPreview();
      renderShadowShopPreview();
      renderColorShopPreviews();
      renderSelectedMouseSkin();
      updateShopSkinSelection();
      requestMazeDraw();
    });
  assetGroupPromises.set(groupName, promise);
  return promise;
}

function assetGroupsForLevel(levelNumber) {
  const config = LEVEL_CONFIGS[levelNumber - 1] ?? {};
  const groups = new Set(["core"]);
  const reachedLevel = Math.max(levelNumber, worldProgress?.unlockedLevel ?? levelNumber);
  if (config.milkCount) groups.add("milk");
  if (config.pieCount) groups.add("pie");
  if (config.carrotCount) groups.add("carrot");
  if (config.spiderWebCount) groups.add("spiderWeb");
  if (config.carMode) groups.add("car");
  if (config.cockroachMode) groups.add("cockroach");
  if (config.catPawMode) groups.add("catPaw");
  if (config.crowMode) groups.add("crow");
  if (config.cloudMode) groups.add("cloud");
  if (config.tunnelCount || config.carrotCount) groups.add("tunnels");
  if (config.rockMode) groups.add("rocks");
  for (let variantIndex = 0; variantIndex < VARIANTS_PER_LEVEL; variantIndex += 1) {
    for (const adversity of adversitiesForVariant(config, variantIndex)) {
      groups.add(adversity);
    }
  }
  for (const [powerKey, unlockLevel] of Object.entries(POWER_UNLOCK_LEVELS)) {
    if (Number.isFinite(unlockLevel) && reachedLevel >= unlockLevel) groups.add(powerKey);
  }
  return [...groups];
}

function ensureAssetsForLevel(levelNumber) {
  return Promise.all(assetGroupsForLevel(levelNumber).map(loadAssetGroup));
}

function scheduleNextLevelPreload(levelNumber) {
  const nextLevel = levelNumber + 1;
  const preload = () => {
    void loadAssetGroup("reactions");
    if (nextLevel > LEVEL_CONFIGS.length) return;
    void ensureAssetsForLevel(nextLevel);
    void ensureLevelSectionForLevel(nextLevel);
  };
  if (typeof globalThis.requestIdleCallback === "function") {
    globalThis.requestIdleCallback(preload, { timeout: 1800 });
  } else {
    setTimeout(preload, 500);
  }
}

void loadAssetGroup("core");

function createTailFixedMouseAnimation(sprite) {
  const repairs = sprite === mouseEatingSprite
    ? [
        { frame: 0, box: [224, 50, 276, 109], shift: 70 },
        { frame: 1, box: [208, 50, 256, 109], shift: 65 },
        { frame: 2, box: [217, 40, 266, 99], shift: 65 },
        { frame: 3, box: [207, 42, 253, 100], shift: 65 },
      ]
    : sprite === mouseSleepSprite
      ? [
          { frame: 0, box: [228, 79, 273, 122], shift: 70 },
          { frame: 1, box: [192, 120, 236, 153], shift: 60 },
        ]
      : null;
  if (!repairs || !sprite.complete || !sprite.naturalWidth || !sprite.naturalHeight) {
    return sprite;
  }

  const cached = mouseTailFixedSpriteCache.get(sprite);
  if (cached) return cached;

  const canvas = document.createElement("canvas");
  canvas.width = sprite.naturalWidth;
  canvas.height = sprite.naturalHeight;
  const context = canvas.getContext("2d", { willReadFrequently: true });
  context.drawImage(sprite, 0, 0);
  const pixels = context.getImageData(0, 0, canvas.width, canvas.height);
  const sourcePixels = new Uint8ClampedArray(pixels.data);
  const mask = new Uint8Array(canvas.width * canvas.height);
  const scale = canvas.height / 384;
  const frameWidth = canvas.height;
  const dilationRadius = Math.max(3, Math.round(7 * scale));

  for (const repair of repairs) {
    const frameOffset = Math.round(repair.frame * frameWidth);
    const [sourceMinX, sourceMinY, sourceMaxX, sourceMaxY] = repair.box;
    const minX = frameOffset + Math.floor(sourceMinX * scale);
    const minY = Math.floor(sourceMinY * scale);
    const maxX = frameOffset + Math.ceil(sourceMaxX * scale);
    const maxY = Math.ceil(sourceMaxY * scale);

    for (let y = minY; y < maxY; y += 1) {
      for (let x = minX; x < maxX; x += 1) {
        const index = (y * canvas.width + x) * 4;
        const red = sourcePixels[index];
        const green = sourcePixels[index + 1];
        const blue = sourcePixels[index + 2];
        const alpha = sourcePixels[index + 3];
        const isPinkTail =
          alpha > 20 &&
          red > 120 &&
          red - green > 25 &&
          red - blue > 18;
        if (!isPinkTail) continue;

        for (let offsetY = -dilationRadius; offsetY <= dilationRadius; offsetY += 1) {
          const targetY = y + offsetY;
          if (targetY < 0 || targetY >= canvas.height) continue;
          for (let offsetX = -dilationRadius; offsetX <= dilationRadius; offsetX += 1) {
            if (offsetX * offsetX + offsetY * offsetY > dilationRadius * dilationRadius) continue;
            const targetX = x + offsetX;
            if (targetX < frameOffset || targetX >= frameOffset + frameWidth) continue;
            mask[targetY * canvas.width + targetX] = 1;
          }
        }
      }
    }

    const shift = Math.round(repair.shift * scale);
    const repairMinX = Math.max(frameOffset, minX - dilationRadius);
    const repairMaxX = Math.min(frameOffset + frameWidth, maxX + dilationRadius);
    const repairMinY = Math.max(0, minY - dilationRadius);
    const repairMaxY = Math.min(canvas.height, maxY + dilationRadius);
    for (let y = repairMinY; y < repairMaxY; y += 1) {
      for (let x = repairMinX; x < repairMaxX; x += 1) {
        if (!mask[y * canvas.width + x]) continue;
        const sourceX = Math.max(frameOffset, x - shift);
        const sourceIndex = (y * canvas.width + sourceX) * 4;
        const targetIndex = (y * canvas.width + x) * 4;
        pixels.data[targetIndex] = sourcePixels[sourceIndex];
        pixels.data[targetIndex + 1] = sourcePixels[sourceIndex + 1];
        pixels.data[targetIndex + 2] = sourcePixels[sourceIndex + 2];
        pixels.data[targetIndex + 3] = sourcePixels[sourceIndex + 3];
      }
    }
  }

  context.putImageData(pixels, 0, 0);
  mouseTailFixedSpriteCache.set(sprite, canvas);
  return canvas;
}

function createAlbinoSkinPreview(sprite, force = false) {
  const skinId = force ? "albino" : selectedMouseSkin;
  if (!sprite.complete || !sprite.naturalWidth) {
    return sprite;
  }
  const sourceSprite = createTailFixedMouseAnimation(sprite);
  if (skinId === "original") return sourceSprite;
  if (skinId === "shadow") return createShadowSkinPreview(sourceSprite);
  if (skinId === "pink" || skinId === "orange" || skinId === "gold") {
    return createColorSkinPreview(sourceSprite, skinId);
  }

  const cached = skinPreviewSpriteCache.get(sourceSprite);
  if (cached) return cached;

  const canvas = document.createElement("canvas");
  canvas.width = sourceSprite.naturalWidth || sourceSprite.width;
  canvas.height = sourceSprite.naturalHeight || sourceSprite.height;
  const context = canvas.getContext("2d", { willReadFrequently: true });
  context.drawImage(sourceSprite, 0, 0);
  const pixels = context.getImageData(0, 0, canvas.width, canvas.height);

  for (let index = 0; index < pixels.data.length; index += 4) {
    if (pixels.data[index + 3] < 18) continue;
    const red = pixels.data[index];
    const green = pixels.data[index + 1];
    const blue = pixels.data[index + 2];
    const lightness = red * 0.299 + green * 0.587 + blue * 0.114;
    const chroma = Math.max(red, green, blue) - Math.min(red, green, blue);

    if (lightness < 72 && chroma < 38) {
      pixels.data[index] = Math.round(102 + lightness * 1.15);
      pixels.data[index + 1] = Math.round(8 + lightness * 0.2);
      pixels.data[index + 2] = Math.round(16 + lightness * 0.24);
    } else if (chroma < 54) {
      const whiteShade = Math.min(250, Math.round(180 + lightness * 0.32));
      pixels.data[index] = whiteShade;
      pixels.data[index + 1] = Math.max(0, whiteShade - 3);
      pixels.data[index + 2] = Math.max(0, whiteShade - 6);
    }
  }

  context.putImageData(pixels, 0, 0);
  skinPreviewSpriteCache.set(sourceSprite, canvas);
  return canvas;
}

function renderAlbinoShopPreview() {
  if (!shopAlbinoPreviewEl || !mouseSprite.complete || !mouseSprite.naturalWidth) return;
  const preview = createAlbinoSkinPreview(mouseSprite, true);
  if (preview === mouseSprite) {
    shopAlbinoPreviewEl.src = mouseSprite.src;
    return;
  }
  shopAlbinoPreviewEl.src = preview.toDataURL("image/png");
}

function createShadowEyeMask(data, width, height) {
  const pixelCount = width * height;
  const candidates = new Uint8Array(pixelCount);
  const visited = new Uint8Array(pixelCount);
  const eyeMask = new Uint8Array(pixelCount);
  const queue = new Int32Array(pixelCount);

  for (let pixelIndex = 0; pixelIndex < pixelCount; pixelIndex += 1) {
    const index = pixelIndex * 4;
    if (data[index + 3] < 18) continue;
    const red = data[index];
    const green = data[index + 1];
    const blue = data[index + 2];
    const lightness = red * 0.299 + green * 0.587 + blue * 0.114;
    const chroma = Math.max(red, green, blue) - Math.min(red, green, blue);
    if (lightness < 82 && chroma < 42) candidates[pixelIndex] = 1;
  }

  for (let start = 0; start < pixelCount; start += 1) {
    if (!candidates[start] || visited[start]) continue;
    let queueStart = 0;
    let queueEnd = 1;
    let minX = start % width;
    let maxX = minX;
    let minY = Math.floor(start / width);
    let maxY = minY;
    queue[0] = start;
    visited[start] = 1;

    while (queueStart < queueEnd) {
      const pixelIndex = queue[queueStart];
      queueStart += 1;
      const x = pixelIndex % width;
      const y = Math.floor(pixelIndex / width);
      minX = Math.min(minX, x);
      maxX = Math.max(maxX, x);
      minY = Math.min(minY, y);
      maxY = Math.max(maxY, y);

      for (let offsetY = -1; offsetY <= 1; offsetY += 1) {
        const nextY = y + offsetY;
        if (nextY < 0 || nextY >= height) continue;
        for (let offsetX = -1; offsetX <= 1; offsetX += 1) {
          if (offsetX === 0 && offsetY === 0) continue;
          const nextX = x + offsetX;
          if (nextX < 0 || nextX >= width) continue;
          const next = nextY * width + nextX;
          if (!candidates[next] || visited[next]) continue;
          visited[next] = 1;
          queue[queueEnd] = next;
          queueEnd += 1;
        }
      }
    }

    if (queueEnd < 5 || queueEnd > pixelCount * 0.025) continue;
    let containsHighlight = false;
    const insetX = Math.max(0, minX - 2);
    const insetY = Math.max(0, minY - 2);
    const endX = Math.min(width - 1, maxX + 2);
    const endY = Math.min(height - 1, maxY + 2);
    for (let y = insetY; y <= endY && !containsHighlight; y += 1) {
      for (let x = insetX; x <= endX; x += 1) {
        const index = (y * width + x) * 4;
        if (data[index + 3] < 18) continue;
        const red = data[index];
        const green = data[index + 1];
        const blue = data[index + 2];
        const lightness = red * 0.299 + green * 0.587 + blue * 0.114;
        const chroma = Math.max(red, green, blue) - Math.min(red, green, blue);
        if (lightness > 184 && chroma < 52) {
          containsHighlight = true;
          break;
        }
      }
    }
    if (!containsHighlight) continue;
    for (let index = 0; index < queueEnd; index += 1) eyeMask[queue[index]] = 1;
  }

  return eyeMask;
}

function createShadowSkinPreview(sprite) {
  const spriteWidth = sprite.naturalWidth || sprite.width;
  const spriteHeight = sprite.naturalHeight || sprite.height;
  if (!spriteWidth || !spriteHeight) return sprite;

  const cached = shadowSkinPreviewCache.get(sprite);
  if (cached) return cached;

  const canvas = document.createElement("canvas");
  canvas.width = spriteWidth;
  canvas.height = spriteHeight;
  const context = canvas.getContext("2d", { willReadFrequently: true });
  context.drawImage(sprite, 0, 0);
  const pixels = context.getImageData(0, 0, canvas.width, canvas.height);
  const eyeMask = sprite === mouseSprite
    ? null
    : createShadowEyeMask(pixels.data, canvas.width, canvas.height);

  for (let index = 0; index < pixels.data.length; index += 4) {
    if (pixels.data[index + 3] < 18) continue;
    const pixelIndex = index / 4;
    const x = pixelIndex % canvas.width;
    const y = Math.floor(pixelIndex / canvas.width);
    const normalizedX = x / canvas.width;
    const normalizedY = y / canvas.height;
    const red = pixels.data[index];
    const green = pixels.data[index + 1];
    const blue = pixels.data[index + 2];
    const lightness = red * 0.299 + green * 0.587 + blue * 0.114;
    const chroma = Math.max(red, green, blue) - Math.min(red, green, blue);
    const leftEye =
      ((normalizedX - 0.158) / 0.041) ** 2 + ((normalizedY - 0.57) / 0.058) ** 2 <= 1;
    const rightEye =
      ((normalizedX - 0.455) / 0.045) ** 2 + ((normalizedY - 0.665) / 0.061) ** 2 <= 1;
    const isEyePixel = sprite === mouseSprite
      ? leftEye || rightEye
      : Boolean(eyeMask?.[pixelIndex]);
    if (isEyePixel && chroma < 58) {
      const eyeShade = Math.max(186, Math.min(252, Math.round(180 + lightness * 0.31)));
      pixels.data[index] = eyeShade;
      pixels.data[index + 1] = eyeShade;
      pixels.data[index + 2] = Math.min(255, eyeShade + 2);
    } else if (chroma < 54) {
      let furShade = Math.max(18, Math.min(126, Math.round(lightness * 0.65 - 45)));
      if (sprite === mouseSprite) {
        const isLightSidePatch =
          normalizedX > 0.1 &&
          normalizedX < 0.7 &&
          normalizedY > 0.76 &&
          normalizedY < 0.98;
        if (isLightSidePatch) furShade = Math.min(furShade, 20);
      }
      pixels.data[index] = furShade;
      pixels.data[index + 1] = Math.min(255, furShade + 1);
      pixels.data[index + 2] = Math.min(255, furShade + 6);
    }
  }

  context.putImageData(pixels, 0, 0);
  shadowSkinPreviewCache.set(sprite, canvas);
  return canvas;
}

function renderShadowShopPreview() {
  if (!shopShadowPreviewEl || !mouseSprite.complete || !mouseSprite.naturalWidth) return;
  const preview = createShadowSkinPreview(mouseSprite);
  if (preview === mouseSprite) {
    shopShadowPreviewEl.src = mouseSprite.src;
    return;
  }
  shopShadowPreviewEl.src = preview.toDataURL("image/png");
}

function createColorSkinPreview(sprite, skinId) {
  const spriteWidth = sprite.naturalWidth || sprite.width;
  const spriteHeight = sprite.naturalHeight || sprite.height;
  const cache = colorSkinPreviewCaches[skinId];
  if (!spriteWidth || !spriteHeight || !cache) return sprite;

  const cached = cache.get(sprite);
  if (cached) return cached;

  const canvas = document.createElement("canvas");
  canvas.width = spriteWidth;
  canvas.height = spriteHeight;
  const context = canvas.getContext("2d", { willReadFrequently: true });
  context.drawImage(sprite, 0, 0);
  const pixels = context.getImageData(0, 0, canvas.width, canvas.height);
  const frameWidth = canvas.width > canvas.height * 1.35 ? canvas.height : canvas.width;

  for (let index = 0; index < pixels.data.length; index += 4) {
    if (pixels.data[index + 3] < 18) continue;
    const pixelIndex = index / 4;
    const x = pixelIndex % canvas.width;
    const y = Math.floor(pixelIndex / canvas.width);
    const normalizedX = (x % frameWidth) / frameWidth;
    const normalizedY = y / canvas.height;
    const red = pixels.data[index];
    const green = pixels.data[index + 1];
    const blue = pixels.data[index + 2];
    const lightness = red * 0.299 + green * 0.587 + blue * 0.114;
    const chroma = Math.max(red, green, blue) - Math.min(red, green, blue);

    // Keep the eyes, whiskers, inner ears, nose and tail from the original artwork.
    if (chroma >= 54 || lightness < 68) continue;

    if (skinId === "pink") {
      pixels.data[index] = Math.min(250, Math.round(150 + lightness * 0.42));
      pixels.data[index + 1] = Math.min(178, Math.round(52 + lightness * 0.43));
      pixels.data[index + 2] = Math.min(208, Math.round(84 + lightness * 0.43));
      continue;
    }

    if (skinId === "orange") {
      pixels.data[index] = Math.min(253, Math.round(135 + lightness * 0.53));
      pixels.data[index + 1] = Math.min(157, Math.round(24 + lightness * 0.45));
      pixels.data[index + 2] = Math.min(62, Math.round(10 + lightness * 0.16));
      continue;
    }

    const diagonal = (normalizedX + normalizedY * 0.58) % 1;
    const sheen = Math.max(0, 1 - Math.abs(diagonal - 0.46) / 0.075);
    pixels.data[index] = Math.min(255, Math.round(148 + lightness * 0.5 + sheen * 28));
    pixels.data[index + 1] = Math.min(236, Math.round(84 + lightness * 0.58 + sheen * 34));
    pixels.data[index + 2] = Math.min(128, Math.round(7 + lightness * 0.23 + sheen * 48));
  }

  context.putImageData(pixels, 0, 0);
  cache.set(sprite, canvas);
  return canvas;
}

function createHelperMouseSprite(sprite) {
  const spriteWidth = sprite.naturalWidth || sprite.width;
  const spriteHeight = sprite.naturalHeight || sprite.height;
  if (!spriteWidth || !spriteHeight) return sprite;
  const cached = helperMouseSpriteCache.get(sprite);
  if (cached) return cached;

  const canvas = document.createElement("canvas");
  canvas.width = spriteWidth;
  canvas.height = spriteHeight;
  const context = canvas.getContext("2d", { willReadFrequently: true });
  context.drawImage(sprite, 0, 0);
  const pixels = context.getImageData(0, 0, canvas.width, canvas.height);
  for (let index = 0; index < pixels.data.length; index += 4) {
    if (pixels.data[index + 3] < 18) continue;
    const red = pixels.data[index];
    const green = pixels.data[index + 1];
    const blue = pixels.data[index + 2];
    const lightness = red * 0.299 + green * 0.587 + blue * 0.114;
    const chroma = Math.max(red, green, blue) - Math.min(red, green, blue);
    if (chroma >= 48 || lightness < 58) continue;
    pixels.data[index] = Math.min(222, Math.round(48 + lightness * 0.72));
    pixels.data[index + 1] = Math.min(151, Math.round(18 + lightness * 0.47));
    pixels.data[index + 2] = Math.min(99, Math.round(8 + lightness * 0.27));
  }
  context.putImageData(pixels, 0, 0);
  helperMouseSpriteCache.set(sprite, canvas);
  return canvas;
}

function drawHelperPacifier(
  ctx,
  center,
  size,
  direction = helperFacingDirection,
  opacity = 1,
) {
  if (direction === "up") return;
  const side = direction === "left" ? -1 : direction === "right" ? 1 : 0;
  const pacifierCenter = {
    x: center.x + size * side * 0.24,
    y: center.y - size * (side ? 0.11 : 0.035),
  };
  const radius = size * 0.085;
  ctx.save();
  ctx.globalAlpha = opacity;
  ctx.shadowColor = "rgba(53, 43, 34, 0.24)";
  ctx.shadowBlur = size * 0.04;
  ctx.fillStyle = "#78bde2";
  ctx.strokeStyle = "#2d739d";
  ctx.lineWidth = Math.max(1, size * 0.026);
  ctx.beginPath();
  ctx.ellipse(pacifierCenter.x, pacifierCenter.y, radius * 1.35, radius, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = "#d8f2ff";
  ctx.beginPath();
  ctx.arc(pacifierCenter.x, pacifierCenter.y, radius * 0.43, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();
  ctx.restore();
}

function drawHelperMouseFrame(
  ctx,
  sprite,
  frameIndex,
  frameCount,
  center,
  size,
  baseline = 0.72,
  opacity = 1,
  direction = helperFacingDirection,
) {
  if (!sprite.complete || !sprite.naturalWidth || !sprite.naturalHeight || opacity <= 0) return;
  const source = createHelperMouseSprite(sprite);
  const sourceWidth = source.width || sprite.naturalWidth;
  const sourceHeight = source.height || sprite.naturalHeight;
  const frameWidth = sourceWidth / frameCount;
  const safeFrame = clamp(Math.floor(frameIndex), 0, frameCount - 1);
  ctx.save();
  ctx.globalAlpha = opacity;
  ctx.shadowColor = "rgba(50, 42, 33, 0.28)";
  ctx.shadowBlur = size * 0.13;
  ctx.shadowOffsetY = size * 0.09;
  ctx.drawImage(
    source,
    safeFrame * frameWidth,
    0,
    frameWidth,
    sourceHeight,
    center.x - size / 2,
    center.y - size * baseline,
    size,
    size,
  );
  ctx.restore();
  drawHelperPacifier(ctx, center, size, direction, opacity);
}

function renderHelperPreview(canvas) {
  if (!canvas || !mouseWalkDownSprite.complete || !mouseWalkDownSprite.naturalWidth) return;
  const context = canvas.getContext("2d");
  context.clearRect(0, 0, canvas.width, canvas.height);
  const previousDirection = helperFacingDirection;
  helperFacingDirection = "down";
  drawHelperMouseFrame(
    context,
    mouseWalkDownSprite,
    3,
    4,
    { x: canvas.width / 2, y: canvas.height * 0.78 },
    canvas.width * 0.92,
    0.72,
  );
  helperFacingDirection = previousDirection;
}

function renderHelperOptionPreview() {
  renderHelperPreview(helperOptionPreviewEl);
  renderHelperPreview(failureHelperPreviewEl);
}

function renderColorShopPreviews() {
  if (!mouseSprite.complete || !mouseSprite.naturalWidth) return;
  for (const [skinId, previewElement] of [
    ["pink", shopPinkPreviewEl],
    ["orange", shopOrangePreviewEl],
    ["gold", shopGoldPreviewEl],
  ]) {
    if (!previewElement) continue;
    const preview = createColorSkinPreview(mouseSprite, skinId);
    previewElement.src = preview === mouseSprite ? mouseSprite.src : preview.toDataURL("image/png");
  }
}

function applySelectedSkinPreviewToPowerIcons() {
  if (document.documentElement) document.documentElement.dataset.skinPreview = selectedMouseSkin;
  document.querySelectorAll(".power-icon img").forEach((icon) => {
    const baseSource = icon.dataset.skinBaseSrc || icon.dataset.src || icon.getAttribute("src");
    if (!baseSource) return;
    icon.dataset.skinBaseSrc = baseSource;
    const requestedSkin = selectedMouseSkin;
    if (requestedSkin === "original") {
      icon.src = baseSource;
      return;
    }
    const source = new Image();
    source.addEventListener("load", () => {
      if (selectedMouseSkin !== requestedSkin) return;
      const preview = createAlbinoSkinPreview(source);
      icon.src = preview === source ? source.src : preview.toDataURL("image/png");
    }, { once: true });
    source.src = baseSource;
  });
}

function selectedMouseSkinSource() {
  if (!mouseSprite.complete || !mouseSprite.naturalWidth) return mouseSprite.src;
  const preview = createAlbinoSkinPreview(mouseSprite);
  return preview === mouseSprite ? mouseSprite.src : preview.toDataURL("image/png");
}

function renderSelectedMouseSkin() {
  const source = selectedMouseSkinSource();
  if (worldMouseImageEl) worldMouseImageEl.src = source;
  if (shopCategorySkinsIconEl) shopCategorySkinsIconEl.src = source;
}

function updateShopSkinSelection() {
  for (const card of shopSkinCards) {
    card.dataset.selected = String(card.dataset.skinId === selectedMouseSkin);
  }
  for (const button of shopSkinSelectButtons) {
    const selected = button.dataset.skinId === selectedMouseSkin;
    button.disabled = selected;
    button.textContent = selected ? "Selected" : "Select";
    button.setAttribute("aria-pressed", String(selected));
  }
}

function selectMouseSkin(skinId) {
  if (!MOUSE_SKIN_IDS.has(skinId) || skinId === selectedMouseSkin) return;
  selectedMouseSkin = skinId;
  try {
    globalThis.localStorage?.setItem(MOUSE_SKIN_STORAGE_KEY, skinId);
  } catch {
    // Skin selection still applies for this session when storage is unavailable.
  }
  updateShopSkinSelection();
  renderSelectedMouseSkin();
  applySelectedSkinPreviewToPowerIcons();
  requestMazeDraw();
}

