function createCell(row, col) {
  return {
    row,
    col,
    active: ACTIVE_CELL_KEYS.has(`${row},${col}`),
    visited: false,
    walls: { top: true, right: true, bottom: true, left: true },
  };
}

function blankMaze() {
  return Array.from({ length: ROWS }, (_, row) =>
    Array.from({ length: COLS }, (_, col) => createCell(row, col)),
  );
}

function createRng(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

function randomUnit() {
  if (globalThis.crypto?.getRandomValues) {
    const value = new Uint32Array(1);
    globalThis.crypto.getRandomValues(value);
    return value[0] / 4294967296;
  }
  return Math.random();
}

function shuffledVariantIndices() {
  const variants = Array.from({ length: VARIANTS_PER_LEVEL }, (_, index) => index);
  for (let index = variants.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(randomUnit() * (index + 1));
    [variants[index], variants[swapIndex]] = [variants[swapIndex], variants[index]];
  }
  return variants;
}

function takeNextVariant(levelIndex) {
  const state = levelVariantStates[levelIndex];
  const config = LEVEL_CONFIGS[levelIndex];
  const hasCuratedPowerMoment = Boolean(
    config?.crystalIntro ||
    config?.tornadoIntro ||
    config?.hammerIntro ||
    config?.fishingIntro ||
    config?.rocketIntro ||
    config?.crystalPractice ||
    config?.tornadoPractice ||
    config?.hammerPractice
  );
  if (state.current < 0 && hasCuratedPowerMoment) {
    state.current = 0;
    state.remaining = shuffledVariantIndices().filter((variant) => variant !== 0);
    return state.current;
  }
  if (!state.remaining.length) {
    state.remaining = shuffledVariantIndices();
    if (state.current >= 0 && state.remaining[0] === state.current) {
      const swapIndex = state.remaining.findIndex((variant) => variant !== state.current);
      [state.remaining[0], state.remaining[swapIndex]] = [state.remaining[swapIndex], state.remaining[0]];
    }
  }

  state.current = state.remaining.shift();
  return state.current;
}

function takeRetryVariant(levelIndex) {
  const state = levelVariantStates[levelIndex];
  if (LEVEL_CONFIGS[levelIndex]?.carrotCount && state.current >= 0) {
    state.remaining = [];
    return state.current;
  }
  state.current = state.current < 0
    ? takeNextVariant(levelIndex)
    : (state.current + 1) % VARIANTS_PER_LEVEL;
  state.remaining = [];
  return state.current;
}

function readSavedControlMode() {
  try {
    const savedMode = globalThis.localStorage?.getItem("mouseMazeControlMode");
    return savedMode === "arrows" ? "arrows" : "swipe";
  } catch {
    return "swipe";
  }
}

function createEmptyPowerInventory() {
  return Object.fromEntries(Object.keys(POWER_CONFIGS).map((key) => [key, 0]));
}

function createStartingPowerInventory() {
  return Object.fromEntries(Object.keys(POWER_CONFIGS).map((key) => [key, 1]));
}

function syncPowerAvailability() {
  crystalAvailable = powerInventory.crystal > 0;
  tornadoAvailable = powerInventory.tornado > 0;
  hammerAvailable = powerInventory.hammer > 0;
  fishingAvailable = powerInventory.fishing > 0;
  rocketAvailable = powerInventory.rocket > 0;
}

function grantIntroPowerIfNeeded(config) {
  const powerKey = config.crystalIntro
    ? "crystal"
    : config.tornadoIntro
      ? "tornado"
      : config.hammerIntro
        ? "hammer"
        : config.fishingIntro
          ? "fishing"
          : config.rocketIntro
            ? "rocket"
          : null;
  if (!powerKey) return;
  let grants = {};
  try {
    grants = JSON.parse(globalThis.localStorage?.getItem(POWER_GRANT_STORAGE_KEY) ?? "{}") ?? {};
  } catch {
    grants = {};
  }
  if (grants[powerKey]) return;
  powerInventory[powerKey] = Math.max(1, powerInventory[powerKey]);
  grants[powerKey] = true;
  syncPowerAvailability();
  saveEconomyState();
  try {
    globalThis.localStorage?.setItem(POWER_GRANT_STORAGE_KEY, JSON.stringify(grants));
  } catch {
    // The free introduction use remains available for this session.
  }
}

function saveEconomyState() {
  try {
    globalThis.localStorage?.setItem(
      ECONOMY_STORAGE_KEY,
      JSON.stringify({ currency, powerInventory }),
    );
  } catch {
    // The current session still works when storage is unavailable.
  }
}

function loadEconomyState() {
  currency = STARTING_CURRENCY;
  powerInventory = createStartingPowerInventory();

  try {
    const saved = globalThis.localStorage?.getItem(ECONOMY_STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (Number.isFinite(parsed.currency)) {
        currency = Math.max(0, Math.floor(parsed.currency));
      }
      for (const key of Object.keys(POWER_CONFIGS)) {
        const savedCount = parsed.powerInventory?.[key];
        if (Number.isFinite(savedCount)) {
          powerInventory[key] = Math.max(0, Math.floor(savedCount));
        }
      }
    }
  } catch {
    currency = STARTING_CURRENCY;
    powerInventory = createStartingPowerInventory();
  }

  syncPowerAvailability();
  saveEconomyState();
}

function updateCurrencyUI() {
  if (currencyCountEl) currencyCountEl.textContent = String(currency);
  currencyStatusEl?.setAttribute(
    "aria-label",
    `${currency} shirt button${currency === 1 ? "" : "s"}`,
  );
  worldCurrencyCountEl.textContent = String(currency);
  worldCurrencyStatusEl.setAttribute(
    "aria-label",
    `${currency} shirt button${currency === 1 ? "" : "s"}`,
  );
}

function updatePowerShopUI() {
  const config = POWER_CONFIGS[shopPowerKey];
  if (!config) return;

  powerShopTitleEl.textContent = `Buy ${config.name}`;
  powerShopIconEl.src = config.image;
  powerShopPriceEl.textContent = String(config.price);
  powerShopBalanceEl.textContent = String(currency);
  powerShopWarningEl.hidden = currency >= config.price;
  powerShopBuyButton.disabled = currency < config.price;
}

function openPowerShop(powerKey) {
  const config = POWER_CONFIGS[powerKey];
  if (!config || gameOver || campaignComplete || !powerControlsEnabled) return;

  if (isPowerTargeting()) cancelActivePower("Power put away while the shop is open.");
  shopPowerKey = powerKey;
  shopReturnFocus = document.querySelector(`#${powerKey}PowerButton`);
  powerShopEl.hidden = false;
  setMovementControlsEnabled(false);
  setPowerControlsEnabled(false);
  updateCurrencyUI();
  updatePowerShopUI();
  powerShopBuyButton.focus?.();
}

function closePowerShop() {
  if (powerShopEl.hidden) return;
  const returnFocus = shopReturnFocus;
  powerShopEl.hidden = true;
  shopPowerKey = null;
  shopReturnFocus = null;

  if (
    !gameOver &&
    !campaignComplete &&
    !crystalRevealing &&
    !fishingCatchAnimating &&
    !rocketFlightAnimation
  ) {
    setMovementControlsEnabled(true);
    setPowerControlsEnabled(true);
  }
  returnFocus?.focus?.();
}

function buySelectedPower() {
  const config = POWER_CONFIGS[shopPowerKey];
  if (!config || currency < config.price) {
    updatePowerShopUI();
    return false;
  }

  currency -= config.price;
  powerInventory[shopPowerKey] += 1;
  syncPowerAvailability();
  saveEconomyState();
  updateCurrencyUI();
  updatePowerUI();
  updatePowerShopUI();
  setMessage(`${config.name} added. ${powerInventory[shopPowerKey]} available.`);
  return true;
}

function consumePower(powerKey) {
  if (!POWER_CONFIGS[powerKey] || powerInventory[powerKey] <= 0) return false;
  clearCrystalForecastReservation();
  powerInventory[powerKey] -= 1;
  syncPowerAvailability();
  saveEconomyState();
  updatePowerUI();
  return true;
}

function handlePowerButton(powerKey, activatePower) {
  if (!isPowerUnlocked(powerKey)) return;
  const activePowerKey = getActivePowerKey();
  if (
    !powerControlsEnabled ||
    gameOver ||
    campaignComplete ||
    mouseMotion ||
    powerTransform ||
    (activePowerKey && activePowerKey !== powerKey)
  ) {
    return;
  }
  if (powerInventory[powerKey] <= 0) {
    openPowerShop(powerKey);
    return;
  }
  activatePower();
}

function initializeEconomySystem() {
  loadEconomyState();
  updateCurrencyUI();
  document.addEventListener?.("visibilitychange", () => {
    if (document.hidden) saveEconomyState();
  });
  globalThis.addEventListener?.("pagehide", saveEconomyState);
}

function saveAttemptState() {
  try {
    globalThis.localStorage?.setItem(
      ATTEMPT_STORAGE_KEY,
      JSON.stringify({ attempts, nextAttemptAt }),
    );
  } catch {
    // The current session still works when storage is unavailable.
  }
}

function syncAttempts(now = Date.now()) {
  attempts = Math.min(MAX_ATTEMPTS, Math.max(0, Math.floor(attempts)));
  let changed = false;

  if (attempts >= MAX_ATTEMPTS) {
    if (nextAttemptAt !== null) changed = true;
    nextAttemptAt = null;
  } else if (!Number.isFinite(nextAttemptAt)) {
    nextAttemptAt = now + ATTEMPT_RECOVERY_MS;
    changed = true;
  } else if (now >= nextAttemptAt) {
    const recovered = Math.floor((now - nextAttemptAt) / ATTEMPT_RECOVERY_MS) + 1;
    attempts = Math.min(MAX_ATTEMPTS, attempts + recovered);
    nextAttemptAt =
      attempts < MAX_ATTEMPTS
        ? nextAttemptAt + recovered * ATTEMPT_RECOVERY_MS
        : null;
    changed = true;
  }

  if (changed) saveAttemptState();
  return changed;
}

function loadAttemptState(now = Date.now()) {
  attempts = MAX_ATTEMPTS;
  nextAttemptAt = null;

  try {
    const saved = globalThis.localStorage?.getItem(ATTEMPT_STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (Number.isFinite(parsed.attempts)) attempts = parsed.attempts;
      if (Number.isFinite(parsed.nextAttemptAt)) nextAttemptAt = parsed.nextAttemptAt;
    }
  } catch {
    attempts = MAX_ATTEMPTS;
    nextAttemptAt = null;
  }

  try {
    const testLives = new URLSearchParams(globalThis.location?.search ?? "").get("testLives");
    if (testLives === "max") {
      attempts = MAX_ATTEMPTS;
      nextAttemptAt = null;
    }
  } catch {
    // Test links remain optional when URL parsing is unavailable.
  }

  syncAttempts(now);
  saveAttemptState();
}

function formatAttemptCountdown(milliseconds) {
  const totalSeconds = Math.max(0, Math.ceil(milliseconds / 1000));
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `${minutes}:${String(seconds).padStart(2, "0")}`;
}

function updateAttemptUI(now = Date.now()) {
  syncAttempts(now);
  attemptCountEl.textContent = String(attempts);
  attemptStatusEl.setAttribute(
    "aria-label",
    `${attempts} attempt${attempts === 1 ? "" : "s"} available`,
  );

  const recovering = attempts < MAX_ATTEMPTS && Number.isFinite(nextAttemptAt);
  attemptTimerEl.hidden = false;
  attemptTimerEl.textContent = recovering
    ? `Next ${formatAttemptCountdown(nextAttemptAt - now)}`
    : "MAX";
  worldAttemptCountEl.textContent = String(attempts);
  worldAttemptTimerEl.textContent = recovering
    ? formatAttemptCountdown(nextAttemptAt - now)
    : "MAX";
  worldAttemptStatusEl.setAttribute(
    "aria-label",
    `${attempts} attempt${attempts === 1 ? "" : "s"} available`,
  );

  if (gameOver && retryCostsAttempt && !campaignComplete) {
    retryButton.disabled = attempts <= 0;
  }
}

function spendAttempt(now = Date.now()) {
  syncAttempts(now);
  if (attempts <= 0) {
    updateAttemptUI(now);
    return false;
  }

  const wasFull = attempts === MAX_ATTEMPTS;
  attempts -= 1;
  if (wasFull || !Number.isFinite(nextAttemptAt)) {
    nextAttemptAt = now + ATTEMPT_RECOVERY_MS;
  }
  saveAttemptState();
  updateAttemptUI(now);
  return true;
}

function initializeAttemptSystem() {
  loadAttemptState();
  updateAttemptUI();

  if (typeof setInterval === "function" && attemptTicker === null) {
    attemptTicker = setInterval(updateAttemptUI, 1000);
  }

  document.addEventListener?.("visibilitychange", () => {
    if (document.hidden) saveAttemptState();
    else updateAttemptUI();
  });
  globalThis.addEventListener?.("pageshow", () => updateAttemptUI());
  globalThis.addEventListener?.("pagehide", saveAttemptState);
}

function saveCampaignState() {
  if (worldReplayFrontier !== null) return;
  const config = LEVEL_CONFIGS[level - 1];
  const retryVariantIndex = levelVariantStates[level - 1]?.current;
  if (
    !config ||
    !Number.isInteger(retryVariantIndex) ||
    retryVariantIndex < 0 ||
    retryVariantIndex >= VARIANTS_PER_LEVEL
  ) {
    return;
  }

  try {
    globalThis.localStorage?.setItem(
      CAMPAIGN_STORAGE_KEY,
      JSON.stringify({
        level,
        retryVariantIndex,
      }),
    );
  } catch {
    // Storage can be unavailable in private browsing; the game remains playable.
  }
}

function restoreCampaignState() {
  let saved;
  try {
    saved = JSON.parse(globalThis.localStorage?.getItem(CAMPAIGN_STORAGE_KEY) ?? "null");
  } catch {
    saved = null;
  }

  const savedLevel = saved?.level;
  const config = LEVEL_CONFIGS[savedLevel - 1];
  const validVariant = (variantIndex) =>
    Number.isInteger(variantIndex) &&
    variantIndex >= 0 &&
    variantIndex < VARIANTS_PER_LEVEL;

  if (
    !config ||
    !validVariant(saved.retryVariantIndex)
  ) {
    try {
      globalThis.localStorage?.removeItem(CAMPAIGN_STORAGE_KEY);
    } catch {
      // Ignore unavailable storage and start a new campaign below.
    }
    return false;
  }

  level = savedLevel;
  levelVariantStates[level - 1].current = saved.retryVariantIndex;
  levelVariantStates[level - 1].remaining = [];
  return true;
}

function defaultWorldProgress() {
  return {
    unlockedLevel: 1,
    completedLevels: Array(LEVEL_CONFIGS.length).fill(false),
  };
}

function loadWorldProgress() {
  worldProgress = defaultWorldProgress();
  try {
    const saved = JSON.parse(
      globalThis.localStorage?.getItem(WORLD_PROGRESS_STORAGE_KEY) ?? "null",
    );
    if (Number.isFinite(saved?.unlockedLevel)) {
      worldProgress.unlockedLevel = clamp(
        Math.floor(saved.unlockedLevel),
        1,
        WORLD_LEVELS.length,
      );
    }
    const savedCompleted = Array.isArray(saved?.completedLevels)
      ? saved.completedLevels
      : Array.isArray(saved?.stars)
        ? saved.stars.map((value) => Number(value) > 0)
        : [];
    worldProgress.completedLevels = Array.from(
      { length: LEVEL_CONFIGS.length },
      (_, index) => Boolean(savedCompleted[index]) || index + 1 < worldProgress.unlockedLevel,
    );
  } catch {
    worldProgress = defaultWorldProgress();
  }

  worldProgress.unlockedLevel = Math.max(
    worldProgress.unlockedLevel,
    clamp(level, 1, WORLD_LEVELS.length),
  );
}

function saveWorldProgress() {
  if (worldJourneyIntroQuery().testingAnotherFeature) return;
  try {
    globalThis.localStorage?.setItem(
      WORLD_PROGRESS_STORAGE_KEY,
      JSON.stringify(worldProgress),
    );
  } catch {
    // Progress remains available for the current session when storage is unavailable.
  }
}

function resetWorldProgress() {
  worldProgress = defaultWorldProgress();
  selectedWorldLevel = 1;
  worldReplayFrontier = null;
  worldJourneyIntroSeenThisSession = false;
  try {
    globalThis.localStorage?.removeItem(WORLD_JOURNEY_INTRO_STORAGE_KEY);
  } catch {
    // The reset still applies for this session when storage is unavailable.
  }
  saveWorldProgress();
}

function worldLevelState(levelNumber) {
  if (worldProgress.completedLevels[levelNumber - 1] || levelNumber < worldProgress.unlockedLevel) {
    return "complete";
  }
  if (levelNumber === worldProgress.unlockedLevel) return "current";
  return "locked";
}

function renderWorldChapterSummary(chapterNumber) {
  const chapter = clamp(chapterNumber, 1, visibleWorldChapterCount);
  const chapterStartIndex = (chapter - 1) * WORLD_CHAPTER_SIZE;
  const chapterEndIndex = Math.min(
    chapterStartIndex + WORLD_CHAPTER_SIZE,
    WORLD_LEVELS.length,
  );
  const chapterLevelTotal = chapterEndIndex - chapterStartIndex;
  const chapterCompletedCount = worldProgress.completedLevels
    .slice(chapterStartIndex, chapterEndIndex)
    .filter(Boolean).length;
  worldChapterLabelEl.textContent = `Section ${chapter}`;
  worldChapterTitleEl.textContent = WORLD_CHAPTER_TITLES[chapter - 1];
  worldProgressTextEl.textContent = `${chapterCompletedCount} / ${chapterLevelTotal}`;
  worldProgressBarEl.style.transform = `scaleX(${chapterCompletedCount / chapterLevelTotal})`;
}

function syncWorldChapterHeaderToScroll() {
  const viewportCenter =
    worldMapEl.scrollTop
    + worldMapEl.clientHeight * 0.5
    - worldMapTrackEl.offsetTop
    - worldFutureReserve;
  const sectionFromTop = clamp(
    Math.floor(viewportCenter / WORLD_CHAPTER_TRACK_HEIGHT),
    0,
    visibleWorldChapterCount - 1,
  );
  renderWorldChapterSummary(visibleWorldChapterCount - sectionFromTop);
}

function worldMouseViewportAnchor() {
  let viewportAnchor = worldMapEl.clientHeight * WORLD_MOUSE_VIEWPORT_ANCHOR;
  if (!levelSheetEl.hidden) {
    const mapBounds = worldMapEl.getBoundingClientRect();
    const sheetBounds = levelSheetEl.getBoundingClientRect();
    const sheetBottomInMap = sheetBounds.bottom - mapBounds.top;
    viewportAnchor = Math.max(viewportAnchor, sheetBottomInMap + 38);
  }
  return Math.max(92, viewportAnchor);
}

function worldMapScrollBounds() {
  const contentMaximum = Math.max(
    0,
    worldMapEl.scrollHeight - worldMapEl.clientHeight,
  );
  const levelNodes = [...worldLevelNodesEl.querySelectorAll(".level-node")];
  const currentLevelButton = worldLevelNodesEl.querySelector(
    '.level-node[data-state="current"]',
  );
  if (!levelNodes.length || !currentLevelButton) {
    return { maximum: contentMaximum, minimum: 0 };
  }

  const trackTop = worldMapTrackEl.offsetTop;
  const highestLevelTop = Math.min(...levelNodes.map((node) => node.offsetTop));
  const futureMargin = Math.min(
    WORLD_FUTURE_SCROLL_MARGIN,
    worldMapEl.clientHeight * 0.3,
  );
  const centeredCurrentTop =
    trackTop
    + currentLevelButton.offsetTop
    - worldMouseViewportAnchor();
  const futureBoundary = trackTop + highestLevelTop - futureMargin;
  const minimum = clamp(
    Math.min(centeredCurrentTop, futureBoundary),
    0,
    contentMaximum,
  );

  const mapBounds = worldMapEl.getBoundingClientRect();
  const navigationBounds =
    document.querySelector(".world-bottom-nav")?.getBoundingClientRect();
  const visibleMapHeight =
    navigationBounds && navigationBounds.top > mapBounds.top
      ? navigationBounds.top - mapBounds.top
      : worldMapEl.clientHeight;
  const startLandmarkBottom =
    trackTop
    + worldStartLandmarkEl.offsetTop
    + worldStartLandmarkEl.offsetHeight;
  const startBoundary =
    startLandmarkBottom
    - visibleMapHeight
    + WORLD_START_SCROLL_MARGIN;
  const maximum = clamp(
    Math.max(minimum, startBoundary),
    minimum,
    contentMaximum,
  );
  return { maximum, minimum };
}

function handleWorldMapScroll() {
  if (
    worldScreenEl.dataset.journeyIntro === "true"
    || worldScreenEl.dataset.levelAdvance === "true"
  ) {
    syncWorldChapterHeaderToScroll();
    return;
  }
  const { maximum, minimum } = worldMapScrollBounds();
  const boundedScrollTop = clamp(worldMapEl.scrollTop, minimum, maximum);
  if (Math.abs(boundedScrollTop - worldMapEl.scrollTop) > 0.5) {
    worldMapEl.scrollTop = boundedScrollTop;
    return;
  }
  syncWorldChapterHeaderToScroll();
}

function centerWorldMouse() {
  if (
    worldScreenEl.dataset.journeyIntro === "true"
    || worldScreenEl.dataset.levelAdvance === "true"
  ) return;
  const currentLevelButton = worldLevelNodesEl.querySelector(
    '.level-node[data-state="current"]',
  );
  if (!currentLevelButton) return;
  const viewportAnchor = worldMouseViewportAnchor();
  const targetTop =
    worldMapTrackEl.offsetTop
    + currentLevelButton.offsetTop
    - viewportAnchor;
  const { maximum, minimum } = worldMapScrollBounds();
  worldMapEl.scrollTop = clamp(
    targetTop,
    minimum,
    maximum,
  );
  syncWorldChapterHeaderToScroll();
}

function worldJourneyIntroQuery() {
  try {
    if (!globalThis.location?.search || typeof URLSearchParams !== "function") {
      return { forced: false, testingAnotherFeature: false };
    }
    const params = new URLSearchParams(globalThis.location.search);
    return {
      forced: params.get("testJourney") === "1",
      testingAnotherFeature:
        params.has("testLevel") ||
        params.has("testUnlock") ||
        params.has("testPower"),
    };
  } catch {
    return { forced: false, testingAnotherFeature: false };
  }
}

function worldTestUnlockQuery() {
  try {
    if (!globalThis.location?.search || typeof URLSearchParams !== "function") return null;
    const value = Number(new URLSearchParams(globalThis.location.search).get("testUnlock"));
    return Number.isInteger(value) && value >= 1 && value <= WORLD_LEVELS.length
      ? value
      : null;
  } catch {
    return null;
  }
}

function hasSeenWorldJourneyIntro() {
  if (worldJourneyIntroSeenThisSession) return true;
  try {
    return globalThis.localStorage?.getItem(WORLD_JOURNEY_INTRO_STORAGE_KEY) === "seen";
  } catch {
    return false;
  }
}

function markWorldJourneyIntroSeen({ forced = false } = {}) {
  worldJourneyIntroSeenThisSession = true;
  if (forced) return;
  try {
    globalThis.localStorage?.setItem(WORLD_JOURNEY_INTRO_STORAGE_KEY, "seen");
  } catch {
    // The intro still remains single-use for this session when storage is unavailable.
  }
}

function shouldPlayWorldJourneyIntro() {
  const query = worldJourneyIntroQuery();
  if (query.forced) {
    const testUnlockLevel = worldTestUnlockQuery();
    return (
      !worldJourneyIntroSeenThisSession
      && (testUnlockLevel === null || testUnlockLevel === 1)
    );
  }
  if (query.testingAnotherFeature || hasSeenWorldJourneyIntro()) return false;
  return (
    worldProgress.unlockedLevel === 1 &&
    !worldProgress.completedLevels.some(Boolean)
  );
}

async function startWorldJourneyIntro(levelToOpen) {
  const query = worldJourneyIntroQuery();
  markWorldJourneyIntroSeen({ forced: query.forced });
  worldScreenEl.dataset.journeyIntro = "true";
  worldMapEl.setAttribute("aria-busy", "true");

  if (!canAnimateMouseMotion() || typeof worldMouseEl.animate !== "function") {
    worldMouseEl.classList.remove("is-journey-pending");
    delete worldScreenEl.dataset.journeyIntro;
    worldMapEl.removeAttribute("aria-busy");
    openWorldLevelSheet(levelToOpen, { focus: false });
    return;
  }

  const restingScrollTop = worldMapEl.scrollTop;
  const maximumScrollTop = Math.max(
    0,
    worldMapEl.scrollHeight - worldMapEl.clientHeight,
  );
  worldMapEl.scrollTop = Math.min(maximumScrollTop, restingScrollTop + 280);
  syncWorldChapterHeaderToScroll();
  const trackBounds = worldMapTrackEl.getBoundingClientRect();
  const restingBounds = worldMouseEl.getBoundingClientRect();
  const trackWidth = worldMapTrackEl.clientWidth;
  const restingPoint = {
    x: restingBounds.left - trackBounds.left + restingBounds.width / 2,
    y: restingBounds.top - trackBounds.top + restingBounds.height / 2,
  };
  const point = (x, y, offset) => ({
    left: `${(x / 360) * trackWidth}px`,
    offset,
    top: `${restingPoint.y + y}px`,
    transform: "translate(-50%, -50%)",
  });

  worldMouseEl.classList.add("is-journey-intro");
  worldMouseEl.classList.remove("is-journey-pending");
  const journeyAnimation = worldMouseEl.animate(
    [
      point(209, 144, 0),
      point(205, 177, 0.12),
      point(170, 194, 0.28),
      point(124, 190, 0.43),
      point(82, 170, 0.58),
      point(58, 132, 0.72),
      point(59, 91, 0.82),
      point(68, 49, 0.91),
      {
        left: `${restingPoint.x}px`,
        offset: 1,
        top: `${restingPoint.y}px`,
        transform: "translate(-50%, -50%)",
      },
    ],
    {
      delay: 420,
      duration: 2200,
      easing: "linear",
      fill: "both",
    },
  );
  worldJourneyIntroAnimation = journeyAnimation;

  try {
    await journeyAnimation.finished;
  } catch {
    // A navigation change can cancel the introduction safely.
  }
  if (worldJourneyIntroAnimation !== journeyAnimation) return;
  journeyAnimation.cancel();
  worldJourneyIntroAnimation = null;
  worldMouseEl.classList.remove("is-journey-intro");
  delete worldScreenEl.dataset.journeyIntro;
  worldMapEl.removeAttribute("aria-busy");
  worldMapEl.scrollTo({ top: restingScrollTop, behavior: "smooth" });
  await new Promise((resolve) => setTimeout(resolve, 360));
  openWorldLevelSheet(levelToOpen, { focus: false });
}

function cancelWorldJourneyIntro() {
  const activeAnimation = worldJourneyIntroAnimation;
  worldJourneyIntroAnimation = null;
  activeAnimation?.cancel();
  worldMouseEl.classList.remove("is-journey-intro", "is-journey-pending");
  delete worldScreenEl.dataset.journeyIntro;
  worldMapEl.removeAttribute("aria-busy");
}

function worldLevelTrackPoint(levelNumber) {
  const meta = WORLD_LEVELS[levelNumber - 1];
  if (!meta) return null;
  const chapterIndex = Math.floor((levelNumber - 1) / WORLD_CHAPTER_SIZE);
  return {
    x: (meta.x / 100) * worldMapTrackEl.clientWidth,
    y:
      worldFutureReserve
      + (visibleWorldChapterCount - chapterIndex - 1) * WORLD_CHAPTER_TRACK_HEIGHT
      + (meta.y / 100) * WORLD_CHAPTER_TRACK_HEIGHT,
  };
}

function worldLevelAdvanceAnchors(completedLevel, nextLevel) {
  const start = worldLevelTrackPoint(completedLevel);
  const end = worldLevelTrackPoint(nextLevel);
  if (!start || !end) return [];

  const anchors = [start];
  const completedChapter = Math.floor((completedLevel - 1) / WORLD_CHAPTER_SIZE);
  const nextChapter = Math.floor((nextLevel - 1) / WORLD_CHAPTER_SIZE);
  for (let chapter = completedChapter; chapter < nextChapter; chapter += 1) {
    anchors.push({
      x: worldMapTrackEl.clientWidth / 2,
      y:
        worldFutureReserve
        + (visibleWorldChapterCount - chapter - 1) * WORLD_CHAPTER_TRACK_HEIGHT,
    });
  }
  anchors.push(end);
  return anchors;
}

function sampleWorldLevelAdvancePath(anchors) {
  const samples = [];
  let totalLength = 0;
  let previous = null;

  for (let segment = 0; segment < anchors.length - 1; segment += 1) {
    const start = anchors[segment];
    const end = anchors[segment + 1];
    const middleY = (start.y + end.y) / 2;
    const steps = 18;
    for (let step = segment === 0 ? 0 : 1; step <= steps; step += 1) {
      const progress = step / steps;
      const inverse = 1 - progress;
      const x =
        inverse ** 3 * start.x
        + 3 * inverse ** 2 * progress * start.x
        + 3 * inverse * progress ** 2 * end.x
        + progress ** 3 * end.x;
      const y =
        inverse ** 3 * start.y
        + 3 * inverse ** 2 * progress * middleY
        + 3 * inverse * progress ** 2 * middleY
        + progress ** 3 * end.y;
      if (previous) totalLength += Math.hypot(x - previous.x, y - previous.y);
      const sample = { x, y, length: totalLength };
      samples.push(sample);
      previous = sample;
    }
  }

  return { samples, totalLength };
}

function worldLevelAdvanceScrollTop(point) {
  const contentMaximum = Math.max(0, worldMapEl.scrollHeight - worldMapEl.clientHeight);
  return clamp(
    worldMapTrackEl.offsetTop + point.y - worldMouseViewportAnchor(),
    0,
    contentMaximum,
  );
}

function cancelWorldLevelAdvance() {
  const activeAnimation = worldLevelAdvanceAnimation;
  worldLevelAdvanceAnimation = null;
  activeAnimation?.cancel();
  if (worldLevelAdvanceScrollTimer !== null) {
    clearTimeout(worldLevelAdvanceScrollTimer);
    worldLevelAdvanceScrollTimer = null;
  }
  worldMouseEl.classList.remove("is-level-advance", "is-level-advance-pending");
  delete worldScreenEl.dataset.levelAdvance;
  worldMapEl.removeAttribute("aria-busy");
}

async function startWorldLevelAdvance(completedLevel, nextLevel) {
  const anchors = worldLevelAdvanceAnchors(completedLevel, nextLevel);
  if (
    anchors.length < 2
    || !canAnimateMouseMotion()
    || typeof worldMouseEl.animate !== "function"
  ) {
    cancelWorldLevelAdvance();
    openWorldLevelSheet(nextLevel, { focus: false });
    return;
  }

  const { samples, totalLength } = sampleWorldLevelAdvancePath(anchors);
  if (!samples.length || totalLength <= 0) {
    cancelWorldLevelAdvance();
    openWorldLevelSheet(nextLevel, { focus: false });
    return;
  }

  const startScrollTop = worldLevelAdvanceScrollTop(anchors[0]);
  const endScrollTop = worldLevelAdvanceScrollTop(anchors.at(-1));
  worldMapEl.scrollTop = startScrollTop;
  syncWorldChapterHeaderToScroll();

  const keyframes = samples.map((sample) => {
    const offset = sample.length / totalLength;
    const exitNode = clamp(offset / 0.12, 0, 1);
    const enterNode = clamp((offset - 0.86) / 0.14, 0, 1);
    const translateX = -118 + exitNode * 68 - enterNode * 68;
    return {
      left: `${sample.x}px`,
      offset,
      top: `${sample.y}px`,
      transform: `translate(${translateX}%, -50%)`,
    };
  });
  const delay = 260;
  const duration = clamp(totalLength * 8.5, 1150, 2100);

  worldMouseEl.classList.add("is-level-advance");
  worldMouseEl.classList.remove("is-level-advance-pending");
  const advanceAnimation = worldMouseEl.animate(keyframes, {
    delay,
    duration,
    easing: "linear",
    fill: "both",
  });
  worldLevelAdvanceAnimation = advanceAnimation;
  worldLevelAdvanceScrollTimer = setTimeout(() => {
    worldLevelAdvanceScrollTimer = null;
    worldMapEl.scrollTo({ top: endScrollTop, behavior: "smooth" });
  }, delay + duration * 0.24);

  try {
    await advanceAnimation.finished;
  } catch {
    // Another navigation action can safely cancel the walk.
  }
  if (worldLevelAdvanceAnimation !== advanceAnimation) return;
  advanceAnimation.cancel();
  worldLevelAdvanceAnimation = null;
  if (worldLevelAdvanceScrollTimer !== null) {
    clearTimeout(worldLevelAdvanceScrollTimer);
    worldLevelAdvanceScrollTimer = null;
  }
  worldMouseEl.classList.remove("is-level-advance");
  delete worldScreenEl.dataset.levelAdvance;
  worldMapEl.removeAttribute("aria-busy");
  worldMapEl.scrollTop = endScrollTop;
  syncWorldChapterHeaderToScroll();
  openWorldLevelSheet(nextLevel, { focus: false });
}

async function requestPortraitOrientationLock() {
  const touchCapable = Boolean(
    globalThis.matchMedia?.("(pointer: coarse)")?.matches
      || Number(globalThis.navigator?.maxTouchPoints) > 0,
  );
  if (
    !touchCapable
    || portraitLockRequestPending
    || !globalThis.screen?.orientation?.lock
  ) return;
  portraitLockRequestPending = true;
  try {
    if (
      document.fullscreenEnabled
      && !document.fullscreenElement
      && globalThis.navigator?.userActivation?.isActive
    ) {
      try {
        await document.documentElement.requestFullscreen({ navigationUI: "hide" });
      } catch {
        // Fullscreen support varies; the orientation request may still succeed.
      }
    }
    await globalThis.screen.orientation.lock("portrait-primary");
  } catch {
    // Browsers only allow orientation locking in supported fullscreen or installed-app contexts.
  } finally {
    portraitLockRequestPending = false;
  }
}

function renderWorldMap() {
  const currentLevel = clamp(worldProgress.unlockedLevel, 1, WORLD_LEVELS.length);
  const currentMeta = WORLD_LEVELS[currentLevel - 1];
  const campaignEndReached = worldProgress.unlockedLevel >= WORLD_LEVELS.length;
  worldFutureReserve = campaignEndReached
    ? Math.max(
      WORLD_CAMPAIGN_END_FUTURE_RESERVE_MIN,
      Math.ceil(worldMapEl.clientHeight * WORLD_CAMPAIGN_END_FUTURE_RESERVE_RATIO),
    )
    : Math.max(
      WORLD_FUTURE_RESERVE_MIN,
      Math.ceil(worldMapEl.clientHeight * 0.74),
    );
  worldMapTrackEl.style.setProperty(
    "--world-future-reserve",
    `${worldFutureReserve}px`,
  );
  if (worldFutureVeilEl) {
    worldFutureVeilEl.dataset.campaignEnd = String(campaignEndReached);
  }
  worldMapEl.dataset.campaignEnd = String(campaignEndReached);
  if (worldComingSoonEl) {
    worldComingSoonEl.hidden = !campaignEndReached;
  }
  const visibleChapterCount = Math.min(
    Math.ceil(WORLD_LEVELS.length / WORLD_CHAPTER_SIZE),
    Math.ceil(worldProgress.unlockedLevel / WORLD_CHAPTER_SIZE),
  );
  visibleWorldChapterCount = visibleChapterCount;
  const visibleStart = 1;
  const visibleEnd = Math.min(
    WORLD_LEVELS.length,
    visibleChapterCount * WORLD_CHAPTER_SIZE,
  );
  const visibleLevels = WORLD_LEVELS.slice(visibleStart - 1, visibleEnd);
  const levelMapY = (levelNumber, meta) => {
    const localY = (meta.y / 100) * WORLD_CHAPTER_TRACK_HEIGHT;
    const chapterIndex = Math.floor((levelNumber - 1) / WORLD_CHAPTER_SIZE);
    return worldFutureReserve
      + (visibleChapterCount - chapterIndex - 1) * WORLD_CHAPTER_TRACK_HEIGHT
      + localY;
  };
  worldStartLandmarkEl?.style.setProperty(
    "--world-start-y",
    `${levelMapY(1, WORLD_LEVELS[0])}px`,
  );

  const currentChapter = Math.floor((currentLevel - 1) / WORLD_CHAPTER_SIZE) + 1;
  renderWorldChapterSummary(currentChapter);
  const worldTrackHeight =
    worldFutureReserve
    + visibleChapterCount * WORLD_CHAPTER_TRACK_HEIGHT
    + WORLD_LEVEL_SHEET_SCROLL_RESERVE;
  worldMapTrackEl.style.height = `${worldTrackHeight}px`;
  worldMapTrackEl.style.minHeight = `${worldTrackHeight}px`;
  document.querySelectorAll(".world-map-section").forEach((section, sectionIndex) => {
    const isVisible = sectionIndex < visibleChapterCount;
    section.style.display = isVisible ? "block" : "none";
    section.style.transform = isVisible
      ? `translateY(${worldFutureReserve + (visibleChapterCount - sectionIndex - 1) * WORLD_CHAPTER_TRACK_HEIGHT}px)`
      : "translateY(0)";
  });
  if (worldSceneryGardenEl) {
    const gardenWorldY = worldFutureReserve
      + (visibleChapterCount - 3) * WORLD_CHAPTER_TRACK_HEIGHT;
    worldSceneryGardenEl.style.setProperty(
      "--scenery-y",
      `${gardenWorldY}px`,
    );
    worldSceneryGardenEl.style.setProperty(
      "--scenery-height",
      `${3 * WORLD_CHAPTER_TRACK_HEIGHT + WORLD_LEVEL_SHEET_SCROLL_RESERVE}px`,
    );
    gardenWorldPathEl?.style.setProperty("--garden-road-y", `${gardenWorldY}px`);
  }
  if (worldSceneryPicnicEl) {
    const picnicVisible = visibleChapterCount >= 4;
    worldSceneryPicnicEl.hidden = !picnicVisible;
    if (picnicVisible) {
      worldSceneryPicnicEl.style.setProperty(
        "--scenery-y",
        `${worldFutureReserve + (visibleChapterCount - 6) * WORLD_CHAPTER_TRACK_HEIGHT}px`,
      );
      worldSceneryPicnicEl.style.setProperty(
        "--scenery-height",
        `${3 * WORLD_CHAPTER_TRACK_HEIGHT}px`,
      );
    }
  }
  if (worldSceneryVegetableEl) {
    const vegetableVisible = visibleChapterCount >= 7;
    worldSceneryVegetableEl.hidden = !vegetableVisible;
    if (vegetableVisible) {
      worldSceneryVegetableEl.style.setProperty(
        "--scenery-y",
        `${worldFutureReserve + (visibleChapterCount - 9) * WORLD_CHAPTER_TRACK_HEIGHT}px`,
      );
      worldSceneryVegetableEl.style.setProperty(
        "--scenery-height",
        `${3 * WORLD_CHAPTER_TRACK_HEIGHT}px`,
      );
    }
  }
  if (worldSceneryKitchenEl) {
    const kitchenVisible = visibleChapterCount >= 10;
    worldSceneryKitchenEl.hidden = !kitchenVisible;
    if (kitchenVisible) {
      worldSceneryKitchenEl.style.setProperty(
        "--scenery-y",
        `${worldFutureReserve + (visibleChapterCount - 12) * WORLD_CHAPTER_TRACK_HEIGHT}px`,
      );
      worldSceneryKitchenEl.style.setProperty(
        "--scenery-height",
        `${3 * WORLD_CHAPTER_TRACK_HEIGHT}px`,
      );
    }
  }
  if (worldThemeTransitionEl) {
    const gardenPicnicBoundary = worldFutureReserve
      + (visibleChapterCount - 3) * WORLD_CHAPTER_TRACK_HEIGHT;
    const transitionVisible = visibleChapterCount >= 4;
    worldThemeTransitionEl.hidden = !transitionVisible;
    if (transitionVisible) {
      worldThemeTransitionEl.style.setProperty(
        "--theme-transition-y",
        `${gardenPicnicBoundary - 360}px`,
      );
    }
  }
  if (worldVegetableTransitionEl) {
    const picnicVegetableBoundary = worldFutureReserve
      + (visibleChapterCount - 6) * WORLD_CHAPTER_TRACK_HEIGHT;
    const transitionVisible = visibleChapterCount >= 7;
    worldVegetableTransitionEl.hidden = !transitionVisible;
    if (transitionVisible) {
      worldVegetableTransitionEl.style.setProperty(
        "--vegetable-transition-y",
        `${picnicVegetableBoundary - 384}px`,
      );
    }
  }
  if (worldKitchenTransitionEl) {
    const vegetableKitchenBoundary = worldFutureReserve
      + (visibleChapterCount - 9) * WORLD_CHAPTER_TRACK_HEIGHT;
    const transitionVisible = visibleChapterCount >= 10;
    worldKitchenTransitionEl.hidden = !transitionVisible;
    if (transitionVisible) {
      worldKitchenTransitionEl.style.setProperty(
        "--kitchen-transition-y",
        `${vegetableKitchenBoundary - 460}px`,
      );
    }
  }

  worldLevelNodesEl.replaceChildren();
  let currentLevelButton = null;
  visibleLevels.forEach((meta, localIndex) => {
    const levelNumber = visibleStart + localIndex;
    const state = worldLevelState(levelNumber);
    const button = document.createElement("button");
    const number = document.createElement("strong");
    button.type = "button";
    button.className = "level-node";
    button.dataset.level = String(levelNumber);
    button.dataset.state = state;
    button.style.setProperty("--node-x", `${meta.x}%`);
    button.style.setProperty("--node-y", `${levelMapY(levelNumber, meta)}px`);
    button.disabled = state === "locked";
    button.setAttribute(
      "aria-label",
      state === "locked"
        ? `Level ${levelNumber}, locked`
        : state === "current"
          ? `Level ${levelNumber}, current level`
          : `Level ${levelNumber}, complete`,
    );
    number.textContent = String(levelNumber);
    button.append(number);
    if (state === "complete") {
      const completionBadge = document.createElement("span");
      completionBadge.className = "level-completion-badge";
      completionBadge.setAttribute("aria-hidden", "true");
      completionBadge.textContent = "\u2713";
      button.append(completionBadge);
    }
    if (state === "locked") {
      const lock = document.createElement("span");
      const lockSvg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
      const lockBody = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      const lockShackle = document.createElementNS("http://www.w3.org/2000/svg", "path");
      lock.className = "power-lock level-lock-icon";
      lock.setAttribute("aria-hidden", "true");
      lockSvg.setAttribute("viewBox", "0 0 24 24");
      lockBody.setAttribute("x", "5");
      lockBody.setAttribute("y", "10");
      lockBody.setAttribute("width", "14");
      lockBody.setAttribute("height", "11");
      lockBody.setAttribute("rx", "2");
      lockShackle.setAttribute("d", "M8 10V7a4 4 0 0 1 8 0v3");
      lockSvg.append(lockBody, lockShackle);
      lock.append(lockSvg);
      button.append(lock);
    } else {
      const selectWorldLevel = () => {
        cancelWorldJourneyIntro();
        cancelWorldLevelAdvance();
        openWorldLevelSheet(levelNumber);
      };
      button.addEventListener("pointerdown", (event) => {
        if (!event.isPrimary || (event.pointerType === "mouse" && event.button !== 0)) {
          return;
        }
        event.preventDefault();
        selectWorldLevel();
      });
      button.addEventListener("click", (event) => {
        if (event.detail !== 0) return;
        selectWorldLevel();
      });
    }
    if (state === "current") currentLevelButton = button;
    worldLevelNodesEl.append(button);
  });

  worldMouseEl.style.setProperty("--node-x", `${currentMeta.x}%`);
  worldMouseEl.style.setProperty(
    "--node-y",
    `${levelMapY(currentLevel, currentMeta)}px`,
  );
  requestAnimationFrame(() => {
    if (!currentLevelButton) return;
    centerWorldMouse();
  });
}

