function cancelActivePower(message) {
  const activePowerKey = getActivePowerKey();
  if (!activePowerKey || powerTransform) return;
  powerPointerStart = null;
  setMessage(`${POWER_CONFIGS[activePowerKey].name} is changing back...`);
  startPowerTransformation(activePowerKey, "out", () => {
    setMovementControlsEnabled(true);
    setMessage(message);
  });
}

function shuffle(items, rng) {
  const copy = [...items];
  for (let i = copy.length - 1; i > 0; i -= 1) {
    const j = Math.floor(rng() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

function startForVariant(config, variantIndex) {
  return {
    ...START_CORNERS[(config.startOffset + variantIndex) % START_CORNERS.length],
  };
}

function initialFacingForStart(start) {
  return start.col === 0 ? "right" : "left";
}

function carveMaze(grid, rng, start) {
  const stack = [grid[start.row][start.col]];
  grid[start.row][start.col].visited = true;

  while (stack.length) {
    const current = stack[stack.length - 1];
    const options = shuffle(DIRS, rng).filter((dir) => {
      const row = current.row + dir.row;
      const col = current.col + dir.col;
      return isInside(row, col) && !grid[row][col].visited;
    });

    if (!options.length) {
      stack.pop();
      continue;
    }

    const dir = options[0];
    const next = grid[current.row + dir.row][current.col + dir.col];
    current.walls[dir.wall] = false;
    next.walls[dir.opposite] = false;
    next.visited = true;
    stack.push(next);
  }
}

function carveKruskalMaze(grid, rng) {
  const cellCount = ROWS * COLS;
  const parents = Array.from({ length: cellCount }, (_, index) => index);
  const ranks = Array(cellCount).fill(0);
  const edges = [];

  const find = (index) => {
    let root = index;
    while (parents[root] !== root) root = parents[root];
    while (parents[index] !== index) {
      const next = parents[index];
      parents[index] = root;
      index = next;
    }
    return root;
  };

  const union = (first, second) => {
    const firstRoot = find(first);
    const secondRoot = find(second);
    if (firstRoot === secondRoot) return false;
    if (ranks[firstRoot] < ranks[secondRoot]) parents[firstRoot] = secondRoot;
    else if (ranks[firstRoot] > ranks[secondRoot]) parents[secondRoot] = firstRoot;
    else {
      parents[secondRoot] = firstRoot;
      ranks[firstRoot] += 1;
    }
    return true;
  };

  for (let row = 0; row < ROWS; row += 1) {
    for (let col = 0; col < COLS; col += 1) {
      if (!isInside(row, col)) continue;
      if (isInside(row, col + 1)) edges.push({ row, col, dir: DIRS[1] });
      if (isInside(row + 1, col)) edges.push({ row, col, dir: DIRS[2] });
    }
  }

  for (const edge of shuffle(edges, rng)) {
    const nextRow = edge.row + edge.dir.row;
    const nextCol = edge.col + edge.dir.col;
    const currentIndex = edge.row * COLS + edge.col;
    const nextIndex = nextRow * COLS + nextCol;
    if (!union(currentIndex, nextIndex)) continue;
    grid[edge.row][edge.col].walls[edge.dir.wall] = false;
    grid[nextRow][nextCol].walls[edge.dir.opposite] = false;
  }

  for (const row of grid) {
    for (const cell of row) cell.visited = cell.active;
  }
}

function addLoops(grid, count, rng) {
  let opened = 0;
  let attempts = 0;
  while (opened < count && attempts < 220) {
    attempts += 1;
    const row = Math.floor(rng() * ROWS);
    const col = Math.floor(rng() * COLS);
    const dir = DIRS[Math.floor(rng() * DIRS.length)];
    const nextRow = row + dir.row;
    const nextCol = col + dir.col;
    if (!isInside(row, col) || !isInside(nextRow, nextCol) || !grid[row][col].walls[dir.wall]) continue;
    grid[row][col].walls[dir.wall] = false;
    grid[nextRow][nextCol].walls[dir.opposite] = false;
    opened += 1;
  }
}

function isInside(row, col) {
  return (
    row >= 0 &&
    row < ROWS &&
    col >= 0 &&
    col < COLS &&
    ACTIVE_CELL_KEYS.has(`${row},${col}`)
  );
}

function neighbors(grid, cell) {
  return DIRS.flatMap((dir) => {
    const row = cell.row + dir.row;
    const col = cell.col + dir.col;
    if (!isInside(row, col) || cell.walls[dir.wall]) return [];
    return [{ row, col, dir: dir.key }];
  });
}

function findShortestPathFrom(grid, start, target, blockedEdges = new Set()) {
  const pathGrid = runtimePathfindingGrid(grid);
  const queue = [{ row: start.row, col: start.col, path: [{ ...start }] }];
  const seen = new Set([keyOf(start)]);

  while (queue.length) {
    const current = queue.shift();
    if (current.row === target.row && current.col === target.col) return current.path;

    for (const next of neighbors(pathGrid, pathGrid[current.row][current.col])) {
      const key = keyOf(next);
      const edge = edgeKey(current, next);
      if (blockedEdges.has(edge) || seen.has(key)) continue;
      seen.add(key);
      queue.push({
        row: next.row,
        col: next.col,
        path: [...current.path, { row: next.row, col: next.col }],
      });
    }
  }

  return [];
}

function findShortestPath(grid, target, blockedEdges = new Set(), start = levelStart) {
  return findShortestPathFrom(grid, start, target, blockedEdges);
}

function joinPaths(firstPath, secondPath) {
  if (!firstPath.length || !secondPath.length) return [];
  return [...firstPath, ...secondPath.slice(1)];
}

function bestCheeseRoute(grid, start, targets) {
  if (!targets.length) return null;
  if (targets.length === 1) {
    const path = findShortestPathFrom(grid, start, targets[0]);
    return path.length ? { path, order: [{ ...targets[0] }] } : null;
  }

  let best = null;
  for (let firstIndex = 0; firstIndex < targets.length; firstIndex += 1) {
    const first = targets[firstIndex];
    const remaining = targets.filter((_, index) => index !== firstIndex);
    const firstPath = findShortestPathFrom(grid, start, first);
    if (!firstPath.length) continue;
    const rest = bestCheeseRoute(grid, first, remaining);
    if (!rest) continue;
    const path = joinPaths(firstPath, rest.path);
    if (!best || path.length < best.path.length) {
      best = { path, order: [{ ...first }, ...rest.order] };
    }
  }
  return best;
}

function remainingCheeseTargets() {
  const targets = cheeseTargets.length ? cheeseTargets : exit ? [exit] : [];
  return targets.filter((target) => !cheeseWasCollected(target));
}

function cheeseIdentity(target) {
  return target?.id ?? keyOf(target);
}

function cheeseWasCollected(target) {
  return collectedCheeseKeys.has(cheeseIdentity(target));
}

function rockAt(cell, positions = rockPositions) {
  if (!cell) return null;
  return (
    positions.find((rock) => rock.row === cell.row && rock.col === cell.col) ?? null
  );
}

function isCheeseVisible(target, positions = rockPositions) {
  return !hiddenCheeseKeys.has(keyOf(target)) || !rockAt(target, positions);
}

function cheeseAt(cell) {
  if (!cell) return null;
  return (
    remainingCheeseTargets().find(
      (target) =>
        !target.helperCarried &&
        target.row === cell.row &&
        target.col === cell.col &&
        isCheeseVisible(target),
    ) ?? null
  );
}

function randomCockroachTrigger() {
  return (
    COCKROACH_MIN_TRIGGER_MOVES +
    Math.floor(
      Math.random() *
        (COCKROACH_MAX_TRIGGER_MOVES - COCKROACH_MIN_TRIGGER_MOVES + 1),
    )
  );
}

function cockroachActionLimit() {
  const config = currentLevelConfig();
  const mode = config.cockroachMode;
  if (!mode) return 0;
  if (mode === "single") return 1;
  return config.activeAdversities?.length > 1
    ? COCKROACH_REPEAT_ACTION_LIMIT - 1
    : COCKROACH_REPEAT_ACTION_LIMIT;
}

function resetCockroachRun() {
  clearCockroachAnimation();
  cockroachMovesSinceAction = 0;
  cockroachNextTrigger = activeVariantAdversityPlan?.cockroachInitialTrigger ??
    randomCockroachTrigger();
  cockroachActionsUsed = 0;
  cockroachDefeated = false;
}

function cockroachHardObstacleAt(cell, movingBottleId = null, relocatedBottle = null) {
  if (!cell) return true;
  const cellKey = keyOf(cell);
  if (fragileCellIsCollapsed(cell, true)) return true;
  if (relocatedBottle && cellKey === keyOf(relocatedBottle)) return true;
  if (rockAt(cell) || pieQuarterAt(cell) || carrotPatchAt(cell) || activeTunnelAt(cell)) {
    return true;
  }
  if (car && cellKey === keyOf(car)) return true;
  return milkBottles.some(
    (bottle) => bottle.id !== movingBottleId && keyOf(bottle) === cellKey,
  );
}

function cockroachCellIsReachable(from, target, movingBottleId, destination) {
  if (cockroachHardObstacleAt(target, movingBottleId, destination)) return false;
  const queue = [{ ...from }];
  const seen = new Set([keyOf(from)]);

  for (let index = 0; index < queue.length; index += 1) {
    const current = queue[index];
    if (keyOf(current) === keyOf(target)) return true;
    for (const next of neighbors(maze, maze[current.row][current.col])) {
      const nextKey = keyOf(next);
      if (
        seen.has(nextKey) ||
        cockroachHardObstacleAt(next, movingBottleId, destination)
      ) {
        continue;
      }
      seen.add(nextKey);
      queue.push({ row: next.row, col: next.col });
    }
  }
  return false;
}

function relocatedBottleRemainsUsable(bottleId, destination, mouseStart = mouse) {
  return DIRS.some((direction) => {
    const approach = {
      row: destination.row - direction.row,
      col: destination.col - direction.col,
    };
    const spill = {
      row: destination.row + direction.row,
      col: destination.col + direction.col,
    };
    if (
      !isInside(approach.row, approach.col) ||
      !isInside(spill.row, spill.col) ||
      !hasOpenPassageBetween(maze, approach, destination) ||
      !hasOpenPassageBetween(maze, destination, spill) ||
      cockroachHardObstacleAt(spill, bottleId, destination) ||
      Boolean(milkPuddleAt(spill)) ||
      remainingCheeseTargets().some((target) => keyOf(target) === keyOf(spill))
    ) {
      return false;
    }
    return (
      cockroachCellIsReachable(mouseStart, approach, bottleId, destination) &&
      cockroachCellIsReachable(approach, spill, bottleId, destination)
    );
  });
}

function cockroachCanLeaveBottleUsable(bottleId, destination) {
  return relocatedBottleRemainsUsable(bottleId, destination, mouse);
}

function cockroachDestinationOptions() {
  const remaining = remainingCheeseTargets();
  const movableObjectives = [
    ...remaining
      .filter((target) => isCheeseVisible(target))
      .map((target) => ({
        kind: "cheese",
        targetIndex: cheeseTargets.findIndex(
          (candidate) => keyOf(candidate) === keyOf(target),
        ),
        from: { row: target.row, col: target.col },
      })),
    ...milkBottles
      .filter((bottle) => !bottle.knocked && !collectedMilkIds.has(bottle.id))
      .map((bottle) => ({
        kind: "milk",
        bottleId: bottle.id,
        from: { row: bottle.row, col: bottle.col },
      })),
  ];
  const options = [];

  for (const objective of movableObjectives) {
    if (objective.kind === "cheese" && objective.targetIndex < 0) continue;
    for (const jump of COCKROACH_JUMPS) {
      const destination = {
        row: objective.from.row + jump.row,
        col: objective.from.col + jump.col,
      };
      if (!isInside(destination.row, destination.col)) continue;
      const destinationKey = keyOf(destination);
      const occupied =
        destinationKey === keyOf(mouse) ||
        fragileCellIsCollapsed(destination, true) ||
        Boolean(car && destinationKey === keyOf(car)) ||
        Boolean(rockAt(destination)) ||
        Boolean(milkBottleAt(destination)) ||
        Boolean(milkPuddleAt(destination)) ||
        Boolean(pieQuarterAt(destination)) ||
        Boolean(carrotPatchAt(destination)) ||
        remaining.some(
          (candidate) =>
            !(objective.kind === "cheese" && keyOf(candidate) === keyOf(objective.from)) &&
            keyOf(candidate) === destinationKey,
        );
      if (occupied) continue;
      if (
        objective.kind === "milk" &&
        !cockroachCanLeaveBottleUsable(objective.bottleId, destination)
      ) {
        continue;
      }
      const pendingHingedWalls = hingedWalls.filter(
        (wall) => !wall.activated && !wall.destroyed && !wall.moving,
      );
      if (pendingHingedWalls.length) {
        if (objective.kind === "milk") continue;
        const relocatedTargets = remaining.map((target) =>
          keyOf(target) === keyOf(objective.from)
            ? { ...target, ...destination }
            : { ...target },
        );
        const solution = solveHingedPuzzle(
          maze,
          mouse,
          pendingHingedWalls,
          relocatedTargets,
          Math.max(80, movesLeft),
        );
        if (!solution || solution.moves > movesLeft) continue;
      }
      options.push({
        ...objective,
        to: destination,
        direction: jump.key,
        distance: jump.distance,
      });
    }
  }

  return options;
}

function applyCockroachRelocation(animation) {
  if (!animation) return;
  if (animation.kind === "milk") {
    const bottle = milkBottles.find((candidate) => candidate.id === animation.bottleId);
    if (bottle && !bottle.knocked && keyOf(bottle) === keyOf(animation.from)) {
      bottle.row = animation.to.row;
      bottle.col = animation.to.col;
    }
  } else {
    const target = cheeseTargets[animation.targetIndex];
    if (
      target &&
      !cheeseWasCollected(target) &&
      keyOf(target) === keyOf(animation.from)
    ) {
      cheeseTargets[animation.targetIndex] = { ...target, ...animation.to };
    }
  }
  cockroachActionsUsed += 1;
  cockroachMovesSinceAction = 0;
  cockroachNextTrigger =
    crystalReservationDecision("cockroach")?.nextTrigger ?? randomCockroachTrigger();
  syncActiveExit();
}

function finishCockroachAnimation() {
  const animation = cockroachAnimation;
  if (!animation) return;
  applyCockroachRelocation(animation);
  const queuedDirection = animation.queuedDirection;
  cockroachAnimation = null;
  cockroachAnimationFrame = null;
  mazeEl.setAttribute("aria-busy", "false");
  setMovementControlsEnabled(true);
  setPowerControlsEnabled(true);
  setMessage(
    animation.kind === "milk"
      ? "The cockroach moved an unopened milk bottle."
      : "The cockroach carried a cheese to another part of the maze.",
    true,
  );
  render();
  saveCampaignState();
  if (queuedDirection) move(queuedDirection);
}

function cockroachEventOption() {
  const config = currentLevelConfig();
  if (
    !config.cockroachMode ||
    cockroachDefeated ||
    cockroachAnimation ||
    cockroachActionsUsed >= cockroachActionLimit() ||
    cockroachMovesSinceAction < cockroachNextTrigger
  ) {
    return null;
  }
  const options = cockroachDestinationOptions();
  if (!options.length) {
    cockroachMovesSinceAction = 0;
    cockroachNextTrigger =
      crystalReservationDecision("cockroach")?.nextTrigger ?? randomCockroachTrigger();
    return null;
  }
  const reserved = crystalReservationDecision("cockroach")?.option;
  if (reserved) {
    const matching = options.find(
      (option) =>
        option.kind === reserved.kind &&
        keyOf(option.from) === keyOf(reserved.from) &&
        keyOf(option.to) === keyOf(reserved.to),
    );
    if (matching) return matching;
  }
  return options[Math.floor(Math.random() * options.length)];
}

function cockroachVisualCellAtProgress(animation, rawProgress) {
  if (!animation) return null;
  const progress = clamp(rawProgress, 0, 1);
  const from = animation.from;
  const to = animation.to;
  const rowDirection = Math.sign(to.row - from.row);
  const colDirection = Math.sign(to.col - from.col);
  const approach = {
    row: from.row - rowDirection * 0.9,
    col: from.col - colDirection * 0.9,
  };
  const escape = {
    row: to.row + rowDirection * 0.8,
    col: to.col + colDirection * 0.8,
  };
  const mixCell = (first, second, amount) => ({
    row: first.row + (second.row - first.row) * amount,
    col: first.col + (second.col - first.col) * amount,
  });
  if (progress < 0.24) {
    return mixCell(approach, from, smoothStep(progress / 0.24));
  }
  if (progress < 0.78) {
    return mixCell(from, to, smoothStep((progress - 0.24) / 0.54));
  }
  return mixCell(to, escape, smoothStep((progress - 0.78) / 0.22));
}

function startConcurrentCockroachAnimation() {
  const option = cockroachEventOption();
  if (!option) return null;
  cockroachAnimation = {
    ...option,
    queuedDirection: null,
    concurrentHazard: true,
    progress: 0,
    startedAt: null,
  };
  return cockroachAnimation;
}

function finishConcurrentCockroachAnimation(caught) {
  const animation = cockroachAnimation;
  if (!animation?.concurrentHazard) return false;
  if (caught) {
    cockroachDefeated = true;
    cockroachMovesSinceAction = 0;
  } else {
    applyCockroachRelocation(animation);
  }
  cockroachAnimation = null;
  return caught;
}

function animateCockroach(timestamp) {
  if (!cockroachAnimation) return;
  if (cockroachAnimation.startedAt === null) cockroachAnimation.startedAt = timestamp;
  cockroachAnimation.progress = clamp(
    (timestamp - cockroachAnimation.startedAt) / COCKROACH_MOVE_DURATION_MS,
    0,
    1,
  );
  drawMaze();
  if (cockroachAnimation.progress >= 1) finishCockroachAnimation();
  else cockroachAnimationFrame = requestAnimationFrame(animateCockroach);
}

function startCockroachAnimation(option, queuedDirection = null) {
  cockroachAnimation = {
    ...option,
    queuedDirection,
    progress: 0,
    startedAt: null,
  };
  setMovementControlsEnabled(false);
  setPowerControlsEnabled(false);
  mazeEl.setAttribute("aria-busy", "true");
  setMessage(
    option.kind === "milk"
      ? "The cockroach has spotted an unopened milk bottle..."
      : "The cockroach has spotted a cheese...",
  );
  requestMazeDraw();
  if (!canAnimateMouseMotion()) finishCockroachAnimation();
  else cockroachAnimationFrame = requestAnimationFrame(animateCockroach);
}

function maybeStartCockroach(queuedDirection = null) {
  const option = cockroachEventOption();
  if (!option) return false;
  startCockroachAnimation(option, queuedDirection);
  return true;
}

function randomCatPawTrigger() {
  return CAT_PAW_TRIGGER_MOVES[
    Math.floor(Math.random() * CAT_PAW_TRIGGER_MOVES.length)
  ];
}

function catPawThreatOptions() {
  const options = [];
  const addOption = (side, start, cells) => {
    if (cells.length === 6 && cells.every((cell) => isInside(cell.row, cell.col))) {
      options.push({ side, start, cells });
    }
  };

  for (let col = 0; col <= COLS - 2; col += 1) {
    addOption(
      "top",
      col,
      [0, 1, 2].flatMap((row) =>
        [0, 1].map((offset) => ({ row, col: col + offset })),
      ),
    );
    addOption(
      "bottom",
      col,
      [ROWS - 3, ROWS - 2, ROWS - 1].flatMap((row) =>
        [0, 1].map((offset) => ({ row, col: col + offset })),
      ),
    );
  }

  for (let row = 0; row <= ROWS - 2; row += 1) {
    addOption(
      "left",
      row,
      [0, 1].flatMap((offset) =>
        [0, 1, 2].map((col) => ({ row: row + offset, col })),
      ),
    );
    addOption(
      "right",
      row,
      [0, 1].flatMap((offset) =>
        [COLS - 3, COLS - 2, COLS - 1].map((col) => ({ row: row + offset, col })),
      ),
    );
  }

  return options;
}

function catPawThreatContains(threat, cell) {
  return Boolean(
    threat?.cells.some(
      (candidate) => candidate.row === cell.row && candidate.col === cell.col,
    ),
  );
}

function catPawThreatHasTwoMoveEscape(
  grid,
  threat,
  start,
  blocked = () => false,
) {
  return Boolean(catPawEscapePath(grid, threat, start, 2, blocked));
}

function catPawEscapePath(grid, threat, start, steps, blocked = () => false) {
  const queue = [{ cell: { ...start }, depth: 0, path: [{ ...start }] }];
  const seen = new Set([`${keyOf(start)}|0`]);
  for (let index = 0; index < queue.length; index += 1) {
    const current = queue[index];
    if (current.depth === steps) {
      if (!catPawThreatContains(threat, current.cell)) return current.path;
      continue;
    }
    for (const next of neighbors(grid, grid[current.cell.row][current.cell.col])) {
      if (blocked(next)) continue;
      const nextDepth = current.depth + 1;
      const stateKey = `${keyOf(next)}|${nextDepth}`;
      if (seen.has(stateKey)) continue;
      seen.add(stateKey);
      const cell = { row: next.row, col: next.col };
      queue.push({ cell, depth: nextDepth, path: [...current.path, cell] });
    }
  }
  return null;
}

function chooseCatPawThreat() {
  const target = helperThreatTarget("cat");
  const targetingHelper = helperDistractsAdversity("cat");
  const reserved = targetingHelper ? null : crystalReservationDecision("catPawThreats");
  if (reserved?.threat && catPawThreatContains(reserved.threat, target)) {
    return {
      ...cloneCrystalThreat(reserved.threat),
      targetKind: targetingHelper ? "helper" : "mouse",
    };
  }
  const options = catPawThreatOptions();
  if (!options.length) return null;
  const targetingOptions = options.filter((option) =>
    catPawThreatContains(option, target),
  );
  const threateningOptions = targetingHelper
    ? targetingOptions
    : targetingOptions.filter((option) =>
        catPawThreatHasTwoMoveEscape(
          maze,
          option,
          target,
          (cell) => cockroachHardObstacleAt(cell),
        ),
      );
  if (!threateningOptions.length) return null;
  const forcedSidePool = testCatSideFromUrl
    ? threateningOptions.filter((option) => option.side === testCatSideFromUrl)
    : [];
  const testPool = forcedSidePool.length ? forcedSidePool : threateningOptions;
  if (!testPool.length) return null;
  const selected = testPool[Math.floor(Math.random() * testPool.length)];
  return {
    ...selected,
    targetKind: targetingHelper ? "helper" : "mouse",
    cells: selected.cells.map((cell) => ({ ...cell })),
  };
}

function catPawMovesUntilStrike() {
  if (!currentLevelConfig().catPawMode) return Number.POSITIVE_INFINITY;
  return Math.max(0, catPawNextTrigger - catPawMovesSinceStrike);
}

function resetCatPawRun() {
  clearCatPawAnimation();
  mouseCapturedByCat = false;
  catPawMovesSinceStrike = 0;
  catPawNextTrigger = testCatSideFromUrl
    ? 3
    : activeVariantAdversityPlan?.catPawInitialTrigger ??
      crystalReservationDecision("catPawStrikes")?.nextTrigger ??
      randomCatPawTrigger();
  catPawThreat = null;
  catPawStrikePending = false;
}

function advanceCatPawClockAfterMouseMove() {
  if (!currentLevelConfig().catPawMode) return;
  catPawMovesSinceStrike += 1;
  const remaining = catPawMovesUntilStrike();
  if (remaining <= 2 && !catPawThreat) catPawThreat = chooseCatPawThreat();
  if (remaining === 0) catPawStrikePending = true;
  requestMazeDraw();
}

function finishCatPawAnimation() {
  const animation = catPawAnimation;
  if (!animation) return;
  const completedFailureAnimation = animation.caught
    ? { kind: "cat", animation: cloneLevelVariant({ ...animation, progress: 1, startedAt: null }) }
    : null;
  if (animation.caughtCar) car = null;
  commitCatHelperCapture(animation);
  if (animation.caught) mouseCapturedByCat = true;
  const caughtCockroach = finishConcurrentCockroachAnimation(
    animation.caughtCockroach,
  );
  catPawAnimation = null;
  catPawAnimationFrame = null;
  catPawThreat = null;
  catPawStrikePending = false;
  catPawMovesSinceStrike = 0;
  catPawNextTrigger = testCatSideFromUrl
    ? 3
    : crystalReservationDecision("catPawStrikes")?.nextTrigger ?? randomCatPawTrigger();
  mazeEl.setAttribute("aria-busy", "false");
  requestMazeDraw();

  if (animation.caught) {
    rewindFailureAnimation = completedFailureAnimation;
    loseLevel("The cat's paw swept the mouse out of the maze.", "cat");
    return;
  }

  setMovementControlsEnabled(true);
  setPowerControlsEnabled(true);
  setMessage(
    animation.caughtHelper
      ? "The little helper distracted the cat and was swept out of the maze."
      : animation.caughtCar
      ? "The cat's paw swept the remote-control car away."
      : caughtCockroach
        ? "The cat's paw caught the cockroach."
        : "The paw missed. Keep moving before the cat tries again.",
  );
  saveCampaignState();
  resolvePlayerArrival(animation.queuedDirection);
}

function animateCatPaw(timestamp) {
  if (!catPawAnimation) return;
  if (catPawAnimation.startedAt === null) catPawAnimation.startedAt = timestamp;
  catPawAnimation.progress = clamp(
    (timestamp - catPawAnimation.startedAt) / CAT_PAW_STRIKE_DURATION_MS,
    0,
    1,
  );
  if (catPawAnimation.progress >= CAT_PAW_IMPACT_START) {
    commitCatHelperCapture(catPawAnimation);
  }
  if (cockroachAnimation?.concurrentHazard) {
    cockroachAnimation.progress = catPawAnimation.progress;
  }
  drawMaze();
  if (catPawAnimation.progress >= 1) finishCatPawAnimation();
  else catPawAnimationFrame = requestAnimationFrame(animateCatPaw);
}

function commitCatHelperCapture(animation = catPawAnimation) {
  if (!animation?.caughtHelper || animation.helperCaptureCommitted) return false;
  animation.helperCaptureCommitted = captureHelperMouse(
    "cat",
    animation.helperCaptureCell,
  );
  return animation.helperCaptureCommitted;
}

function catPawCaptureTargets(threat) {
  return {
    mouse: Boolean(threat && catPawThreatContains(threat, mouse)),
    helper: Boolean(
      threat && helperIsActive() && catPawThreatContains(threat, helperMouse),
    ),
  };
}

function startCatPawAnimation(queuedDirection = null) {
  const threat = catPawThreat ?? chooseCatPawThreat();
  if (!threat) {
    resetCatPawRun();
    return false;
  }
  startConcurrentCockroachAnimation();
  const cockroachImpactCell = cockroachAnimation?.concurrentHazard
    ? cockroachVisualCellAtProgress(cockroachAnimation, CAT_PAW_IMPACT_START)
    : null;
  const caughtCockroach = Boolean(
    cockroachImpactCell &&
      catPawThreatContains(threat, {
        row: Math.round(cockroachImpactCell.row),
        col: Math.round(cockroachImpactCell.col),
      }),
  );
  const captureTargets = catPawCaptureTargets(threat);
  const caughtHelper = captureTargets.helper;
  const caught = captureTargets.mouse;
  catPawAnimation = {
    threat,
    caught,
    caughtHelper,
    helperCaptureCell: caughtHelper ? { ...helperMouse } : null,
    helperCaptureCommitted: false,
    caughtCar: Boolean(car && catPawThreatContains(threat, car)),
    caughtCockroach,
    queuedDirection,
    progress: 0,
    startedAt: null,
  };
  catPawStrikePending = false;
  if (caught) {
    gameOver = true;
    retryCostsAttempt = true;
  }
  setMovementControlsEnabled(false);
  setPowerControlsEnabled(false);
  controlsPanelEl.hidden = true;
  mazeEl.setAttribute("aria-busy", "true");
  setMessage(
    caught
      ? "The cat has the mouse in its sights..."
      : caughtHelper
        ? "The helper is keeping the cat away from the mouse..."
        : "The cat is striking the warned edge...",
  );
  requestMazeDraw();
  if (!canAnimateMouseMotion()) finishCatPawAnimation();
  else catPawAnimationFrame = requestAnimationFrame(animateCatPaw);
  return true;
}

function maybeStartCatPawStrike(queuedDirection = null) {
  if (finalObjectiveAtMouse()) {
    cancelPendingAdversityStrikesForFinalObjective();
    return false;
  }
  if (
    !currentLevelConfig().catPawMode ||
    !catPawStrikePending ||
    catPawAnimation
  ) {
    return false;
  }
  return startCatPawAnimation(queuedDirection);
}

function randomCrowTrigger() {
  return CROW_TRIGGER_MOVES[
    Math.floor(Math.random() * CROW_TRIGGER_MOVES.length)
  ];
}

function crowCanCatchCell(cell) {
  return isInside(cell.row, cell.col);
}

function crowThreatCells(startRow, startCol, size = 3) {
  return Array.from({ length: size }, (_, rowOffset) =>
    Array.from({ length: size }, (__, colOffset) => ({
      row: startRow + rowOffset,
      col: startCol + colOffset,
    })),
  ).flat();
}

function crowThreatOptions() {
  const options = [];
  for (let row = 0; row <= ROWS - 3; row += 1) {
    for (let col = 0; col <= COLS - 3; col += 1) {
      const cells = crowThreatCells(row, col);
      if (cells.every((cell) => isInside(cell.row, cell.col))) {
        options.push({ startRow: row, startCol: col, cells });
      }
    }
  }
  return options;
}

function crowThreatContains(threat, cell) {
  return Boolean(
    threat?.cells?.some(
      (candidate) => candidate.row === cell.row && candidate.col === cell.col,
    ),
  );
}

function crowThreatCenterCell(threat) {
  if (!threat?.cells?.length) return { ...mouse };
  return threat.cells.reduce(
    (center, cell) => ({
      row: center.row + cell.row / threat.cells.length,
      col: center.col + cell.col / threat.cells.length,
    }),
    { row: 0, col: 0 },
  );
}

function chooseCrowThreat() {
  const target = helperThreatTarget("crow");
  const targetingHelper = helperDistractsAdversity("crow");
  const reserved = targetingHelper ? null : crystalReservationDecision("crowThreats");
  if (reserved?.threat && crowThreatContains(reserved.threat, target)) {
    return {
      ...cloneCrystalThreat(reserved.threat),
      targetKind: targetingHelper ? "helper" : "mouse",
    };
  }
  const options = crowThreatOptions();
  if (!options.length) return null;
  const threateningOptions = options.filter((option) =>
    crowThreatContains(option, target),
  );
  if (!threateningOptions.length) return null;
  const selected = threateningOptions[
    Math.floor(Math.random() * threateningOptions.length)
  ];
  return {
    ...selected,
    targetKind: targetingHelper ? "helper" : "mouse",
    cells: selected.cells.map((cell) => ({ ...cell })),
  };
}

function crowMovesUntilStrike() {
  if (!currentLevelConfig().crowMode) return Number.POSITIVE_INFINITY;
  return Math.max(0, crowNextTrigger - crowMovesSinceStrike);
}

function resetCrowRun() {
  clearCrowAnimation();
  crowMovesSinceStrike = 0;
  crowNextTrigger =
    crystalReservationDecision("crowStrikes")?.nextTrigger ?? randomCrowTrigger();
  crowThreat = null;
  crowStrikePending = false;
  mouseCapturedByCrow = false;
}

function advanceCrowClockAfterMouseMove() {
  if (!currentLevelConfig().crowMode) return;
  crowMovesSinceStrike += 1;
  const remaining = crowMovesUntilStrike();
  if (remaining <= 2 && !crowThreat && !cloudCoversCell(helperThreatTarget("crow"))) {
    crowThreat = chooseCrowThreat();
  }
  if (remaining === 0) {
    if (crowThreat) crowStrikePending = true;
    else resetCrowRun();
  }
  requestMazeDraw();
}

function finishCrowAnimation() {
  const animation = crowAnimation;
  if (!animation) return;
  const completedFailureAnimation = animation.caught
    ? { kind: "crow", animation: cloneLevelVariant({ ...animation, progress: 1, startedAt: null }) }
    : null;
  if (animation.caughtCar) car = null;
  if (animation.caughtHelper) captureHelperMouse("crow", animation.helperCaptureCell);
  const caughtCockroach = finishConcurrentCockroachAnimation(
    animation.caughtCockroach,
  );
  crowAnimation = null;
  crowAnimationFrame = null;
  crowThreat = null;
  crowStrikePending = false;
  crowMovesSinceStrike = 0;
  crowNextTrigger =
    crystalReservationDecision("crowStrikes")?.nextTrigger ?? randomCrowTrigger();
  mazeEl.setAttribute("aria-busy", "false");
  requestMazeDraw();

  if (animation.caught) {
    mouseCapturedByCrow = true;
    rewindFailureAnimation = completedFailureAnimation;
    loseLevel("The crow carried the mouse out of the maze.", "crow");
    return;
  }

  setMovementControlsEnabled(true);
  setPowerControlsEnabled(true);
  setMessage(
    animation.caughtHelper
      ? "The little helper drew the crow away and was carried out of the maze."
      : animation.caughtCar
      ? "The crow carried the remote-control car away."
      : caughtCockroach
        ? "The crow carried the cockroach away."
        : animation.blockedByCloud
          ? "The cloud concealed the mouse from the crow."
          : "The crow missed. Leave the final shadow before it dives again.",
  );
  saveCampaignState();
  resolvePlayerArrival(animation.queuedDirection);
}

function animateCrow(timestamp) {
  if (!crowAnimation) return;
  if (crowAnimation.startedAt === null) crowAnimation.startedAt = timestamp;
  crowAnimation.progress = clamp(
    (timestamp - crowAnimation.startedAt) / CROW_STRIKE_DURATION_MS,
    0,
    1,
  );
  if (cockroachAnimation?.concurrentHazard) {
    cockroachAnimation.progress = crowAnimation.progress;
  }
  drawMaze();
  if (crowAnimation.progress >= 1) finishCrowAnimation();
  else crowAnimationFrame = requestAnimationFrame(animateCrow);
}

function crowCaptureTargets(threat) {
  const mouseInThreat = Boolean(threat && crowThreatContains(threat, mouse));
  const helperInThreat = Boolean(
    threat && helperIsActive() && crowThreatContains(threat, helperMouse),
  );
  const mouseBlockedByCloud = Boolean(mouseInThreat && cloudCoversCell(mouse));
  const helperBlockedByCloud = Boolean(helperInThreat && cloudCoversCell(helperMouse));
  return {
    mouse: mouseInThreat && !mouseBlockedByCloud,
    helper: helperInThreat && !helperBlockedByCloud,
    mouseBlockedByCloud,
    helperBlockedByCloud,
  };
}

function startCrowAnimation(queuedDirection = null) {
  const threat = crowThreat ?? chooseCrowThreat();
  if (!threat) {
    resetCrowRun();
    return false;
  }
  startConcurrentCockroachAnimation();
  const targetsHelper = threat.targetKind === "helper" && helperIsActive();
  const threatTarget = targetsHelper ? helperMouse : mouse;
  const targetedCell = crowThreatContains(threat, threatTarget) ? { ...threatTarget } : null;
  const captureTargets = crowCaptureTargets(threat);
  const caughtHelper = captureTargets.helper;
  const caught = captureTargets.mouse;
  const blockedByCloud = Boolean(
    (captureTargets.mouseBlockedByCloud || captureTargets.helperBlockedByCloud) &&
      !caught &&
      !caughtHelper,
  );
  const carTargeted = Boolean(car && crowThreatContains(threat, car));
  const caughtCar = Boolean(carTargeted && !cloudCoversCell(car));
  const cockroachImpactCell = cockroachAnimation?.concurrentHazard
    ? cockroachVisualCellAtProgress(cockroachAnimation, CROW_IMPACT_START)
    : null;
  const roundedCockroachImpactCell = cockroachImpactCell
    ? {
        row: Math.round(cockroachImpactCell.row),
        col: Math.round(cockroachImpactCell.col),
      }
    : null;
  const caughtCockroach = Boolean(
    roundedCockroachImpactCell &&
      crowThreatContains(threat, roundedCockroachImpactCell) &&
      !cloudCoversCell(roundedCockroachImpactCell),
  );
  crowAnimation = {
    threat,
    flightDiagonal:
      crystalReservationDecision("crowStrikes")?.flightDiagonal ??
      CROW_FLIGHT_DIAGONALS[
        Math.floor(Math.random() * CROW_FLIGHT_DIAGONALS.length)
      ],
    caught,
    caughtHelper,
    helperCaptureCell: caughtHelper ? { ...helperMouse } : null,
    caughtCar,
    caughtCockroach,
    caughtCell: caught ? { ...mouse } : null,
    targetedCell,
    blockedByCloud,
    queuedDirection,
    progress: 0,
    startedAt: null,
  };
  crowStrikePending = false;
  if (caught) {
    gameOver = true;
    retryCostsAttempt = true;
  }
  setMovementControlsEnabled(false);
  setPowerControlsEnabled(false);
  controlsPanelEl.hidden = true;
  mazeEl.setAttribute("aria-busy", "true");
  setMessage(
    caught
      ? "The crow has caught the mouse in the open..."
      : caughtHelper
        ? "The helper drew the crow away from the mouse..."
      : blockedByCloud
        ? `The cloud is concealing the ${targetsHelper ? "helper" : "mouse"} from the crow...`
        : "The crow is diving at the warned squares...",
  );
  requestMazeDraw();
  if (!canAnimateMouseMotion()) finishCrowAnimation();
  else crowAnimationFrame = requestAnimationFrame(animateCrow);
  return true;
}

function maybeStartCrowStrike(queuedDirection = null) {
  if (finalObjectiveAtMouse()) {
    cancelPendingAdversityStrikesForFinalObjective();
    return false;
  }
  if (
    !currentLevelConfig().crowMode ||
    !crowStrikePending ||
    crowAnimation
  ) {
    return false;
  }
  return startCrowAnimation(queuedDirection);
}

const CLOUD_DIRECTIONS = Object.freeze([
  { row: -1, col: 0 },
  { row: 1, col: 0 },
  { row: 0, col: -1 },
  { row: 0, col: 1 },
  { row: -1, col: -1 },
  { row: -1, col: 1 },
  { row: 1, col: -1 },
  { row: 1, col: 1 },
]);

function createCloudPass() {
  const direction = CLOUD_DIRECTIONS[
    Math.floor(randomUnit() * CLOUD_DIRECTIONS.length)
  ];
  const padding = (CLOUD_FOOTPRINT_CELLS + 1) / 2;
  const laneInset = Math.floor(CLOUD_FOOTPRINT_CELLS / 2);
  const laneRow =
    laneInset + randomUnit() * Math.max(0, ROWS - 1 - laneInset * 2);
  const laneCol =
    laneInset + randomUnit() * Math.max(0, COLS - 1 - laneInset * 2);
  const row = direction.row === 0
    ? laneRow
    : direction.row > 0
      ? -padding
      : ROWS - 1 + padding;
  const col = direction.col === 0
    ? laneCol
    : direction.col > 0
      ? -padding
      : COLS - 1 + padding;
  const travelCells = Math.max(
    direction.row ? ROWS : 0,
    direction.col ? COLS : 0,
  ) + Math.ceil(padding * 2);
  return {
    row,
    col,
    direction: { ...direction },
    stepsTaken: 0,
    travelCells,
  };
}

function currentCloudVisualState() {
  if (!cloud) return null;
  if (!cloudAnimation) return { row: cloud.row, col: cloud.col };
  const progress = smoothStep(clamp(cloudAnimation.progress, 0, 1));
  return {
    row:
      cloudAnimation.from.row +
      (cloudAnimation.to.row - cloudAnimation.from.row) * progress,
    col:
      cloudAnimation.from.col +
      (cloudAnimation.to.col - cloudAnimation.from.col) * progress,
  };
}

function cloudCoversCell(cell) {
  const visual = currentCloudVisualState();
  if (!visual || !cell) return false;
  const halfFootprint = CLOUD_FOOTPRINT_CELLS / 2;
  return (
    Math.abs(cell.row - visual.row) < halfFootprint &&
    Math.abs(cell.col - visual.col) < halfFootprint
  );
}

function clearCloudRun() {
  if (cloudStepTimer !== null) clearTimeout(cloudStepTimer);
  if (cloudAnimationFrame !== null) cancelAnimationFrame(cloudAnimationFrame);
  cloudStepTimer = null;
  cloudAnimationFrame = null;
  cloudAnimation = null;
  cloud = null;
  cloudIdleStepsRemaining = 0;
}

function scheduleCloudStep() {
  if (
    !cloud ||
    cloudStepTimer !== null ||
    cloudAnimation ||
    cloudIdleStepsRemaining <= 0 ||
    gameOver ||
    campaignComplete
  ) {
    return;
  }
  cloudStepTimer = setTimeout(() => {
    cloudStepTimer = null;
    startCloudStep();
  }, CLOUD_STEP_INTERVAL_MS);
}

function finishCloudStep() {
  if (!cloud || !cloudAnimation) return;
  cloud.row = cloudAnimation.to.row;
  cloud.col = cloudAnimation.to.col;
  cloud.stepsTaken += 1;
  cloudIdleStepsRemaining = Math.max(0, cloudIdleStepsRemaining - 1);
  cloudAnimation = null;
  cloudAnimationFrame = null;
  if (cloud.stepsTaken >= cloud.travelCells) cloud = createCloudPass();
  requestMazeDraw();
  scheduleCloudStep();
}

function animateCloudStep(timestamp) {
  if (!cloudAnimation) return;
  if (cloudAnimation.startedAt === null) cloudAnimation.startedAt = timestamp;
  cloudAnimation.progress = clamp(
    (timestamp - cloudAnimation.startedAt) / CLOUD_MOVE_DURATION_MS,
    0,
    1,
  );
  drawMaze();
  if (cloudAnimation.progress >= 1) finishCloudStep();
  else cloudAnimationFrame = requestAnimationFrame(animateCloudStep);
}

function startCloudStep() {
  if (!cloud || cloudAnimation || cloudIdleStepsRemaining <= 0 || gameOver) return;
  cloudAnimation = {
    from: { row: cloud.row, col: cloud.col },
    to: {
      row: cloud.row + cloud.direction.row,
      col: cloud.col + cloud.direction.col,
    },
    progress: 0,
    startedAt: null,
  };
  requestMazeDraw();
  if (!canAnimateMouseMotion()) {
    cloudAnimation.progress = 1;
    finishCloudStep();
    return;
  }
  cloudAnimationFrame = requestAnimationFrame(animateCloudStep);
}

function startCloudRun() {
  clearCloudRun();
  if (!currentLevelConfig().cloudMode || gameOver || campaignComplete) return;
  cloud = createCloudPass();
  cloudIdleStepsRemaining = CLOUD_MAX_IDLE_STEPS;
  requestMazeDraw();
  scheduleCloudStep();
}

function noteCloudPlayerAction() {
  if (!cloud || !currentLevelConfig().cloudMode || gameOver) return;
  cloudIdleStepsRemaining = CLOUD_MAX_IDLE_STEPS;
  scheduleCloudStep();
}

function waterIsActive() {
  return Boolean(currentLevelConfig().waterMode);
}

function cellFromKey(key) {
  const [row, col] = String(key).split(",").map(Number);
  return { row, col };
}

function projectedRockPositions(rockPush = null) {
  if (!rockPush) return rockPositions;
  return rockPositions.map((rock) =>
    rock.id === rockPush.id
      ? { ...rock, row: rockPush.to.row, col: rockPush.to.col }
      : rock,
  );
}

function movableObjectiveAt(cell) {
  if (!cell) return null;
  const cheese = remainingCheeseTargets().find(
    (target) =>
      !target.helperCarried &&
      target.row === cell.row &&
      target.col === cell.col,
  );
  if (cheese) {
    return {
      kind: "cheese",
      id: cheeseIdentity(cheese),
      entity: cheese,
    };
  }
  const bottle = milkBottleAt(cell);
  return bottle
    ? { kind: "milk", id: bottle.id, entity: bottle }
    : null;
}

function objectivePushDestinationIsClear(destination, movingObjective, reservedKeys = new Set()) {
  if (!isInside(destination.row, destination.col)) return false;
  const destinationCell = maze[destination.row]?.[destination.col];
  if (
    !destinationCell?.active ||
    reservedKeys.has(keyOf(destination)) ||
    fragileCellIsCollapsed(destination, true)
  ) return false;
  if (
    rockAt(destination) ||
    milkBottleAt(destination) ||
    milkPuddleAt(destination) ||
    pieQuarterAt(destination) ||
    carrotPatchAt(destination) ||
    activeTunnelAt(destination) ||
    fragileCellIsCollapsed(destination, true) ||
    waterCellIsFlooded(destination) ||
    keyOf(mouse) === keyOf(destination) ||
    (car && keyOf(car) === keyOf(destination))
  ) {
    return false;
  }
  return !remainingCheeseTargets().some(
    (target) =>
      cheeseIdentity(target) !== movingObjective.id &&
      keyOf(target) === keyOf(destination),
  );
}

function objectivePushForStep(actorFrom, objectCell, reservedKeys = new Set()) {
  if (!areCardinallyAdjacent(actorFrom, objectCell)) return { blocked: true, push: null };
  const movingObjective = movableObjectiveAt(objectCell);
  if (!movingObjective) return { blocked: false, push: null };
  const rowDelta = objectCell.row - actorFrom.row;
  const colDelta = objectCell.col - actorFrom.col;
  const direction = DIRS.find(
    (candidate) => candidate.row === rowDelta && candidate.col === colDelta,
  );
  const sourceCell = maze[objectCell.row]?.[objectCell.col];
  const destination = {
    row: objectCell.row + rowDelta,
    col: objectCell.col + colDelta,
  };
  if (
    !direction ||
    !sourceCell ||
    sourceCell.walls[direction.wall] ||
    !objectivePushDestinationIsClear(destination, movingObjective, reservedKeys)
  ) {
    return { blocked: true, push: null };
  }
  return {
    blocked: false,
    push: {
      kind: movingObjective.kind,
      id: movingObjective.id,
      from: { row: objectCell.row, col: objectCell.col },
      to: destination,
    },
  };
}

function applyObjectivePush(push) {
  if (!push) return;
  if (push.kind === "cheese") {
    const target = cheeseTargets.find(
      (candidate) => cheeseIdentity(candidate) === push.id,
    );
    if (!target || cheeseWasCollected(target)) return;
    const hidden = hiddenCheeseKeys.delete(keyOf(target));
    target.row = push.to.row;
    target.col = push.to.col;
    if (hidden) hiddenCheeseKeys.add(keyOf(target));
    return;
  }
  if (push.kind === "milk") {
    const bottle = milkBottles.find((candidate) => candidate.id === push.id);
    if (!bottle || bottle.glassDestroyed) return;
    bottle.row = push.to.row;
    bottle.col = push.to.col;
  }
}

function uniqueObjectivePushes(...groups) {
  const pushes = groups.flat().filter(Boolean);
  const seen = new Set();
  return pushes.filter((push) => {
    const identity = `${push.kind}:${push.id}`;
    if (seen.has(identity)) return false;
    seen.add(identity);
    return true;
  });
}

function waterExpansionEdges(floodedKeys = floodedWaterKeys, rocks = rockPositions) {
  const edges = [];
  const seen = new Set();
  for (const floodedKey of floodedKeys) {
    const from = cellFromKey(floodedKey);
    if (fragileCellIsCollapsed(from)) continue;
    const mazeCell = maze[from.row]?.[from.col];
    if (!mazeCell) continue;
    for (const next of neighbors(maze, mazeCell)) {
      const nextKey = keyOf(next);
      if (
        floodedKeys.has(nextKey) ||
        rockAt(next, rocks) ||
        seen.has(nextKey)
      ) continue;
      seen.add(nextKey);
      edges.push({ from, to: { row: next.row, col: next.col } });
    }
  }
  return edges;
}

function waterExpansionKeys(floodedKeys = floodedWaterKeys, rocks = rockPositions) {
  return waterExpansionEdges(floodedKeys, rocks).map(({ to }) => keyOf(to));
}

function waterArrivalMoves(rocks = rockPositions) {
  const arrivalMoves = new Map([[keyOf(waterOrigin), WATER_PREPARATION_MOVES]]);
  const queue = [{ ...waterOrigin }];
  while (queue.length) {
    const current = queue.shift();
    const currentArrival = arrivalMoves.get(keyOf(current));
    if (fragileCellIsCollapsed(current)) continue;
    const mazeCell = maze[current.row]?.[current.col];
    if (!mazeCell) continue;
    for (const next of neighbors(maze, mazeCell)) {
      const nextKey = keyOf(next);
      if (arrivalMoves.has(nextKey) || rockAt(next, rocks)) continue;
      arrivalMoves.set(nextKey, currentArrival + 1);
      queue.push({ row: next.row, col: next.col });
    }
  }
  return arrivalMoves;
}

function findWaterSafePath(start, target, rocks = rockPositions) {
  if (!waterIsActive() || !start || !target) return [];
  const arrivalMoves = waterArrivalMoves(rocks);
  const queue = [{ ...start, path: [{ ...start }] }];
  const earliestVisit = new Map([[keyOf(start), 0]]);
  while (queue.length) {
    const current = queue.shift();
    if (keyOf(current) === keyOf(target)) return current.path;
    const mazeCell = maze[current.row]?.[current.col];
    if (!mazeCell) continue;
    for (const next of neighbors(maze, mazeCell)) {
      const nextKey = keyOf(next);
      const steps = current.path.length;
      const playerArrivalMove = waterMoveCount + steps;
      const floodArrivalMove = arrivalMoves.get(nextKey) ?? Number.POSITIVE_INFINITY;
      if (
        rockAt(next, rocks) ||
        floodedWaterKeys.has(nextKey) ||
        playerArrivalMove >= floodArrivalMove ||
        (earliestVisit.get(nextKey) ?? Number.POSITIVE_INFINITY) <= steps
      ) {
        continue;
      }
      earliestVisit.set(nextKey, steps);
      queue.push({
        row: next.row,
        col: next.col,
        path: [...current.path, { row: next.row, col: next.col }],
      });
    }
  }
  return [];
}

function waterAdvanceForNextMove(rocks = rockPositions) {
  if (!waterIsActive()) return null;
  const moveCount = waterMoveCount + 1;
  if (moveCount < WATER_PREPARATION_MOVES) return { moveCount, newKeys: [], pushes: [] };
  if (moveCount === WATER_PREPARATION_MOVES) {
    return { moveCount, newKeys: [keyOf(waterOrigin)], pushes: [] };
  }
  const edges = waterExpansionEdges(floodedWaterKeys, rocks);
  const newKeys = edges.map(({ to }) => keyOf(to));
  const reservedKeys = new Set([
    ...rocks.map(keyOf),
    ...newKeys,
  ]);
  const pushedIds = new Set();
  const pushes = [];
  for (const edge of edges) {
    const objective = movableObjectiveAt(edge.to);
    if (!objective || pushedIds.has(`${objective.kind}:${objective.id}`)) continue;
    const result = objectivePushForStep(edge.from, edge.to, reservedKeys);
    if (result.blocked || !result.push) continue;
    pushes.push(result.push);
    pushedIds.add(`${objective.kind}:${objective.id}`);
    reservedKeys.add(keyOf(result.push.to));
  }
  return { moveCount, newKeys, pushes };
}

function activeWaterAdvanceVisual() {
  const animation =
    mouseMotion ?? milkKnockAnimation ?? pieBiteAnimation ?? carrotSearchAnimation;
  return animation?.waterAdvance
    ? { advance: animation.waterAdvance, progress: animation.progress ?? 0 }
    : null;
}

function waterObjectiveDefeatMessage() {
  if (!waterIsActive()) return null;
  if (floodedWaterKeys.has(keyOf(mouse))) return "The flood caught the mouse.";
  if (remainingCheeseTargets().some((target) => floodedWaterKeys.has(keyOf(target)))) {
    return "The flood reached the cheese.";
  }
  if (
    remainingMilkBottles().some((bottle) => {
      const objectiveCell = bottle.knocked && bottle.spill ? bottle.spill : bottle;
      return floodedWaterKeys.has(keyOf(objectiveCell));
    })
  ) {
    return "The flood reached the milk objective.";
  }
  if (remainingPieQuarters().some((quarter) => {
    const objectiveCell = quarter.helperCarried
      ? helperMouse
      : quarter.helperDeliveredCell ?? quarter;
    return objectiveCell && floodedWaterKeys.has(keyOf(objectiveCell));
  })) {
    return "The flood reached the pie.";
  }
  return null;
}

function commitWaterAdvance(advance, { applyPushes = true } = {}) {
  if (!advance) return null;
  waterMoveCount = advance.moveCount;
  if (applyPushes) {
    for (const push of advance.pushes ?? []) applyObjectivePush(push);
  }
  for (const key of advance.newKeys) floodedWaterKeys.add(key);
  if (helperIsActive() && floodedWaterKeys.has(keyOf(helperMouse))) {
    captureHelperMouse("flood", helperMouse);
  }
  syncWaterDebugDataset();
  return waterObjectiveDefeatMessage();
}

function waterWarningKeys() {
  if (!waterIsActive()) return [];
  if (!floodedWaterKeys.size) return [keyOf(waterOrigin)];
  return waterExpansionKeys();
}

function syncWaterDebugDataset() {
  mazeEl.dataset.testWater = JSON.stringify({
    active: waterIsActive(),
    origin: { ...waterOrigin },
    moveCount: waterMoveCount,
    flooded: [...floodedWaterKeys],
    warning: waterWarningKeys(),
  });
}

function restartWaterAfterTornado() {
  if (!waterIsActive()) return;
  const occupiedKeys = new Set([
    keyOf(mouse),
    ...remainingCheeseTargets().map(keyOf),
    ...milkBottles.filter((bottle) => !bottle.glassDestroyed).map(keyOf),
    ...pieFootprintCells(pie).map(keyOf),
    ...rockPositions.map(keyOf),
    ...activeTunnels().map(keyOf),
    ...(car ? [keyOf(car)] : []),
  ]);
  const candidates = [];
  for (let row = 0; row < ROWS; row += 1) {
    for (let col = 0; col < COLS; col += 1) {
      if (row !== 0 && row !== ROWS - 1 && col !== 0 && col !== COLS - 1) continue;
      const cell = maze[row]?.[col];
      if (
        !cell?.active ||
        occupiedKeys.has(`${row},${col}`) ||
        keyOf(cell) === keyOf(waterOrigin)
      ) {
        continue;
      }
      candidates.push({ row, col });
    }
  }
  if (candidates.length) {
    waterOrigin = { ...candidates[Math.floor(randomUnit() * candidates.length)] };
  }
  waterMoveCount = 0;
  floodedWaterKeys = new Set();
  syncWaterDebugDataset();
}

function waterShouldAnimate() {
  return waterIsActive() && !campaignComplete && !gameOver && !gameShellEl.hidden && !document.hidden;
}

function animateWaterSurface(timestamp) {
  waterAmbientFrame = null;
  if (!waterShouldAnimate()) return;
  waterVisualTime = timestamp;
  if (timestamp - waterLastAmbientDraw >= WATER_AMBIENT_FRAME_MS) {
    waterLastAmbientDraw = timestamp;
    requestMazeDraw();
  }
  waterAmbientFrame = requestAnimationFrame(animateWaterSurface);
}

function ensureWaterSurfaceAnimation() {
  if (!waterShouldAnimate() || waterAmbientFrame) return;
  waterVisualTime = performance.now();
  waterLastAmbientDraw = 0;
  waterAmbientFrame = requestAnimationFrame(animateWaterSurface);
}

function waterCellIsFlooded(cell) {
  return floodedWaterKeys.has(keyOf(cell));
}

function milkBottleAt(cell, bottles = milkBottles) {
  if (!cell) return null;
  return bottles.find(
    (bottle) =>
      !bottle.glassDestroyed &&
      !bottle.helperCarried &&
      bottle.row === cell.row &&
      bottle.col === cell.col,
  ) ?? null;
}

function milkPuddleAt(cell, bottles = milkBottles, collected = collectedMilkIds) {
  if (!cell) return null;
  return bottles.find(
    (bottle) =>
      bottle.knocked &&
      bottle.spill?.row === cell.row &&
      bottle.spill?.col === cell.col &&
      !collected.has(bottle.id),
  ) ?? null;
}

function remainingMilkBottles() {
  return milkBottles.filter((bottle) => !collectedMilkIds.has(bottle.id));
}

function remainingPieQuarters() {
  return pie?.quarters?.filter((quarter) => !eatenPieQuarterIds.has(quarter.id)) ?? [];
}

function isPieCleared() {
  return Boolean(pie) && remainingPieQuarters().length === 0;
}

function pieQuarterAt(cell) {
  if (!cell || !pie || isPieCleared()) return null;
  return pie.quarters.find(
    (quarter) => quarter.row === cell.row && quarter.col === cell.col,
  ) ?? null;
}

function remainingCarrots() {
  return carrotPatches.filter(
    (patch) => patch.hasCarrot && !collectedCarrotIds.has(patch.id),
  );
}

function carrotPatchAt(cell) {
  if (!cell) return null;
  return carrotPatches.find(
    (patch) =>
      !inspectedCarrotPatchIds.has(patch.id) &&
      patch.row === cell.row &&
      patch.col === cell.col,
  ) ?? null;
}

function remainingObjectiveCount() {
  return (
    remainingCheeseTargets().length +
    remainingMilkBottles().length +
    remainingPieQuarters().length +
    remainingCarrots().length
  );
}

function allObjectivesComplete() {
  return remainingObjectiveCount() === 0;
}

function immediateObjectiveAtMouse() {
  const deliveredPieQuarter = remainingPieQuarters().find(
    (quarter) =>
      quarter.helperDeliveredCell &&
      keyOf(quarter.helperDeliveredCell) === keyOf(mouse),
  );
  if (deliveredPieQuarter) return { kind: "pie", target: deliveredPieQuarter };
  const reachedCheese = cheeseAt(mouse);
  if (reachedCheese) return { kind: "cheese", target: reachedCheese };
  const reachedMilk = milkPuddleAt(mouse);
  if (reachedMilk) return { kind: "milk", target: reachedMilk };
  return null;
}

function finalObjectiveAtMouse() {
  if (remainingObjectiveCount() !== 1) return null;
  return immediateObjectiveAtMouse();
}

function cancelPendingAdversityStrikesForFinalObjective() {
  catPawThreat = null;
  catPawStrikePending = false;
  mouseCapturedByCat = false;
  crowThreat = null;
  crowStrikePending = false;
  mouseCapturedByCrow = false;
}

function startImmediateObjectiveAtMouse({ requireFinal = false } = {}) {
  const objective = requireFinal ? finalObjectiveAtMouse() : immediateObjectiveAtMouse();
  if (!objective) return false;
  if (requireFinal) cancelPendingAdversityStrikesForFinalObjective();
  if (objective.kind === "pie") {
    startPieBiteAnimation(
      objective.target,
      { key: mouseFacingDirection },
      { delivered: true },
    );
  } else if (objective.kind === "cheese") {
    startCheeseEatingAnimation(objective.target);
  } else {
    startMilkDrinkAnimation(objective.target);
  }
  return true;
}

function helperIsActive() {
  return Boolean(helperRequestedForRun && helperMouse && !helperCaptured);
}

function helperDistractsAdversity(adversity) {
  return Boolean(
    helperIsActive() &&
      helperTask?.type === "distract" &&
      helperTask.adversity === adversity &&
      (helperTask.turnsRemaining === null || helperTask.turnsRemaining > 0),
  );
}

function helperThreatTarget(adversity) {
  if (adversity === "car") return carPursuitTarget().cell;
  return helperDistractsAdversity(adversity) ? helperMouse : mouse;
}

function syncHelperDebugDataset() {
  if (!mazeEl) return;
  mazeEl.dataset.testHelperPlanner = JSON.stringify({
    active: helperIsActive(),
    captured: helperCaptured,
    mode: helperMode,
    task: helperTask
      ? {
          key: helperTask.key,
          type: helperTask.type,
          kind: helperTask.kind ?? null,
          adversity: helperTask.adversity ?? null,
          target: helperTask.target ? { ...helperTask.target } : null,
          objectiveGoal: helperTask.objectiveGoal
            ? {
                ...helperTask.objectiveGoal,
                cell: { ...helperTask.objectiveGoal.cell },
              }
            : null,
          score: helperTask.score ?? 0,
          age: helperTask.age ?? 0,
          turnsRemaining: helperTask.turnsRemaining ?? null,
        }
      : null,
    intent: helperLastDecision?.intent ?? null,
    decision: helperLastDecision,
    cargo: helperCargo,
    recoveryTurns: helperRecoveryTurns,
    cooldowns: helperDistractionCooldowns,
    testedRocks: [...helperTestedRockIds],
    tunnelCooldownTurns: helperTunnelCooldownTurns,
  });
}

function helperObjectiveByIdentity(kind, id) {
  if (kind === "cheese") {
    return cheeseTargets.find((target) => cheeseIdentity(target) === id) ?? null;
  }
  if (kind === "milk") {
    return milkBottles.find((bottle) => bottle.id === id) ?? null;
  }
  if (kind === "pie") {
    return pie?.quarters?.find((quarter) => quarter.id === id) ?? null;
  }
  return null;
}

function helperCellIsBlocked(cell, allowedTargetKey = null) {
  if (!cell || !isInside(cell.row, cell.col)) return true;
  const cellKey = keyOf(cell);
  return Boolean(
    (car && cellKey === keyOf(car)) ||
      milkBottleAt(cell) ||
      rockAt(cell) ||
      pieQuarterAt(cell) ||
      carrotPatchAt(cell) ||
      waterCellIsFlooded(cell),
  );
}

function findHelperPath(start, target, allowedTargetKey = null) {
  if (!start || !target) return [];
  const queue = [{ row: start.row, col: start.col, path: [{ ...start }] }];
  const seen = new Set([keyOf(start)]);
  const waterArrivals = waterIsActive() ? waterArrivalMoves() : null;
  const stepIsSafe = (cell, step) => {
    if (!waterArrivals) return true;
    const arrival = waterArrivals.get(keyOf(cell)) ?? Number.POSITIVE_INFINITY;
    return !waterCellIsFlooded(cell) && waterMoveCount + step < arrival;
  };
  while (queue.length) {
    const current = queue.shift();
    if (keyOf(current) === keyOf(target)) return current.path;
    const mazeCell = maze[current.row]?.[current.col];
    if (!mazeCell) continue;
    for (const next of neighbors(maze, mazeCell)) {
      const nextKey = keyOf(next);
      const nextStep = current.path.length;
      if (
        seen.has(nextKey) ||
        helperCellIsBlocked(next, allowedTargetKey) ||
        !stepIsSafe(next, nextStep)
      ) continue;
      seen.add(nextKey);
      queue.push({
        row: next.row,
        col: next.col,
        path: [...current.path, { row: next.row, col: next.col }],
      });
    }

  }
  return [];
}

function helperDistanceBetween(start, target) {
  const path = findHelperPath(start, target, keyOf(target));
  return path.length ? path.length - 1 : ROWS * COLS + 20;
}

function carPursuitDistance(from, target) {
  if (!from || !target) return Number.POSITIVE_INFINITY;
  const blockedKeys = new Set([
    ...rockPositions.map(keyOf),
    ...(pie && !isPieCleared() ? pieFootprintCells(pie).map(keyOf) : []),
    ...floodedWaterKeys,
    ...collapsedFragileTileKeys,
  ]);
  blockedKeys.delete(keyOf(from));
  blockedKeys.delete(keyOf(target));
  const path = findPathAvoidingCells(maze, from, target, blockedKeys);
  return path.length ? path.length - 1 : Number.POSITIVE_INFINITY;
}

function carPursuitTarget(
  playerCell = mouse,
  helperCell = helperIsActive() ? helperMouse : null,
) {
  if (!car || !helperCell) {
    return {
      kind: "mouse",
      cell: { ...playerCell },
      playerDistance: car ? carPursuitDistance(car, playerCell) : 0,
      helperDistance: Number.POSITIVE_INFINITY,
    };
  }
  const playerDistance = carPursuitDistance(car, playerCell);
  const helperDistance = carPursuitDistance(car, helperCell);
  const helperWinsTie = helperDistractsAdversity("car");
  const targetsHelper =
    helperDistance < playerDistance ||
    (helperDistance === playerDistance && helperWinsTie);
  return {
    kind: targetsHelper ? "helper" : "mouse",
    cell: { ...(targetsHelper ? helperCell : playerCell) },
    playerDistance,
    helperDistance,
  };
}

function helperOpenNeighborCount(cell) {
  const mazeCell = maze[cell.row]?.[cell.col];
  if (!mazeCell) return 0;
  return neighbors(maze, mazeCell).filter((next) => !helperCellIsBlocked(next)).length;
}

function helperCatAttackBandDepth(cell) {
  return Math.min(
    cell.row,
    ROWS - 1 - cell.row,
    cell.col,
    COLS - 1 - cell.col,
  );
}

function helperCatDecoyPath(projectedPlayer) {
  const queue = [{ cell: { ...helperMouse }, path: [{ ...helperMouse }] }];
  const seen = new Set([keyOf(helperMouse)]);
  let targetDepth = null;
  const candidates = [];
  for (let index = 0; index < queue.length; index += 1) {
    const current = queue[index];
    const depth = current.path.length - 1;
    if (targetDepth !== null && depth > targetDepth) break;
    if (helperCatAttackBandDepth(current.cell) <= 2) {
      targetDepth = depth;
      candidates.push(current);
      continue;
    }
    const mazeCell = maze[current.cell.row]?.[current.cell.col];
    if (!mazeCell) continue;
    for (const next of neighbors(maze, mazeCell)) {
      const nextKey = keyOf(next);
      if (seen.has(nextKey) || helperCellIsBlocked(next)) continue;
      seen.add(nextKey);
      queue.push({
        cell: { row: next.row, col: next.col },
        path: [...current.path, { row: next.row, col: next.col }],
      });
    }
  }
  candidates.sort((first, second) => {
    const firstSeparation =
      Math.abs(first.cell.row - projectedPlayer.row) +
      Math.abs(first.cell.col - projectedPlayer.col);
    const secondSeparation =
      Math.abs(second.cell.row - projectedPlayer.row) +
      Math.abs(second.cell.col - projectedPlayer.col);
    return (
      secondSeparation - firstSeparation ||
      helperOpenNeighborCount(second.cell) - helperOpenNeighborCount(first.cell) ||
      keyOf(first.cell).localeCompare(keyOf(second.cell))
    );
  });
  return candidates[0]?.path ?? [];
}

function helperRememberDecoyTarget(cell) {
  if (!cell) return;
  const targetKey = keyOf(cell);
  helperDecoyHistory = helperDecoyHistory.filter((key) => key !== targetKey);
  helperDecoyHistory.push(targetKey);
  if (helperDecoyHistory.length > 5) helperDecoyHistory.shift();
}

function helperExistingDecoyPlan(adversity, projectedPlayer) {
  if (
    helperTask?.type !== "distract" ||
    helperTask.adversity !== adversity ||
    !helperTask.target
  ) {
    return null;
  }
  if (keyOf(helperTask.target) === keyOf(helperMouse)) {
    helperRememberDecoyTarget(helperTask.target);
    return null;
  }
  const path = findHelperPath(helperMouse, helperTask.target, keyOf(helperTask.target));
  if (!path.length) return null;
  return { target: { ...helperTask.target }, path };
}

function helperRemoteDecoyPlan(adversity, projectedPlayer, intent = null) {
  const existing = helperExistingDecoyPlan(adversity, projectedPlayer);
  if (existing) return existing;

  let best = null;
  for (const cell of maze.flat()) {
    if (!cell || cell.active === false || helperCellIsBlocked(cell)) continue;
    const cellKey = keyOf(cell);
    if (cellKey === keyOf(helperMouse) || cellKey === keyOf(projectedPlayer)) continue;
    if (adversity === "crow" && cloudCoversCell(cell)) continue;
    const path = findHelperPath(helperMouse, cell, cellKey);
    if (path.length < 2) continue;
    const playerDistance = helperDistanceBetween(projectedPlayer, cell);
    if (!Number.isFinite(playerDistance)) continue;
    const intentDistance = intent?.cell
      ? Math.abs(cell.row - intent.cell.row) + Math.abs(cell.col - intent.cell.col)
      : playerDistance;
    const carDistance = car ? helperDistanceBetween(car, cell) : 0;
    const recentPenalty = helperDecoyHistory.includes(cellKey) ? 600 : 0;
    const score =
      playerDistance * 46 +
      intentDistance * 12 +
      helperOpenNeighborCount(cell) * 14 +
      Math.min(path.length - 1, 12) * 3 +
      (adversity === "car" ? Math.min(carDistance, 16) * 7 : 0) -
      recentPenalty;
    if (!best || score > best.score || (score === best.score && cellKey < keyOf(best.target))) {
      best = { target: { row: cell.row, col: cell.col }, path, score };
    }
  }
  return best;
}

function helperDistractionObjectiveGoal(projectedPlayer, intent = null) {
  const existing = helperTask?.type === "distract"
    ? helperTask.objectiveGoal
    : null;
  if (existing) {
    const descriptor = helperObjectiveDescriptors().find(
      (candidate) => candidate.key === existing.key,
    );
    if (descriptor) {
      return {
        ...existing,
        cell: { ...existing.cell },
      };
    }
  }

  const candidate = helperFetchCandidates(projectedPlayer, intent)[0];
  if (!candidate?.target) return null;
  return {
    key: `${candidate.kind}:${candidate.id}`,
    kind: candidate.kind,
    id: candidate.id,
    cell: { ...candidate.target },
  };
}

function helperThreatEscapePath(
  adversity,
  projectedPlayer,
  objectiveGoal = helperTask?.objectiveGoal ?? null,
) {
  const threat = adversity === "cat" ? catPawThreat : crowThreat;
  const movesUntilImpact = adversity === "cat"
    ? catPawMovesUntilStrike()
    : crowMovesUntilStrike();
  if (!threat || !Number.isFinite(movesUntilImpact) || movesUntilImpact <= 0) return [];
  const isSafe = adversity === "cat"
    ? (cell) => !catPawThreatContains(threat, cell)
    : (cell) => !crowThreatContains(threat, cell) || cloudCoversCell(cell);
  const goalCell = objectiveGoal?.cell ?? null;
  const unreachableDistance = ROWS * COLS + 20;
  const startGoalDistance = goalCell
    ? helperDistanceBetween(helperMouse, goalCell)
    : unreachableDistance;
  const hasReachableGoal = Boolean(goalCell && startGoalDistance < unreachableDistance);
  if (isSafe(helperMouse) && !hasReachableGoal) return [{ ...helperMouse }];

  const escapesWithoutReentry = (path) => {
    let escaped = isSafe(path[0]);
    for (const cell of path.slice(1)) {
      if (escaped && !isSafe(cell)) return false;
      if (isSafe(cell)) escaped = true;
    }
    return escaped;
  };

  const options = [];
  for (const cell of maze.flat()) {
    if (!cell || cell.active === false || !isSafe(cell) || helperCellIsBlocked(cell)) continue;
    const path = findHelperPath(helperMouse, cell, keyOf(cell));
    const steps = path.length - 1;
    if (!path.length || steps > movesUntilImpact || !escapesWithoutReentry(path)) continue;
    const crossesPlayer = path.slice(1).some((step) => keyOf(step) === keyOf(projectedPlayer));
    const safetyScore =
      helperDistanceBetween(cell, projectedPlayer) * 16 +
      helperOpenNeighborCount(cell) * 10 -
      steps * 4 -
      (crossesPlayer ? 120 : 0);
    const firstStep = path[1] ?? path[0];
    const firstGoalDistance = hasReachableGoal
      ? helperDistanceBetween(firstStep, goalCell)
      : unreachableDistance;
    const goalDistance = hasReachableGoal
      ? helperDistanceBetween(cell, goalCell)
      : unreachableDistance;
    options.push({
      path,
      safetyScore,
      movesTowardGoal: hasReachableGoal && firstGoalDistance < startGoalDistance,
      goalProgress: hasReachableGoal ? startGoalDistance - goalDistance : 0,
      goalDistance,
    });
  }
  options.sort((first, second) => {
    if (hasReachableGoal) {
      const directionDifference =
        Number(second.movesTowardGoal) - Number(first.movesTowardGoal);
      if (directionDifference) return directionDifference;
      const progressDifference = second.goalProgress - first.goalProgress;
      if (progressDifference) return progressDifference;
      const distanceDifference = first.goalDistance - second.goalDistance;
      if (distanceDifference) return distanceDifference;
    }
    return (
      second.safetyScore - first.safetyScore ||
      first.path.length - second.path.length ||
      keyOf(first.path.at(-1)).localeCompare(keyOf(second.path.at(-1)))
    );
  });
  return options[0]?.path ?? [];
}

function helperCarEscapeStep(projectedPlayer, preferredStep) {
  if (!car) return preferredStep ?? { ...helperMouse };
  const nextCar = nextCarStepForTurn(maze, car, helperMouse);
  const carDistance = helperDistanceBetween(car, helperMouse);
  const preferredCaught = preferredStep
    ? carCatchesMouse(maze, helperMouse, preferredStep, car, nextCar)
    : true;
  if (carDistance > 3 && !preferredCaught) return preferredStep;

  const mazeCell = maze[helperMouse.row]?.[helperMouse.col];
  const uniqueOptions = new Map();
  for (const cell of [
    preferredStep,
    { ...helperMouse },
    ...neighbors(maze, mazeCell ?? { ...helperMouse, walls: {} }),
  ]) {
    if (!cell || helperCellIsBlocked(cell)) continue;
    uniqueOptions.set(keyOf(cell), cell);
  }
  const currentTargetDistance = helperTask?.target
    ? helperDistanceBetween(helperMouse, helperTask.target)
    : 0;
  const safeOptions = [...uniqueOptions.values()]
    .filter((cell) => !carCatchesMouse(maze, helperMouse, cell, car, nextCar))
    .map((cell) => {
      const targetDistance = helperTask?.target
        ? helperDistanceBetween(cell, helperTask.target)
        : currentTargetDistance;
      const carSeparation = findShortestPathFrom(maze, nextCar, cell).length - 1;
      const reversesLastStep = Boolean(
        helperLastDecision?.from && keyOf(cell) === keyOf(helperLastDecision.from),
      );
      return {
        cell,
        score:
          Math.max(0, carSeparation) * 34 +
          helperDistanceBetween(cell, projectedPlayer) * 14 +
          helperOpenNeighborCount(cell) * 10 +
          (currentTargetDistance - targetDistance) * 7 +
          (preferredStep && keyOf(cell) === keyOf(preferredStep) ? 10 : 0) -
          (reversesLastStep ? 100 : 0) -
          (keyOf(cell) === keyOf(projectedPlayer) ? 90 : 0),
      };
    });
  safeOptions.sort((first, second) => second.score - first.score);
  return safeOptions[0]?.cell ?? preferredStep ?? { ...helperMouse };
}

function helperCarApproachStep(projectedPlayer, preferredStep = null) {
  if (!car) return preferredStep ?? { ...helperMouse };
  const playerDistance = carPursuitDistance(car, projectedPlayer);
  const nextCar = nextCarStepForTurn(maze, car, projectedPlayer);
  const mazeCell = maze[helperMouse.row]?.[helperMouse.col];
  const uniqueOptions = new Map();
  for (const cell of [
    preferredStep,
    { ...helperMouse },
    ...neighbors(maze, mazeCell ?? { ...helperMouse, walls: {} }),
  ]) {
    if (!cell || helperCellIsBlocked(cell)) continue;
    uniqueOptions.set(keyOf(cell), cell);
  }
  const safeOptions = [...uniqueOptions.values()]
    .filter((cell) => !carCatchesMouse(maze, helperMouse, cell, car, nextCar))
    .map((cell) => {
      const distance = carPursuitDistance(car, cell);
      const becomesBait = distance <= playerDistance;
      const reversesLastStep = Boolean(
        helperLastDecision?.from && keyOf(cell) === keyOf(helperLastDecision.from),
      );
      return {
        cell,
        score:
          (becomesBait ? 900 : 0) -
          Math.min(distance, ROWS * COLS) * 52 +
          helperDistanceBetween(cell, projectedPlayer) * 9 +
          helperOpenNeighborCount(cell) * 8 +
          (preferredStep && keyOf(cell) === keyOf(preferredStep) ? 8 : 0) -
          (reversesLastStep ? 90 : 0) -
          (keyOf(cell) === keyOf(projectedPlayer) ? 180 : 0),
      };
    });
  safeOptions.sort(
    (first, second) =>
      second.score - first.score || keyOf(first.cell).localeCompare(keyOf(second.cell)),
  );
  return safeOptions[0]?.cell ?? { ...helperMouse };
}

function helperEvasiveStep(adversity, projectedPlayer) {
  if (
    adversity === "cat" &&
    !catPawThreat &&
    helperCatAttackBandDepth(helperMouse) > 2
  ) {
    const decoyPath = helperCatDecoyPath(projectedPlayer);
    if (decoyPath.length > 1) return decoyPath[1];
  }
  const mazeCell = maze[helperMouse.row]?.[helperMouse.col];
  const options = [
    { row: helperMouse.row, col: helperMouse.col },
    ...neighbors(maze, mazeCell ?? { ...helperMouse, walls: {} }).map((cell) => ({
      row: cell.row,
      col: cell.col,
    })),
  ].filter((cell) => !helperCellIsBlocked(cell));
  if (!options.length) return { ...helperMouse };
  const scored = options.map((cell, index) => {
    const playerDistance = helperDistanceBetween(cell, projectedPlayer);
    const carDistance = car ? helperDistanceBetween(cell, car) : 0;
    const clearOfCat = catPawThreat && !catPawThreatContains(catPawThreat, cell);
    const clearOfCrow = crowThreat && !crowThreatContains(crowThreat, cell);
    const hiddenFromCrow = cloudCoversCell(cell);
    const waterArrival = waterIsActive()
      ? waterArrivalMoves().get(keyOf(cell)) ?? Number.POSITIVE_INFINITY
      : Number.POSITIVE_INFINITY;
    const waterSlack = waterArrival - waterMoveCount;
    const moved = keyOf(cell) !== keyOf(helperMouse) ? 1 : 0;
    const overlapsPlayer = keyOf(cell) === keyOf(projectedPlayer);
    const reversesLastStep = Boolean(
      helperLastDecision?.from && keyOf(cell) === keyOf(helperLastDecision.from),
    );
    let threatSafety = 0;
    if (adversity === "car") threatSafety += carDistance * 8;
    if (adversity === "cat" && clearOfCat) threatSafety += 420;
    if (adversity === "cat" && !catPawThreat) {
      threatSafety += Math.max(0, 3 - helperCatAttackBandDepth(cell)) * 120;
    }
    if (adversity === "crow" && clearOfCrow) threatSafety += 260;
    if (adversity === "crow" && hiddenFromCrow) threatSafety -= 480;
    return {
      cell,
      score:
        playerDistance * 10 +
        helperOpenNeighborCount(cell) * 9 +
        Math.min(8, waterSlack) * 4 +
        threatSafety +
        moved * 3 -
        (overlapsPlayer ? 600 : 0) -
        (reversesLastStep ? 140 : 0) -
        index * 0.01,
    };
  });
  scored.sort((first, second) => second.score - first.score);
  return scored[0].cell;
}

function helperRouteLengthForPlayer(start = mouse) {
  const route = currentObjectiveRoute(maze, start, rockPositions);
  return route?.path?.length ? route.path.length - 1 : Number.POSITIVE_INFINITY;
}

function helperMilkKnockIsSafe(bottle, direction, spill, projectedPlayer) {
  const playerPath = findHelperPath(projectedPlayer, spill, keyOf(spill));
  if (!playerPath.length) return null;
  const before = helperRouteLengthForPlayer(projectedPlayer);
  const previous = {
    knocked: bottle.knocked,
    direction: bottle.direction,
    spill: bottle.spill ? { ...bottle.spill } : null,
  };
  bottle.knocked = true;
  bottle.direction = direction;
  bottle.spill = { ...spill };
  const after = helperRouteLengthForPlayer(projectedPlayer);
  bottle.knocked = previous.knocked;
  bottle.direction = previous.direction;
  bottle.spill = previous.spill;
  if (!Number.isFinite(after)) return null;
  if (Number.isFinite(before) && after > before) return null;
  if (after > movesLeft) return null;
  return {
    before,
    after,
    routeSavings: Number.isFinite(before) ? before - after : 0,
  };
}

function helperMilkKnockOptions(bottle, projectedPlayer) {
  if (
    !bottle ||
    bottle.knocked ||
    bottle.helperCarried ||
    bottle.helperDelivered ||
    bottle.glassDestroyed
  ) return null;

  const options = [];
  for (const direction of DIRS) {
    const source = {
      row: bottle.row - direction.row,
      col: bottle.col - direction.col,
    };
    const spill = bottleSpillForDirection(bottle, direction.key);
    if (
      !spill ||
      !isInside(source.row, source.col) ||
      !isInside(spill.row, spill.col) ||
      helperCellIsBlocked(source) ||
      !helperDropCellIsClear(spill, projectedPlayer) ||
      !hasOpenPassageBetween(maze, source, bottle) ||
      !hasOpenPassageBetween(maze, bottle, spill)
    ) continue;

    const path = findHelperPath(helperMouse, source);
    if (!path.length) continue;
    const safety = helperMilkKnockIsSafe(
      bottle,
      direction.key,
      spill,
      projectedPlayer,
    );
    if (!safety) continue;
    options.push({
      direction: direction.key,
      source,
      spill,
      path,
      playerDistance: helperDistanceBetween(projectedPlayer, spill),
      routeSavings: safety.routeSavings,
    });
  }

  options.sort(
    (first, second) =>
      second.routeSavings - first.routeSavings ||
      first.playerDistance - second.playerDistance ||
      first.path.length - second.path.length,
  );
  return options;
}

function helperRockPushOption(rock, direction, projectedPlayer) {
  if (!rock || !direction || helperTestedRockIds.has(String(rock.id))) return null;
  if (mouseMotion?.rockPush || waterIsActive() || rotatingCircuits.length) {
    return null;
  }
  const source = {
    row: rock.row - direction.row,
    col: rock.col - direction.col,
  };
  const destination = {
    row: rock.row + direction.row,
    col: rock.col + direction.col,
  };
  if (
    !isInside(source.row, source.col) ||
    !isInside(destination.row, destination.col) ||
    helperCellIsBlocked(source) ||
    activeTunnelAt(source) ||
    rockAt(destination) ||
    milkBottleAt(destination) ||
    milkPuddleAt(destination) ||
    pieQuarterAt(destination) ||
    carrotPatchAt(destination) ||
    activeTunnelAt(destination) ||
    waterCellIsFlooded(destination) ||
    keyOf(destination) === keyOf(projectedPlayer) ||
    Boolean(car && keyOf(car) === keyOf(destination)) ||
    remainingCheeseTargets().some((target) => keyOf(target) === keyOf(destination)) ||
    !hasOpenPassageBetween(maze, source, rock) ||
    !hasOpenPassageBetween(maze, rock, destination)
  ) {
    return null;
  }
  const path = findHelperPath(helperMouse, source, keyOf(source));
  if (!path.length) return null;

  const nextRocks = rockPositions.map((candidate) =>
    candidate.id === rock.id
      ? { ...candidate, row: destination.row, col: destination.col }
      : { ...candidate },
  );
  const rockLayoutKey = rockPositions
    .map((candidate) => `${candidate.id}:${keyOf(candidate)}`)
    .sort()
    .join("|");
  const objectiveKey = remainingCheeseTargets()
    .map((target) => `${cheeseIdentity(target)}:${keyOf(target)}`)
    .sort()
    .join("|");
  const safetyContext = `${keyOf(projectedPlayer)}|${movesLeft}|${rockLayoutKey}|${objectiveKey}`;
  const safetyKey = `${safetyContext}|${rock.id}->${keyOf(destination)}`;
  let safe = helperRockSafetyCache.get(safetyKey);
  if (safe === undefined) {
    const baselineKey = `baseline|${safetyContext}`;
    let before = helperRockSafetyCache.get(baselineKey);
    if (before === undefined) {
      before = helperRouteLengthForPlayer(projectedPlayer);
      helperRockSafetyCache.set(baselineKey, before);
    }
    const afterRoute = currentObjectiveRoute(maze, projectedPlayer, nextRocks);
    const after = afterRoute?.path?.length
      ? afterRoute.path.length - 1
      : Number.POSITIVE_INFINITY;
    safe = Boolean(
      Number.isFinite(after) &&
      after <= movesLeft &&
      (!Number.isFinite(before) || after <= before),
    );
    helperRockSafetyCache.set(safetyKey, safe);
  }
  if (!safe) return null;

  return {
    type: "exploreRock",
    key: `explore-rock:${rock.id}:${direction.key}`,
    kind: "rock",
    id: rock.id,
    target: source,
    rockFrom: { row: rock.row, col: rock.col },
    rockTo: destination,
    direction: direction.key,
    path,
    score:
      360 -
      (path.length - 1) * 12 +
      helperOpenNeighborCount(destination) * 4 +
      helperDistanceBetween(projectedPlayer, rock) * 2,
  };
}

function helperRockExplorationCandidates(projectedPlayer) {
  if (!hiddenCheeseKeys.size || !rockPositions.length) return [];
  const candidates = [];
  for (const rock of rockPositions) {
    if (helperTestedRockIds.has(String(rock.id))) continue;
    for (const direction of DIRS) {
      const option = helperRockPushOption(rock, direction, projectedPlayer);
      if (option) candidates.push(option);
    }
  }
  return candidates.sort(
    (first, second) =>
      second.score - first.score ||
      String(first.id).localeCompare(String(second.id)) ||
      first.direction.localeCompare(second.direction),
  );
}

function helperTunnelGoalCells(objectives, projectedPlayer, carrying = false) {
  if (carrying) {
    return helperRendezvousCells(projectedPlayer, helperLikelyPlayerIntent(projectedPlayer))
      .filter((cell) => cell.playerDistance === 1)
      .map((cell) => ({ row: cell.row, col: cell.col }));
  }
  return objectives
    .filter((candidate) => !candidate.waitingForObstacle && candidate.kind !== "milk")
    .map((candidate) => ({ ...candidate.target }));
}

function helperTunnelTask(projectedPlayer, objectives = [], carrying = false) {
  if (
    helperTunnelCooldownTurns > 0 ||
    rotatingCircuits.length ||
    activeTunnels().length < 2
  ) {
    return null;
  }
  const goals = helperTunnelGoalCells(objectives, projectedPlayer, carrying);
  if (!goals.length) return null;
  const taskSuffix = carrying ? ":deliver" : ":fetch";
  if (
    helperTask?.type === "tunnel" &&
    helperTask.key.endsWith(taskSuffix) &&
    (helperTask.age ?? 0) < HELPER_TASK_COMMITMENT_TURNS
  ) {
    const committedEntry = activeTunnels().find(
      (tunnel) => tunnel.id === helperTask.entryId,
    );
    const committedPath = committedEntry
      ? findHelperPath(helperMouse, committedEntry, keyOf(committedEntry))
      : [];
    if (committedPath.length) {
      return {
        ...helperTask,
        target: { row: committedEntry.row, col: committedEntry.col },
        path: committedPath,
      };
    }
  }
  const distanceToGoals = (origin) =>
    Math.min(...goals.map((goal) => helperDistanceBetween(origin, goal)));
  const directDistance = distanceToGoals(helperMouse);
  if (!Number.isFinite(directDistance)) return null;

  let best = null;
  for (const entry of activeTunnels()) {
    const path = findHelperPath(helperMouse, entry, keyOf(entry));
    if (!path.length) continue;
    const destinations = activeTunnels().filter((candidate) => candidate.id !== entry.id);
    const destinationDistances = destinations
      .map(distanceToGoals)
      .filter(Number.isFinite);
    if (destinationDistances.length !== destinations.length) continue;
    const expectedDistance =
      destinationDistances.reduce((total, distance) => total + distance, 0) /
      destinationDistances.length;
    const expectedJourney = path.length - 1 + 1 + expectedDistance;
    const bestJourney = path.length + Math.min(...destinationDistances);
    const gain = directDistance - bestJourney;
    const expectedGain = directDistance - expectedJourney;
    if (gain < 3 || expectedGain < -5) continue;
    const candidate = {
      type: "tunnel",
      key: `tunnel:${entry.id}:${carrying ? "deliver" : "fetch"}`,
      kind: "tunnel",
      entryId: entry.id,
      target: { row: entry.row, col: entry.col },
      path,
      gain,
      expectedGain,
      score: 500 + gain * 24 + expectedGain * 8,
    };
    if (!best || candidate.score > best.score) best = candidate;
  }
  return best;
}

function helperRandomTunnelAction(entryId) {
  const entry = activeTunnels().find((tunnel) => tunnel.id === entryId);
  if (!entry || keyOf(entry) !== keyOf(helperMouse)) return null;
  const destinations = activeTunnels().filter((tunnel) => tunnel.id !== entry.id);
  if (!destinations.length) return null;
  const destination = destinations[
    Math.min(destinations.length - 1, Math.floor(randomUnit() * destinations.length))
  ];
  return {
    to: { row: destination.row, col: destination.col },
    action: {
      type: "tunnel",
      entryId: entry.id,
      destinationId: destination.id,
    },
  };
}

function helperObjectiveDescriptors() {
  const descriptors = [];
  for (const target of remainingCheeseTargets()) {
    if (target.helperCarried || !isCheeseVisible(target)) continue;
    descriptors.push({
      key: `cheese:${cheeseIdentity(target)}`,
      kind: "cheese",
      id: cheeseIdentity(target),
      cell: { row: target.row, col: target.col },
      allowedTargetKey: keyOf(target),
    });
  }
  for (const bottle of remainingMilkBottles()) {
    const cell = bottle.knocked && bottle.spill ? bottle.spill : bottle;
    descriptors.push({
      key: `milk:${bottle.id}`,
      kind: "milk",
      id: bottle.id,
      cell: { row: cell.row, col: cell.col },
      allowedTargetKey: bottle.knocked ? keyOf(cell) : null,
    });
  }
  for (const quarter of remainingPieQuarters()) {
    if (quarter.helperCarried) continue;
    const cell = quarter.helperDeliveredCell ?? quarter.approach;
    descriptors.push({
      key: `pie:${quarter.id}`,
      kind: "pie",
      id: quarter.id,
      cell: { row: cell.row, col: cell.col },
      allowedTargetKey: keyOf(cell),
    });
  }
  return descriptors;
}

function noteHelperPlayerTurn(projectedPlayer) {
  helperPlannerTurn += 1;
  helperTunnelCooldownTurns = Math.max(0, helperTunnelCooldownTurns - 1);
  helperPlayerTrail.push({ row: projectedPlayer.row, col: projectedPlayer.col });
  if (helperPlayerTrail.length > HELPER_INTENT_HISTORY_LIMIT) helperPlayerTrail.shift();
  for (const adversity of Object.keys(helperDistractionCooldowns)) {
    helperDistractionCooldowns[adversity] = Math.max(
      0,
      helperDistractionCooldowns[adversity] - 1,
    );
  }
  if (!helperTask) return;
  helperTask.age = (helperTask.age ?? 0) + 1;
  if (helperTask.type !== "distract") return;
  if (helperTask.turnsRemaining === null) return;
  helperTask.turnsRemaining = Math.max(0, (helperTask.turnsRemaining ?? 0) - 1);
  if (helperTask.turnsRemaining > 0) return;
  helperDistractionCooldowns[helperTask.adversity] =
    HELPER_DISTRACTION_COOLDOWN_TURNS;
  helperTask = null;
}

function helperLikelyPlayerIntent(projectedPlayer) {
  const descriptors = helperObjectiveDescriptors();
  if (!descriptors.length) return null;
  const recent = helperPlayerTrail.slice(-3);
  let best = null;
  for (const descriptor of descriptors) {
    const currentDistance = helperDistanceBetween(projectedPlayer, descriptor.cell);
    if (!Number.isFinite(currentDistance)) continue;
    let progress = 0;
    for (let index = 1; index < recent.length; index += 1) {
      const before = helperDistanceBetween(recent[index - 1], descriptor.cell);
      const after = helperDistanceBetween(recent[index], descriptor.cell);
      progress += (before - after) * index;
    }
    const score = progress * 22 - currentDistance * 1.5;
    if (!best || score > best.score || (score === best.score && descriptor.key < best.key)) {
      best = { ...descriptor, score, distance: currentDistance };
    }
  }
  return best;
}

function helperDropCellIsClear(cell, playerCell = mouse) {
  if (helperCellIsBlocked(cell) || activeTunnelAt(cell)) return false;
  const cellKey = keyOf(cell);
  if (cellKey === keyOf(playerCell) || (car && cellKey === keyOf(car))) return false;
  const occupiedByCheese = remainingCheeseTargets().some(
    (target) => !target.helperCarried && keyOf(target) === cellKey,
  );
  const occupiedByMilk = Boolean(milkBottleAt(cell) || milkPuddleAt(cell));
  const occupiedByDeliveredPie = remainingPieQuarters().some(
    (quarter) => quarter.helperDeliveredCell && keyOf(quarter.helperDeliveredCell) === cellKey,
  );
  return !occupiedByCheese && !occupiedByMilk && !occupiedByDeliveredPie;
}

function helperCellsAtDistance(origin, targetDistance) {
  const queue = [{ cell: { ...origin }, distance: 0 }];
  const seen = new Set([keyOf(origin)]);
  const matches = [];
  for (let index = 0; index < queue.length; index += 1) {
    const current = queue[index];
    if (current.distance === targetDistance) {
      matches.push(current.cell);
      continue;
    }
    const mazeCell = maze[current.cell.row]?.[current.cell.col];
    if (!mazeCell) continue;
    for (const next of neighbors(maze, mazeCell)) {
      const nextKey = keyOf(next);
      if (seen.has(nextKey) || helperCellIsBlocked(next)) continue;
      seen.add(nextKey);
      queue.push({
        cell: { row: next.row, col: next.col },
        distance: current.distance + 1,
      });
    }
  }
  return matches;
}

function helperRendezvousCells(projectedPlayer, intent = null) {
  const cells = new Map();
  const add = (cell, routeIndex = 20) => {
    if (!cell || !helperDropCellIsClear(cell, projectedPlayer)) return;
    const playerPath = findHelperPath(projectedPlayer, cell, keyOf(cell));
    if (!playerPath.length || playerPath.length - 1 > 4) return;
    const existing = cells.get(keyOf(cell));
    if (!existing || routeIndex < existing.routeIndex) {
      cells.set(keyOf(cell), { ...cell, routeIndex, playerDistance: playerPath.length - 1 });
    }
  };

  if (intent) {
    const route = findHelperPath(projectedPlayer, intent.cell, intent.allowedTargetKey);
    route.slice(1, 6).forEach((cell, index) => {
      add(cell, index);
      const mazeCell = maze[cell.row]?.[cell.col];
      if (!mazeCell) return;
      for (const neighbor of neighbors(maze, mazeCell)) add(neighbor, index + 0.5);
    });
  }
  for (const distance of [1, 2, 3]) {
    for (const cell of helperCellsAtDistance(projectedPlayer, distance)) add(cell, 10 + distance);
  }
  return [...cells.values()];
}

function helperDeliveryPreservesSolvability(
  cell,
  projectedPlayer,
  cargo = helperCargo,
) {
  const playerPath = findHelperPath(projectedPlayer, cell, keyOf(cell));
  if (!playerPath.length || playerPath.length - 1 > movesLeft) return false;
  if (!cargo || cargo.kind !== "cheese") return true;
  const objective = helperObjectiveByIdentity(cargo.kind, cargo.id);
  if (!objective) return false;
  const previous = {
    row: objective.row,
    col: objective.col,
    helperCarried: objective.helperCarried,
    helperDelivered: objective.helperDelivered,
  };
  objective.row = cell.row;
  objective.col = cell.col;
  objective.helperCarried = false;
  objective.helperDelivered = true;
  const routeLength = helperRouteLengthForPlayer(projectedPlayer);
  Object.assign(objective, previous);
  return Number.isFinite(routeLength) && routeLength <= movesLeft;
}

function helperDeliveryPlan(
  projectedPlayer,
  start = helperMouse,
  intent = null,
  cargo = helperCargo,
) {
  const currentDistance = helperDistanceBetween(start, projectedPlayer);
  if (
    currentDistance === 1 &&
    helperDropCellIsClear(start, projectedPlayer) &&
    helperDeliveryPreservesSolvability(start, projectedPlayer, cargo)
  ) {
    return { cell: { ...start }, path: [{ ...start }], distance: currentDistance };
  }

  let best = null;
  for (const candidate of helperRendezvousCells(projectedPlayer, intent)) {
    const path = findHelperPath(start, candidate, keyOf(candidate));
    if (
      !path.length ||
      !helperDeliveryPreservesSolvability(candidate, projectedPlayer, cargo)
    ) continue;
    const score =
      Math.abs(candidate.playerDistance - 1) * 1000 +
      path.length * 8 +
      candidate.routeIndex * 1.5;
    if (!best || score < best.score || (score === best.score && keyOf(candidate) < keyOf(best.cell))) {
      best = { cell: candidate, path, distance: candidate.playerDistance, score };
    }
  }
  return best;
}

function helperCanDeliverFrom(start, projectedPlayer, intent, cargo = helperCargo) {
  return Boolean(helperDeliveryPlan(projectedPlayer, start, intent, cargo));
}

function helperProspectiveDelivery(candidate, projectedPlayer, intent) {
  if (!candidate || candidate.kind === "milk" || candidate.waitingForObstacle) return null;
  const delivery = helperDeliveryPlan(
    projectedPlayer,
    candidate.target,
    intent,
    null,
  );
  if (!delivery || keyOf(delivery.cell) === keyOf(candidate.objectiveCell)) return null;
  const playerDistance = helperDistanceBetween(projectedPlayer, candidate.objectiveCell);
  const pickupTurns = Math.max(1, candidate.path.length - 1);
  const deliveryTurns = Math.max(1, delivery.path.length - 1);
  return {
    delivery,
    playerDistance,
    routeSavings: playerDistance - delivery.distance,
    totalTurns: pickupTurns + deliveryTurns,
  };
}

function helperObjectiveWaterScore(cell, helperSteps) {
  if (!waterIsActive()) return 0;
  const arrival = waterArrivalMoves().get(keyOf(cell)) ?? Number.POSITIVE_INFINITY;
  const slack = arrival - (waterMoveCount + helperSteps);
  if (slack <= 0) return Number.NEGATIVE_INFINITY;
  if (slack <= 2) return 260;
  if (slack <= 4) return 150;
  if (slack <= 6) return 70;
  return 0;
}

function helperBlockedObjectiveApproach(objectiveCell) {
  const topologyPath = findShortestPathFrom(maze, helperMouse, objectiveCell);
  if (topologyPath.length < 2) return null;
  const blockerIndex = topologyPath.findIndex(
    (cell, index) => index > 0 && helperCellIsBlocked(cell),
  );
  if (blockerIndex < 1) return null;
  const target = topologyPath[blockerIndex - 1];
  const path = findHelperPath(helperMouse, target, keyOf(target));
  return path.length ? { target: { ...target }, path } : null;
}

function helperFetchCandidates(projectedPlayer = mouse, intent = null) {
  const objectiveCount = remainingObjectiveCount();
  const canHelpWithFinalObjective = Boolean(
    car || currentLevelConfig().catPawMode || currentLevelConfig().crowMode,
  );
  if (objectiveCount === 0 || (objectiveCount === 1 && !canHelpWithFinalObjective)) return [];
  const candidates = [];
  for (const target of remainingCheeseTargets()) {
    if (target.helperCarried || target.helperDelivered || !isCheeseVisible(target)) continue;
    const candidate = {
      type: "fetch",
      key: `fetch:cheese:${cheeseIdentity(target)}`,
      kind: "cheese",
      id: cheeseIdentity(target),
      target: { row: target.row, col: target.col },
      allowedTargetKey: keyOf(target),
      objectiveCell: { row: target.row, col: target.col },
    };
    const path = findHelperPath(helperMouse, candidate.target, candidate.allowedTargetKey);
    if (
      path.length &&
      helperCanDeliverFrom(
        candidate.target,
        projectedPlayer,
        intent,
        null,
      )
    ) {
      candidates.push({ ...candidate, path });
    } else if (!path.length) {
      const approach = helperBlockedObjectiveApproach(candidate.objectiveCell);
      if (approach) {
        candidates.push({
          ...candidate,
          target: approach.target,
          allowedTargetKey: keyOf(approach.target),
          path: approach.path,
          waitingForObstacle: true,
        });
      }
    }
  }
  for (const bottle of remainingMilkBottles()) {
    for (const knock of helperMilkKnockOptions(bottle, projectedPlayer) ?? []) {
      candidates.push({
        type: "fetch",
        key: `fetch:milk:${bottle.id}:${knock.direction}`,
        kind: "milk",
        id: bottle.id,
        target: { ...knock.source },
        objectiveCell: { row: bottle.row, col: bottle.col },
        knockDirection: knock.direction,
        spill: { ...knock.spill },
        allowedTargetKey: null,
        path: knock.path,
        routeSavings: knock.routeSavings,
      });
    }
  }
  for (const quarter of remainingPieQuarters()) {
    if (quarter.helperCarried || quarter.helperDeliveredCell) continue;
    const candidate = {
      type: "fetch",
      key: `fetch:pie:${quarter.id}`,
      kind: "pie",
      id: quarter.id,
      target: { ...quarter.approach },
      objectiveCell: { ...quarter.approach },
      allowedTargetKey: keyOf(quarter.approach),
    };
    const path = findHelperPath(helperMouse, candidate.target, candidate.allowedTargetKey);
    if (
      path.length &&
      helperCanDeliverFrom(
        candidate.target,
        projectedPlayer,
        intent,
        null,
      )
    ) {
      candidates.push({ ...candidate, path });
    }
  }
  for (const candidate of candidates) {
    const helperSteps = candidate.path.length - 1;
    const playerDistance = helperDistanceBetween(
      projectedPlayer,
      candidate.kind === "milk" ? candidate.spill : candidate.objectiveCell,
    );
    const deliveryDistance = candidate.kind === "milk"
      ? 0
      : Math.max(0, helperDistanceBetween(candidate.target, projectedPlayer) - 2);
    const descriptorKey = `${candidate.kind}:${candidate.id}`;
    const complementsIntent = Boolean(intent && descriptorKey !== intent.key);
    const competesWithPlayer = Boolean(intent && descriptorKey === intent.key);
    const waterScore = helperObjectiveWaterScore(candidate.objectiveCell, helperSteps);
    const prospectiveDelivery = helperProspectiveDelivery(
      candidate,
      projectedPlayer,
      intent,
    );
    const finalObjectiveLead = playerDistance - helperSteps;
    candidate.providesUsefulDelivery = Boolean(
      candidate.kind === "milk" ||
        candidate.waitingForObstacle ||
        (prospectiveDelivery &&
          prospectiveDelivery.routeSavings >= 1 &&
          (!competesWithPlayer || finalObjectiveLead >= 2)),
    );
    candidate.deliveryDistance = prospectiveDelivery?.delivery.distance ?? deliveryDistance;
    candidate.deliveryTurns = prospectiveDelivery?.totalTurns ?? 0;
    candidate.usefulAsFinalObjective = Boolean(
      objectiveCount !== 1 ||
        (!candidate.waitingForObstacle &&
          ((prospectiveDelivery &&
            prospectiveDelivery.routeSavings >= 1 &&
            finalObjectiveLead >= 2) ||
            (candidate.kind === "milk" && (candidate.routeSavings ?? 0) > 0))),
    );
    candidate.score =
      playerDistance * 6 -
      helperSteps * 5 -
      deliveryDistance * 2 +
      (complementsIntent ? 65 : 0) -
      (competesWithPlayer ? 75 : 0) +
      (candidate.routeSavings ?? 0) * 25 +
      waterScore +
      (objectiveCount === 1 && candidate.usefulAsFinalObjective
        ? 140 + Math.max(0, finalObjectiveLead) * 12
        : 0);
    if (
      remainingObjectiveCount() === 1 &&
      competesWithPlayer &&
      playerDistance <= helperSteps + 4
    ) {
      candidate.score -= 180;
    }
  }
  return candidates
    .filter(
      (candidate) =>
        Number.isFinite(candidate.score) &&
        candidate.providesUsefulDelivery &&
        candidate.usefulAsFinalObjective,
    )
    .sort((first, second) => second.score - first.score || first.key.localeCompare(second.key));
}

function helperCarDangerTurns(projectedPlayer) {
  if (!car) return Number.POSITIVE_INFINITY;
  let simulatedCar = { ...car };
  for (let turn = 1; turn <= HELPER_THREAT_LOOKAHEAD_TURNS; turn += 1) {
    const nextCar = nextCarStepForTurn(maze, simulatedCar, projectedPlayer);
    if (carCatchesMouse(maze, projectedPlayer, projectedPlayer, simulatedCar, nextCar)) {
      return turn;
    }
    if (keyOf(nextCar) === keyOf(simulatedCar)) break;
    simulatedCar = { ...nextCar };
  }
  return Number.POSITIVE_INFINITY;
}

function helperThreatCandidates(projectedPlayer, intent = null) {
  const candidates = [];
  const carDanger = helperCarDangerTurns(projectedPlayer);
  if (car && helperDistractionCooldowns.car === 0) {
    const decoy = helperRemoteDecoyPlan("car", projectedPlayer, intent);
    candidates.push({
      type: "distract",
      key: "distract:car",
      adversity: "car",
      target: decoy?.target ?? null,
      score: Number.isFinite(carDanger) ? 900 - carDanger * 90 : 720,
      turnsRemaining: null,
    });
  }

  const catTurns = catPawMovesUntilStrike();
  const catAlreadyTargetsHelper = catPawThreat?.targetKind === "helper";
  const catDecoyPath = currentLevelConfig().catPawMode && !catAlreadyTargetsHelper
    ? helperCatDecoyPath(projectedPlayer)
    : [];
  const catPreparationTurns = Math.max(3, Math.min(5, catDecoyPath.length + 1));
  if (
    currentLevelConfig().catPawMode &&
    helperDistractionCooldowns.cat === 0 &&
    (catAlreadyTargetsHelper || catTurns <= catPreparationTurns)
  ) {
    candidates.push({
      type: "distract",
      key: "distract:cat",
      adversity: "cat",
      target:
        helperTask?.type === "distract" &&
        helperTask.adversity === "cat" &&
        helperTask.target
          ? { ...helperTask.target }
          : catDecoyPath.at(-1) ?? { ...helperMouse },
      objectiveGoal: helperDistractionObjectiveGoal(projectedPlayer, intent),
      score: 1040 - Math.max(0, catTurns) * 80,
      turnsRemaining: null,
    });
  }

  const crowTurns = crowMovesUntilStrike();
  const crowAlreadyTargetsHelper = crowThreat?.targetKind === "helper";
  if (
    currentLevelConfig().crowMode &&
    helperDistractionCooldowns.crow === 0 &&
    (crowAlreadyTargetsHelper || crowTurns <= 3)
  ) {
    const decoy = helperRemoteDecoyPlan("crow", projectedPlayer, intent);
    candidates.push({
      type: "distract",
      key: "distract:crow",
      adversity: "crow",
      target: decoy?.target ?? null,
      objectiveGoal: helperDistractionObjectiveGoal(projectedPlayer, intent),
      score: 1020 - Math.max(0, crowTurns) * 80,
      turnsRemaining: null,
    });
  }
  return candidates.sort(
    (first, second) => second.score - first.score || first.key.localeCompare(second.key),
  );
}

function helperAdoptTask(candidate) {
  const changed = helperTask?.key !== candidate?.key;
  if (!candidate) {
    helperTask = null;
    return;
  }
  const previous = changed ? null : helperTask;
  helperTask = {
    ...candidate,
    age: previous?.age ?? 0,
    turnsRemaining:
      previous?.turnsRemaining ??
      candidate.turnsRemaining ??
      null,
  };
  if (changed) {
    helperIntentCueUntil = Date.now() + HELPER_INTENT_CUE_MS;
    setTimeout(() => {
      if (Date.now() >= helperIntentCueUntil) requestMazeDraw();
    }, HELPER_INTENT_CUE_MS + 20);
  }
}

function helperChooseTask(projectedPlayer, intent) {
  const threats = helperThreatCandidates(projectedPlayer, intent);
  const urgentThreat = threats[0] ?? null;
  if (urgentThreat) return urgentThreat;

  if (helperRecoveryTurns > 0) {
    return { type: "rest", key: "rest:recovery", score: 0, reason: "recovery" };
  }
  const observationTurns = currentLevelConfig().helperIntro
    ? 0
    : HELPER_OBSERVATION_TURNS;
  if (helperPlannerTurn <= observationTurns) {
    return { type: "follow", key: "follow:observe", score: 0, reason: "observing" };
  }

  const objectives = helperFetchCandidates(projectedPlayer, intent);
  const tunnelTask = helperTunnelTask(projectedPlayer, objectives);
  if (
    tunnelTask &&
    (!objectives[0] ||
      tunnelTask.gain >= 4 ||
      tunnelTask.score > objectives[0].score + 40)
  ) {
    return tunnelTask;
  }
  const currentCandidate = helperTask?.type === "fetch"
    ? objectives.find((candidate) => candidate.key === helperTask.key)
    : null;
  if (
    currentCandidate &&
    ((helperTask.age ?? 0) < HELPER_TASK_COMMITMENT_TURNS ||
      !objectives[0] ||
      currentCandidate.score + 25 >= objectives[0].score)
  ) {
    return currentCandidate;
  }
  if (objectives[0]) return objectives[0];
  const rockCandidates = helperRockExplorationCandidates(projectedPlayer);
  const currentRockCandidate = helperTask?.type === "exploreRock"
    ? rockCandidates.find((candidate) => candidate.key === helperTask.key)
    : null;
  if (
    currentRockCandidate &&
    (helperTask.age ?? 0) < HELPER_TASK_COMMITMENT_TURNS
  ) {
    return currentRockCandidate;
  }
  if (rockCandidates[0]) return rockCandidates[0];
  return { type: "rest", key: "rest:no-useful-action", score: 0, reason: "no-useful-action" };
}

function helperActionForPathStep(step) {
  if (!step?.helperTunnel) return null;
  return {
    type: "tunnel",
    entryId: step.entryId,
    destinationId: step.destinationId,
  };
}

function prepareHelperTurn(projectedPlayer = mouse) {
  helperMotion = null;
  if (!helperIsActive()) return;
  noteHelperPlayerTurn(projectedPlayer);
  const intent = helperLikelyPlayerIntent(projectedPlayer);
  let to = { ...helperMouse };
  let action = null;
  helperResting = false;

  if (helperCargo) {
    const urgentThreat = helperThreatCandidates(projectedPlayer, intent)[0] ?? null;
    const delivery = helperDeliveryPlan(projectedPlayer, helperMouse, intent);
    const tunnelTask = helperTunnelTask(projectedPlayer, [], true);
    if (
      urgentThreat &&
      helperDropCellIsClear(helperMouse, projectedPlayer) &&
      helperDeliveryPreservesSolvability(helperMouse, projectedPlayer) &&
      (!delivery || delivery.path.length > 2)
    ) {
      helperAdoptTask({ type: "deliver", key: "deliver:before-threat", score: urgentThreat.score });
      action = { type: "deliver" };
    } else if (tunnelTask && tunnelTask.gain >= 3) {
      helperAdoptTask(tunnelTask);
      const path = findHelperPath(helperMouse, tunnelTask.target, keyOf(tunnelTask.target));
      if (path.length === 1) {
        const travel = helperRandomTunnelAction(tunnelTask.entryId);
        if (travel) {
          to = travel.to;
          action = travel.action;
        } else {
          helperResting = true;
        }
      } else if (path.length > 1) {
        to = path[1];
      } else {
        helperResting = true;
      }
    } else {
      helperAdoptTask({ type: "deliver", key: "deliver:cargo", score: 1000 });
      if (delivery) {
        to = delivery.path[1] ?? delivery.cell;
        action = helperActionForPathStep(to);
        if (keyOf(to) === keyOf(delivery.cell)) action = { type: "deliver" };
      } else {
        helperResting = true;
      }
    }
  } else {
    const task = helperChooseTask(projectedPlayer, intent);
    helperAdoptTask(task);
    if (task.type === "distract") {
      const threatLockedOnHelper =
        (task.adversity === "cat" && catPawThreat?.targetKind === "helper") ||
        (task.adversity === "crow" && crowThreat?.targetKind === "helper");
      if (threatLockedOnHelper) {
        const escapePath = helperThreatEscapePath(task.adversity, projectedPlayer);
        to = escapePath[1] ?? { ...helperMouse };
        action = helperActionForPathStep(to);
      } else if (task.target) {
        const path = findHelperPath(helperMouse, task.target, keyOf(task.target));
        to = path[1] ?? { ...helperMouse };
        action = helperActionForPathStep(to);
      } else {
        to = helperEvasiveStep(task.adversity, projectedPlayer);
      }
      if (task.adversity === "car") {
        const carTargetsHelper = carPursuitTarget(mouse, helperMouse).kind === "helper";
        to = carTargetsHelper
          ? helperCarEscapeStep(projectedPlayer, to)
          : helperCarApproachStep(projectedPlayer, to);
        action = helperActionForPathStep(to);
      }
    } else if (task.type === "fetch") {
      const path = findHelperPath(helperMouse, task.target, task.allowedTargetKey);
      to = path[1] ?? task.target;
      action = helperActionForPathStep(to);
      if (task.kind === "milk" && path.length === 1) {
        helperFacingDirection = task.knockDirection;
        action = {
          type: "knockMilk",
          id: task.id,
          direction: task.knockDirection,
          spill: { ...task.spill },
        };
      } else if (
        task.kind !== "milk" &&
        !task.waitingForObstacle &&
        keyOf(to) === keyOf(task.target)
      ) {
        action = { type: "pickup", kind: task.kind, id: task.id };
      } else if (task.waitingForObstacle && path.length <= 1) {
        helperResting = true;
      }
    } else if (task.type === "exploreRock") {
      const rock = rockPositions.find((candidate) => candidate.id === task.id);
      const path = rock
        ? findHelperPath(helperMouse, task.target, keyOf(task.target))
        : [];
      if (path.length > 1) {
        to = path[1];
      } else if (
        rock &&
        path.length === 1 &&
        keyOf(rock) === keyOf(task.rockFrom)
      ) {
        to = { ...task.rockFrom };
        action = {
          type: "pushRock",
          id: task.id,
          direction: task.direction,
          from: { ...task.rockFrom },
          to: { ...task.rockTo },
        };
      } else {
        helperTask = null;
        helperResting = true;
      }
    } else if (task.type === "tunnel") {
      const path = findHelperPath(helperMouse, task.target, keyOf(task.target));
      if (path.length === 1) {
        const travel = helperRandomTunnelAction(task.entryId);
        if (travel) {
          to = travel.to;
          action = travel.action;
        } else {
          helperTask = null;
          helperResting = true;
        }
      } else if (path.length > 1) {
        to = path[1];
      } else {
        helperTask = null;
        helperResting = true;
      }
    } else if (task.type === "follow") {
      const path = findHelperPath(helperMouse, projectedPlayer, keyOf(projectedPlayer));
      if (path.length > 2) {
        to = path[1];
        action = helperActionForPathStep(to);
      } else {
        helperResting = true;
      }
    } else {
      helperResting = true;
    }
  }

  helperMode = helperResting
    ? "rest"
    : helperCargo
      ? "deliver"
      : helperTask?.type ?? "follow";
  helperLastDecision = {
    turn: helperPlannerTurn,
    mode: helperMode,
    task: helperTask?.key ?? null,
    score: helperTask?.score ?? 0,
    intent: intent?.key ?? null,
    from: { ...helperMouse },
    to: { ...to },
    action: action?.type ?? null,
  };
  syncHelperDebugDataset();
  if (helperRecoveryTurns > 0 && helperTask?.reason === "recovery") {
    helperRecoveryTurns -= 1;
  }
  if (helperResting && !action && keyOf(to) === keyOf(helperMouse)) return;
  if (to.col > helperMouse.col) helperFacingDirection = "right";
  else if (to.col < helperMouse.col) helperFacingDirection = "left";
  else if (to.row < helperMouse.row) helperFacingDirection = "up";
  else if (to.row > helperMouse.row) helperFacingDirection = "down";
  helperMotion = {
    from: { ...helperMouse },
    to: { ...to },
    action,
    progress: 0,
  };
}

function pickupHelperObjective(action) {
  if (!action || helperCargo) return;
  const objective = helperObjectiveByIdentity(action.kind, action.id);
  if (!objective) return;
  if (action.kind === "cheese" && cheeseWasCollected(objective)) return;
  if (action.kind === "milk" && (objective.knocked || collectedMilkIds.has(objective.id))) return;
  if (action.kind === "pie" && eatenPieQuarterIds.has(objective.id)) return;
  objective.helperCarried = true;
  objective.helperDelivered = false;
  if (action.kind !== "pie") {
    objective.row = helperMouse.row;
    objective.col = helperMouse.col;
  }
  helperCargo = { kind: action.kind, id: action.id };
  helperTask = null;
  helperMode = "deliver";
}

function syncHelperCargoPosition() {
  if (!helperCargo || !helperMouse || helperCargo.kind === "pie") return;
  const objective = helperObjectiveByIdentity(helperCargo.kind, helperCargo.id);
  if (!objective) return;
  objective.row = helperMouse.row;
  objective.col = helperMouse.col;
}

function deliverHelperCargo(cell = helperMouse) {
  if (!helperCargo || !cell) return;
  const objective = helperObjectiveByIdentity(helperCargo.kind, helperCargo.id);
  if (!objective) {
    helperCargo = null;
    return;
  }
  objective.helperCarried = false;
  objective.helperDelivered = true;
  if (helperCargo.kind === "pie") {
    objective.helperDeliveredCell = { row: cell.row, col: cell.col };
  } else {
    objective.row = cell.row;
    objective.col = cell.col;
  }
  const deliveredKind = helperCargo.kind;
  helperCargo = null;
  helperTask = null;
  helperRecoveryTurns = deliveredKind === "pie" ? HELPER_PIE_RECOVERY_TURNS : 0;
  helperResting = helperRecoveryTurns > 0;
  helperMode = helperResting ? "rest" : "follow";
}

function nearestHelperDropCell(origin) {
  const queue = [{ row: origin.row, col: origin.col }];
  const seen = new Set([keyOf(origin)]);
  while (queue.length) {
    const current = queue.shift();
    if (helperDropCellIsClear(current)) return current;
    const mazeCell = maze[current.row]?.[current.col];
    if (!mazeCell) continue;
    for (const next of neighbors(maze, mazeCell)) {
      const nextKey = keyOf(next);
      if (seen.has(nextKey) || waterCellIsFlooded(next)) continue;
      seen.add(nextKey);
      queue.push({ row: next.row, col: next.col });
    }
  }
  return { ...origin };
}

function captureHelperMouse(reason = "trouble", captureCell = helperMouse) {
  if (!helperIsActive()) return false;
  if (helperCargo) {
    const dropCell = reason === "cat"
      ? captureCell ?? helperMouse
      : nearestHelperDropCell(captureCell ?? helperMouse);
    deliverHelperCargo(dropCell);
  }
  helperCaptured = true;
  helperMouse = null;
  helperMotion = null;
  helperResting = false;
  helperMode = "captured";
  helperTask = null;
  helperRecoveryTurns = 0;
  setMessage(
    reason === "flood"
      ? "The little helper was swept safely out of the maze."
      : `The little helper distracted the ${reason} and was carried out of the maze.`,
  );
  syncHelperDebugDataset();
  return true;
}

function commitHelperTurn(completedMotion = helperMotion) {
  helperMotion = null;
  if (!completedMotion || !helperIsActive()) return;
  const action = completedMotion.action;
  if (action?.type === "pushRock") {
    const rock = rockPositions.find((candidate) => candidate.id === action.id);
    const destinationBlocked =
      !rock ||
      keyOf(rock) !== keyOf(action.from) ||
      rockAt(action.to) ||
      milkBottleAt(action.to) ||
      milkPuddleAt(action.to) ||
      pieQuarterAt(action.to) ||
      carrotPatchAt(action.to) ||
      activeTunnelAt(action.to) ||
      fragileCellIsCollapsed(action.to, true) ||
      waterCellIsFlooded(action.to) ||
      keyOf(action.to) === keyOf(mouse) ||
      Boolean(car && keyOf(car) === keyOf(action.to)) ||
      remainingCheeseTargets().some((target) => keyOf(target) === keyOf(action.to));
    if (destinationBlocked) {
      helperMouse = { ...completedMotion.from };
      helperTask = null;
      helperMode = "follow";
      syncHelperDebugDataset();
      return;
    }
    rock.row = action.to.row;
    rock.col = action.to.col;
    helperMouse = { ...completedMotion.to };
    helperTestedRockIds.add(String(action.id));
    helperTask = null;
    helperMode = "follow";
    shortestPath = currentObjectiveRoute()?.path ?? [];
    syncActiveExit();
  } else {
    helperMouse = { ...completedMotion.to };
  }
  if (action?.type === "pickup") {
    pickupHelperObjective(action);
  } else if (action?.type === "deliver") {
    deliverHelperCargo(helperMouse);
  } else if (action?.type === "knockMilk") {
    const bottle = milkBottles.find(
      (candidate) => candidate.id === action.id,
    );
    if (bottle && !bottle.knocked) {
      bottle.knocked = true;
      bottle.direction = action.direction;
      bottle.spill = { ...action.spill };
    }
    helperTask = null;
    helperMode = "follow";
  } else if (action?.type === "tunnel") {
    helperTunnelCooldownTurns = HELPER_TUNNEL_COOLDOWN_TURNS;
    helperTask = null;
    helperMode = helperCargo ? "deliver" : "follow";
  }
  syncHelperCargoPosition();
  syncHelperDebugDataset();
}

function carTurnCaptureState(
  playerFrom,
  playerTo,
  completedHelperMotion,
  completedCarMotion,
) {
  if (!completedCarMotion) return { mouse: false, helper: false };
  const carFrom = completedCarMotion.from;
  const carTo = completedCarMotion.to;
  const caughtMouse = carCatchesMouse(
    maze,
    playerFrom,
    playerTo,
    carFrom,
    carTo,
  );
  if (!helperIsActive() || !helperMouse) {
    return { mouse: caughtMouse, helper: false };
  }
  const helperFrom = completedHelperMotion?.from ?? helperMouse;
  const helperTo = completedHelperMotion?.to ?? helperMouse;
  return {
    mouse: caughtMouse,
    helper: carCatchesMouse(maze, helperFrom, helperTo, carFrom, carTo),
  };
}

function helperCaughtByCar(completedHelperMotion, completedCarMotion) {
  return carTurnCaptureState(
    mouse,
    mouse,
    completedHelperMotion,
    completedCarMotion,
  ).helper;
}

function resetHelperRun() {
  helperMotion = null;
  helperCargo = null;
  helperCaptured = false;
  helperMouse = helperRequestedForRun && level >= HELPER_FIRST_LEVEL
    ? { ...levelStart }
    : null;
  helperFacingDirection = initialFacingForStart(levelStart);
  helperMode = helperMouse ? "observe" : "inactive";
  helperTask = null;
  helperPlayerTrail = helperMouse ? [{ ...levelStart }] : [];
  helperPlannerTurn = 0;
  helperRecoveryTurns = 0;
  helperDistractionCooldowns = { car: 0, cat: 0, crow: 0 };
  helperDecoyHistory = [];
  helperIntentCueUntil = 0;
  helperLastDecision = null;
  helperTestedRockIds = new Set();
  helperRockSafetyCache = new Map();
  helperTunnelCooldownTurns = 0;
  helperResting = false;
  syncHelperDebugDataset();
}

function shouldHoldFinalCheesePose() {
  return allObjectivesComplete();
}

function bottleSpillForDirection(bottle, directionKey) {
  const dir = DIRS.find((candidate) => candidate.key === directionKey);
  if (!dir) return null;
  return { row: bottle.row + dir.row, col: bottle.col + dir.col };
}

function solveMilkPuzzle(
  grid,
  start,
  bottles,
  targets,
  maxDistance = 72,
  initialCollectedCheeses = new Set(),
  initialCollectedMilk = new Set(),
  blockedKeys = new Set(),
) {
  const targetIndexByKey = new Map(targets.map((target, index) => [keyOf(target), index]));
  const allCheeseMask = (1 << targets.length) - 1;
  const allMilkMask = (1 << bottles.length) - 1;
  const initialCheeseMask = targets.reduce(
    (mask, target, index) => mask | (initialCollectedCheeses.has(keyOf(target)) ? 1 << index : 0),
    0,
  );
  const initialMilkMask = bottles.reduce(
    (mask, bottle, index) => mask | (initialCollectedMilk.has(bottle.id) ? 1 << index : 0),
    0,
  );
  const initialBottleStates = bottles.map((bottle) =>
    bottle.knocked ? DIRS.findIndex((dir) => dir.key === bottle.direction) + 1 : 0,
  );
  const queue = [{
    mouse: { ...start },
    bottleStates: initialBottleStates,
    cheeseMask: initialCheeseMask,
    milkMask: initialMilkMask,
    path: [{ ...start }],
    actions: [],
  }];
  const stateKey = (state) =>
    `${keyOf(state.mouse)}|${state.bottleStates.join("")}|${state.cheeseMask}|${state.milkMask}`;
  const seen = new Set([stateKey(queue[0])]);

  for (let queueIndex = 0; queueIndex < queue.length; queueIndex += 1) {
    const state = queue[queueIndex];
    if (state.cheeseMask === allCheeseMask && state.milkMask === allMilkMask) return state;
    if (state.actions.length >= maxDistance) continue;

    for (let directionIndex = 0; directionIndex < DIRS.length; directionIndex += 1) {
      const dir = DIRS[directionIndex];
      const currentCell = grid[state.mouse.row][state.mouse.col];
      if (currentCell.walls[dir.wall]) continue;
      const next = { row: state.mouse.row + dir.row, col: state.mouse.col + dir.col };
      if (!isInside(next.row, next.col)) continue;
      if (blockedKeys.has(keyOf(next))) continue;
      const bottleIndex = bottles.findIndex((bottle) => keyOf(bottle) === keyOf(next));

      if (bottleIndex >= 0) {
        if (state.bottleStates[bottleIndex] !== 0) continue;
        const bottle = bottles[bottleIndex];
        const bottleCell = grid[bottle.row][bottle.col];
        const spill = bottleSpillForDirection(bottle, dir.key);
        if (
          !spill ||
          !isInside(spill.row, spill.col) ||
          bottleCell.walls[dir.wall] ||
          blockedKeys.has(keyOf(spill)) ||
          bottles.some((candidate, index) => index !== bottleIndex && keyOf(candidate) === keyOf(spill)) ||
          targetIndexByKey.has(keyOf(spill))
        ) {
          continue;
        }
        const bottleStates = [...state.bottleStates];
        bottleStates[bottleIndex] = directionIndex + 1;
        const nextState = {
          ...state,
          bottleStates,
          path: [...state.path, { ...state.mouse }],
          actions: [...state.actions, { type: "knock", direction: dir.key, bottleId: bottle.id }],
        };
        const stateId = stateKey(nextState);
        if (!seen.has(stateId)) {
          seen.add(stateId);
          queue.push(nextState);
        }
        continue;
      }

      let blockedByFallenBottle = false;
      for (let index = 0; index < bottles.length; index += 1) {
        if (state.bottleStates[index] && keyOf(bottles[index]) === keyOf(next)) {
          blockedByFallenBottle = true;
          break;
        }
      }
      if (blockedByFallenBottle) continue;

      let cheeseMask = state.cheeseMask;
      const targetIndex = targetIndexByKey.get(keyOf(next));
      if (targetIndex !== undefined) cheeseMask |= 1 << targetIndex;
      let milkMask = state.milkMask;
      for (let index = 0; index < bottles.length; index += 1) {
        const encodedDirection = state.bottleStates[index];
        if (!encodedDirection) continue;
        const spill = bottleSpillForDirection(bottles[index], DIRS[encodedDirection - 1].key);
        if (keyOf(spill) === keyOf(next)) milkMask |= 1 << index;
      }
      const nextState = {
        mouse: next,
        bottleStates: [...state.bottleStates],
        cheeseMask,
        milkMask,
        path: [...state.path, { ...next }],
        actions: [...state.actions, { type: "move", direction: dir.key }],
      };
      const stateId = stateKey(nextState);
      if (seen.has(stateId)) continue;
      seen.add(stateId);
      queue.push(nextState);
    }
  }
  return null;
}

function nextCarStep(grid, from, target) {
  const path = findShortestPathFrom(grid, from, target);
  return path.length > 1 ? { ...path[1] } : { ...from };
}

function nextCarStepAvoiding(grid, from, target, blockedKeys = new Set()) {
  if (hasOpenPassageBetween(grid, from, target)) return { ...from };
  const queue = [{ ...from }];
  const previous = new Map([[keyOf(from), null]]);
  const targetKey = keyOf(target);
  while (queue.length) {
    const current = queue.shift();
    if (keyOf(current) === targetKey) break;
    const mazeCell = grid[current.row]?.[current.col];
    if (!mazeCell) continue;
    for (const next of neighbors(grid, mazeCell)) {
      const nextKey = keyOf(next);
      if (
        previous.has(nextKey) ||
        (nextKey !== targetKey && blockedKeys.has(nextKey))
      ) {
        continue;
      }
      previous.set(nextKey, keyOf(current));
      queue.push({ row: next.row, col: next.col });
    }
  }
  if (!previous.has(targetKey)) {
    const currentCell = grid[from.row]?.[from.col];
    const fallbackOptions = currentCell
      ? neighbors(grid, currentCell).filter((cell) => !blockedKeys.has(keyOf(cell)))
      : [];
    if (!fallbackOptions.length) return { ...from };
    fallbackOptions.sort((first, second) => {
      const firstPath = findShortestPathFrom(grid, first, target);
      const secondPath = findShortestPathFrom(grid, second, target);
      const firstDistance = firstPath.length ? firstPath.length - 1 : ROWS * COLS + 20;
      const secondDistance = secondPath.length ? secondPath.length - 1 : ROWS * COLS + 20;
      return firstDistance - secondDistance;
    });
    return { ...fallbackOptions[0] };
  }
  let cursor = targetKey;
  let parent = previous.get(cursor);
  while (parent && parent !== keyOf(from)) {
    cursor = parent;
    parent = previous.get(cursor);
  }
  return cellFromKey(cursor);
}

function areCardinallyAdjacent(first, second) {
  return Math.abs(first.row - second.row) + Math.abs(first.col - second.col) === 1;
}

function hasOpenPassageBetween(grid, first, second) {
  if (!areCardinallyAdjacent(first, second)) return false;
  const direction = DIRS.find(
    (item) =>
      first.row + item.row === second.row &&
      first.col + item.col === second.col,
  );
  if (!direction) return false;
  const firstCell = grid[first.row]?.[first.col];
  const secondCell = grid[second.row]?.[second.col];
  if (!firstCell || !secondCell) return false;
  return (
    !firstCell.walls[direction.wall] &&
    !secondCell.walls[direction.opposite]
  );
}

function nextCarStepForTurn(grid, carPosition, mousePosition) {
  if (grid === maze) {
    const blockedKeys = new Set([
      ...rockPositions.map(keyOf),
      ...(pie && !isPieCleared() ? pieFootprintCells(pie).map(keyOf) : []),
      ...carrotPatches
        .filter((patch) => !inspectedCarrotPatchIds.has(patch.id))
        .map(keyOf),
      ...floodedWaterKeys,
      ...collapsedFragileTileKeys,
    ]);
    const pendingCollapse = pendingFragileCollapseKey();
    if (pendingCollapse) blockedKeys.add(pendingCollapse);
    for (let attempt = 0; attempt < 8; attempt += 1) {
      const next = nextCarStepAvoiding(grid, carPosition, mousePosition, blockedKeys);
      if (keyOf(next) === keyOf(carPosition)) return next;
      const objectivePush = objectivePushForStep(carPosition, next);
      if (!objectivePush.blocked) return next;
      blockedKeys.add(keyOf(next));
    }
    return { ...carPosition };
  }
  return nextCarStep(grid, carPosition, mousePosition);
}

function carObjectivePushForStep(carFrom, carTo) {
  if (!carFrom || !carTo || keyOf(carFrom) === keyOf(carTo)) return null;
  return objectivePushForStep(carFrom, carTo).push;
}

function carHasLegalMove(grid, carPosition, blockedKeys = new Set()) {
  const cell = grid[carPosition.row]?.[carPosition.col];
  if (!cell) return false;
  return neighbors(grid, cell).some((next) => !blockedKeys.has(keyOf(next)));
}

function carBlockedKeysForPuzzle(result) {
  const blockedKeys = new Set([
    ...(result.rocks ?? []).map(keyOf),
    ...(result.milkBottles ?? []).map(keyOf),
    ...(result.carrotPatches ?? []).map(keyOf),
  ]);
  if (result.pie) {
    for (const cell of pieFootprintCells(result.pie)) blockedKeys.add(keyOf(cell));
  }
  return blockedKeys;
}

function carPlacementOffersActivePursuit(result, grid, start, carStart) {
  // Fallen bottles remain occupied for the whole run. Rocks and the pie can
  // change later, so temporary separation is handled by the patrol fallback.
  const blockedKeys = new Set((result.milkBottles ?? []).map(keyOf));
  const pursuitPath = findPathAvoidingCells(
    grid,
    carStart,
    start,
    blockedKeys,
  );
  return pursuitPath.length > 1;
}

function carPlacementOffersFairStart(result, grid, start, carStart) {
  const blockedKeys = carBlockedKeysForPuzzle(result);
  if (!carHasLegalMove(grid, carStart, blockedKeys)) return false;

  const distanceFromMouse = findShortestPathFrom(grid, carStart, start).length - 1;
  const minimumDistance = Math.min(8, Math.max(6, Math.floor((grid.length + grid[0].length) / 3)));
  if (distanceFromMouse < minimumDistance) return false;

  const safeOpeningMoves = neighbors(grid, grid[start.row]?.[start.col]).filter((next) => {
    if (blockedKeys.has(keyOf(next))) return false;
    const nextCar = nextCarStepAvoiding(grid, carStart, start, blockedKeys);
    return !carCatchesMouse(grid, start, next, carStart, nextCar);
  });
  if (!safeOpeningMoves.length) return false;

  // The catcher may chase later, but it must not begin by sealing the only
  // visible corridor to an objective. This keeps the opening readable and fair.
  const stationaryCarKey = new Set([keyOf(carStart)]);
  for (const target of result.exits ?? []) {
    if (!findPathAvoidingCells(grid, start, target, stationaryCarKey).length) return false;
  }

  return true;
}

function carCatchesMouse(grid, mouseFrom, mouseTo, carFrom, carTo) {
  const sameDestination = keyOf(mouseTo) === keyOf(carTo);
  const crossedPaths = keyOf(mouseFrom) === keyOf(carTo) && keyOf(mouseTo) === keyOf(carFrom);
  return (
    sameDestination ||
    crossedPaths ||
    hasOpenPassageBetween(grid, mouseTo, carTo)
  );
}

function solveCarPuzzle(grid, start, carStart, targets, maxDistance = 72) {
  const targetIndexByKey = new Map(targets.map((target, index) => [keyOf(target), index]));
  const allCollectedMask = (1 << targets.length) - 1;
  const queue = [{
    mouse: { ...start },
    car: { ...carStart },
    collectedMask: 0,
    path: [{ ...start }],
    carPath: [{ ...carStart }],
    actions: [],
  }];
  const stateKey = (state) => `${keyOf(state.mouse)}|${keyOf(state.car)}|${state.collectedMask}`;
  const seen = new Set([stateKey(queue[0])]);

  for (let queueIndex = 0; queueIndex < queue.length; queueIndex += 1) {
    const state = queue[queueIndex];
    if (state.collectedMask === allCollectedMask) return state;
    if (state.actions.length >= maxDistance) continue;
    for (const next of neighbors(grid, grid[state.mouse.row][state.mouse.col])) {
      if (keyOf(next) === keyOf(state.car)) continue;
      let collectedMask = state.collectedMask;
      const targetIndex = targetIndexByKey.get(keyOf(next));
      if (targetIndex !== undefined) collectedMask |= 1 << targetIndex;
      const nextCar = nextCarStepForTurn(grid, state.car, state.mouse);
      if (carCatchesMouse(grid, state.mouse, next, state.car, nextCar)) continue;
      const nextState = {
        mouse: { row: next.row, col: next.col },
        car: nextCar,
        collectedMask,
        path: [...state.path, { row: next.row, col: next.col }],
        carPath: [...state.carPath, nextCar],
        actions: [...state.actions, { direction: next.dir }],
      };
      const stateId = stateKey(nextState);
      if (seen.has(stateId)) continue;
      seen.add(stateId);
      queue.push(nextState);
    }
  }
  return null;
}

function solveRockPuzzle(grid, start, rocks, targets, maxDistance = 64) {
  const targetIndexByKey = new Map(targets.map((target, index) => [keyOf(target), index]));
  const allCollectedMask = (1 << targets.length) - 1;
  const normalizedRocks = rocks.map((rock) => ({ row: rock.row, col: rock.col }));
  const initialMask = targetIndexByKey.has(keyOf(start)) && !rockAt(start, normalizedRocks)
    ? 1 << targetIndexByKey.get(keyOf(start))
    : 0;
  const queue = [
    {
      mouse: { ...start },
      rocks: normalizedRocks,
      collectedMask: initialMask,
      path: [{ ...start }],
      actions: [],
      pushes: 0,
    },
  ];
  const stateKey = (state) => {
    const rockKeys = state.rocks.map(keyOf).sort().join(";");
    return `${keyOf(state.mouse)}|${rockKeys}|${state.collectedMask}`;
  };
  const seen = new Set([stateKey(queue[0])]);

  for (let queueIndex = 0; queueIndex < queue.length; queueIndex += 1) {
    const state = queue[queueIndex];
    if (state.collectedMask === allCollectedMask) return state;
    if (state.actions.length >= maxDistance) continue;

    for (const dir of DIRS) {
      const currentCell = grid[state.mouse.row][state.mouse.col];
      if (currentCell.walls[dir.wall]) continue;
      const next = { row: state.mouse.row + dir.row, col: state.mouse.col + dir.col };
      if (!isInside(next.row, next.col)) continue;

      const nextRocks = state.rocks.map((rock) => ({ ...rock }));
      const pushedRockIndex = nextRocks.findIndex(
        (rock) => rock.row === next.row && rock.col === next.col,
      );
      let rockFrom = null;
      let rockTo = null;
      if (pushedRockIndex >= 0) {
        const rockCell = grid[next.row][next.col];
        rockTo = { row: next.row + dir.row, col: next.col + dir.col };
        if (
          !isInside(rockTo.row, rockTo.col) ||
          rockCell.walls[dir.wall] ||
          rockAt(rockTo, nextRocks)
        ) {
          continue;
        }
        rockFrom = { ...nextRocks[pushedRockIndex] };
        nextRocks[pushedRockIndex] = { ...rockTo };
      }

      let collectedMask = state.collectedMask;
      const targetIndex = targetIndexByKey.get(keyOf(next));
      if (targetIndex !== undefined && !rockAt(next, nextRocks)) {
        collectedMask |= 1 << targetIndex;
      }
      const action = {
        direction: dir.key,
        mouse: { ...next },
        rockFrom,
        rockTo,
      };
      const nextState = {
        mouse: next,
        rocks: nextRocks,
        collectedMask,
        path: [...state.path, { ...next }],
        actions: [...state.actions, action],
        pushes: state.pushes + (pushedRockIndex >= 0 ? 1 : 0),
      };
      const key = stateKey(nextState);
      if (seen.has(key)) continue;
      seen.add(key);
      queue.push(nextState);
    }
  }

  return null;
}

function currentObjectiveRoute(grid = maze, start = mouse, rocks = rockPositions) {
  const routeGrid = runtimePathfindingGrid(grid);
  const targets = [...remainingCheeseTargets()];
  if (pie && !isPieCleared()) {
    const bottleBlockers = new Set(
      milkBottles
        .filter((bottle) => !bottle.glassDestroyed)
        .map(keyOf),
    );
    const solution = solvePiePuzzle(
      routeGrid,
      start,
      pie,
      80,
      eatenPieQuarterIds,
      bottleBlockers,
    );
    return solution ? { path: solution.path, order: [], solution } : null;
  }
  if (milkBottles.length) {
    const normalizedMilk = milkBottles.map((bottle) => ({
      ...bottle,
      knocked: Boolean(bottle.knocked),
      direction: bottle.direction,
    }));
    const solution = solveMilkPuzzle(
      routeGrid,
      start,
      normalizedMilk,
      targets,
      80,
      new Set(),
      collectedMilkIds,
    );
    return solution ? { path: solution.path, order: targets, solution } : null;
  }
  const carrotTargets = remainingCarrots();
  if (carrotTargets.length && !targets.length) {
    const sealedTunnelPatchIds = new Set(
      tunnels
        .filter((tunnel) => tunnel.sealed && tunnel.sourceCarrotPatchId)
        .map((tunnel) => tunnel.sourceCarrotPatchId),
    );
    const solution = solveCarrotSearchPuzzle(
      routeGrid,
      start,
      carrotPatches,
      carrotTargets.map((patch) => patch.id),
      {
        searchablePatchIds: carrotTargets.map((patch) => patch.id),
        initialInspectedIds: inspectedCarrotPatchIds,
        initialSealedTunnelPatchIds: sealedTunnelPatchIds,
      },
    );
    return solution ? { path: solution.path, order: solution.order, solution } : null;
  }
  if (!targets.length) return null;
  const pendingHingedWalls = hingedWalls.filter(
    (wall) => !wall.activated && !wall.destroyed && !wall.moving,
  );
  if (pendingHingedWalls.length) {
    const solution = solveHingedPuzzle(routeGrid, start, pendingHingedWalls, targets, 80);
    return solution ? { path: solution.path, order: targets, solution } : null;
  }
  if (!rocks.length) return bestCheeseRoute(routeGrid, start, targets);
  const solution = solveRockPuzzle(routeGrid, start, rocks, targets, 80);
  return solution ? { path: solution.path, order: targets, solution } : null;
}

function currentCheeseRoute(grid = maze, start = mouse) {
  return bestCheeseRoute(runtimePathfindingGrid(grid), start, remainingCheeseTargets());
}

function syncActiveExit() {
  const route = currentCheeseRoute();
  exit = route?.order[0] ? { ...route.order[0] } : null;
  return route;
}

function keyOf(cell) {
  return `${cell.row},${cell.col}`;
}

function fragileTileAt(cell) {
  if (!cell) return null;
  const cellKey = keyOf(cell);
  return fragileTiles.find((tile) => keyOf(tile) === cellKey) ?? null;
}

function pendingFragileCollapseKey() {
  if (!mouseMotion || keyOf(mouseMotion.from) === keyOf(mouseMotion.to)) return null;
  const fromKey = keyOf(mouseMotion.from);
  return crackedFragileTileKeys.has(fromKey) ? fromKey : null;
}

function fragileCellIsCollapsed(cell, includePending = false) {
  if (!cell) return false;
  const cellKey = keyOf(cell);
  return collapsedFragileTileKeys.has(cellKey) ||
    (includePending && pendingFragileCollapseKey() === cellKey);
}

function spiderWebAt(cell, includeBroken = false) {
  if (!cell) return null;
  const cellKey = keyOf(cell);
  return spiderWebs.find(
    (web) => keyOf(web) === cellKey && (includeBroken || !brokenSpiderWebIds.has(web.id)),
  ) ?? null;
}

function trapMouseInSpiderWebIfNeeded(cell) {
  const web = spiderWebAt(cell);
  if (!web) return false;
  mouseTrappedWebId = web.id;
  mouseSpiderWebTrapSettled = false;
  syncSpiderWebDebugDataset();
  return true;
}

function syncSpiderWebDebugDataset() {
  if (!mazeEl) return;
  mazeEl.dataset.testSpiderWebs = JSON.stringify({
    webs: spiderWebs.map((web) => ({ id: web.id, row: web.row, col: web.col })),
    broken: [...brokenSpiderWebIds],
    trapped: mouseTrappedWebId,
    settled: mouseSpiderWebTrapSettled,
    trapping: spiderWebTrapAnimation
      ? {
          id: spiderWebTrapAnimation.webId,
          progress: spiderWebTrapAnimation.progress,
        }
      : null,
    breaking: spiderWebBreakAnimation
      ? {
          id: spiderWebBreakAnimation.webId,
          progress: spiderWebBreakAnimation.progress,
        }
      : null,
  });
}

function syncFragileDebugDataset() {
  if (!mazeEl) return;
  mazeEl.dataset.testFragileTiles = JSON.stringify({
    tiles: fragileTiles.map((tile) => ({ row: tile.row, col: tile.col })),
    cracked: [...crackedFragileTileKeys],
    collapsed: [...collapsedFragileTileKeys],
    pending: pendingFragileCollapseKey(),
    falling: fragileFallAnimation
      ? {
          row: fragileFallAnimation.cell.row,
          col: fragileFallAnimation.cell.col,
          progress: fragileFallAnimation.progress,
        }
      : null,
  });
}

function runtimePathfindingGrid(grid = maze) {
  if (grid !== maze || !collapsedFragileTileKeys.size) return grid;
  const pathGrid = cloneMazeGrid(grid);
  for (const collapsedKey of collapsedFragileTileKeys) {
    blockGridCell(pathGrid, cellFromKey(collapsedKey));
  }
  return pathGrid;
}

function blockGridCell(grid, cell) {
  const blockedCell = grid[cell.row]?.[cell.col];
  if (!blockedCell) return;
  for (const direction of DIRS) {
    blockedCell.walls[direction.wall] = true;
    const neighbor = grid[cell.row + direction.row]?.[cell.col + direction.col];
    if (neighbor) neighbor.walls[direction.opposite] = true;
  }
}

function commitFragileMouseMotion(completedMotion) {
  if (!completedMotion) return false;
  const fromKey = keyOf(completedMotion.from);
  const toKey = keyOf(completedMotion.to);
  let collapsed = false;
  if (fromKey !== toKey && crackedFragileTileKeys.has(fromKey)) {
    crackedFragileTileKeys.delete(fromKey);
    collapsedFragileTileKeys.add(fromKey);
    collapsed = true;
  }
  if (fragileTileAt(completedMotion.to) && !collapsedFragileTileKeys.has(toKey)) {
    crackedFragileTileKeys.add(toKey);
  }
  syncFragileDebugDataset();
  return collapsed;
}

function mouseHasImmediateObjective() {
  return Boolean(
    cheeseAt(mouse) ||
    milkPuddleAt(mouse) ||
    remainingPieQuarters().some(
      (quarter) =>
        quarter.helperDeliveredCell &&
        keyOf(quarter.helperDeliveredCell) === keyOf(mouse),
    )
  );
}

function failIfFragileRunIsUnsolvable(allowImmediateObjective = true) {
  if (
    !collapsedFragileTileKeys.size ||
    allObjectivesComplete() ||
    (allowImmediateObjective && mouseHasImmediateObjective()) ||
    currentObjectiveRoute()
  ) {
    return false;
  }
  loseLevel("The fragile floor closed every route to the remaining objectives.", "blocked");
  return true;
}

function edgeKey(a, b) {
  return [keyOf(a), keyOf(b)].sort().join("|");
}

function cloneMazeGrid(grid) {
  return grid.map((row) =>
    row.map((cell) => ({
      ...cell,
      walls: { ...cell.walls },
    })),
  );
}

function segmentKey(segment) {
  return `${segment.orientation}:${segment.line}:${segment.start}`;
}

function edgeSegmentBetween(first, second) {
  if (first.row !== second.row) {
    return {
      orientation: "horizontal",
      line: Math.max(first.row, second.row),
      start: first.col,
      length: 1,
    };
  }
  return {
    orientation: "vertical",
    line: Math.max(first.col, second.col),
    start: first.row,
    length: 1,
  };
}

function segmentHasWall(grid, segment) {
  if (segment.orientation === "horizontal") {
    return Boolean(grid[segment.line]?.[segment.start]?.walls.top);
  }
  return Boolean(grid[segment.start]?.[segment.line]?.walls.left);
}

function setSegmentWall(grid, segment, present) {
  if (segment.orientation === "horizontal") {
    const lower = grid[segment.line]?.[segment.start];
    const upper = grid[segment.line - 1]?.[segment.start];
    if (!lower || !upper) return false;
    lower.walls.top = present;
    upper.walls.bottom = present;
    return true;
  }

  const right = grid[segment.start]?.[segment.line];
  const left = grid[segment.start]?.[segment.line - 1];
  if (!right || !left) return false;
  right.walls.left = present;
  left.walls.right = present;
  return true;
}

function segmentEndpoints(segment) {
  if (segment.orientation === "horizontal") {
    return [
      { row: segment.line, col: segment.start },
      { row: segment.line, col: segment.start + 1 },
    ];
  }
  return [
    { row: segment.start, col: segment.line },
    { row: segment.start + 1, col: segment.line },
  ];
}

function cellsSeparatedBySegment(segment) {
  if (segment.orientation === "horizontal") {
    return [
      { row: segment.line - 1, col: segment.start },
      { row: segment.line, col: segment.start },
    ];
  }
  return [
    { row: segment.start, col: segment.line - 1 },
    { row: segment.start, col: segment.line },
  ];
}

function perpendicularHingeSources(destination) {
  const [first, second] = segmentEndpoints(destination);
  const candidates = [];
  for (const hinge of [first, second]) {
    if (destination.orientation === "horizontal") {
      for (const start of [hinge.row - 1, hinge.row]) {
        if (hinge.col <= 0 || hinge.col >= COLS || start < 0 || start >= ROWS) continue;
        candidates.push({
          source: { orientation: "vertical", line: hinge.col, start, length: 1 },
          hinge: { ...hinge },
        });
      }
    } else {
      for (const start of [hinge.col - 1, hinge.col]) {
        if (hinge.row <= 0 || hinge.row >= ROWS || start < 0 || start >= COLS) continue;
        candidates.push({
          source: { orientation: "horizontal", line: hinge.row, start, length: 1 },
          hinge: { ...hinge },
        });
      }
    }
  }
  return candidates;
}

function otherSegmentEndpoint(segment, hinge) {
  return segmentEndpoints(segment).find(
    (point) => point.row !== hinge.row || point.col !== hinge.col,
  );
}

function pointToGridSegmentDistance(point, start, end) {
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const lengthSquared = dx * dx + dy * dy;
  if (!lengthSquared) return Math.hypot(point.x - start.x, point.y - start.y);
  const amount = clamp(
    ((point.x - start.x) * dx + (point.y - start.y) * dy) / lengthSquared,
    0,
    1,
  );
  return Math.hypot(
    point.x - (start.x + dx * amount),
    point.y - (start.y + dy * amount),
  );
}

function hingedSweepClearsCell(source, destination, hinge, cell) {
  const sourceOther = otherSegmentEndpoint(source, hinge);
  const destinationOther = otherSegmentEndpoint(destination, hinge);
  if (!sourceOther || !destinationOther) return false;
  const hingePoint = { x: hinge.col, y: hinge.row };
  const cellCenter = { x: cell.col + 0.5, y: cell.row + 0.5 };
  const sourceAngle = Math.atan2(
    sourceOther.row - hinge.row,
    sourceOther.col - hinge.col,
  );
  const destinationAngle = Math.atan2(
    destinationOther.row - hinge.row,
    destinationOther.col - hinge.col,
  );
  let angleDelta = destinationAngle - sourceAngle;
  while (angleDelta > Math.PI) angleDelta -= Math.PI * 2;
  while (angleDelta < -Math.PI) angleDelta += Math.PI * 2;

  for (let step = 0; step <= 20; step += 1) {
    const angle = sourceAngle + angleDelta * (step / 20);
    const end = {
      x: hingePoint.x + Math.cos(angle),
      y: hingePoint.y + Math.sin(angle),
    };
    if (pointToGridSegmentDistance(cellCenter, hingePoint, end) < 0.46) return false;
  }
  return true;
}

function wallPresentForHingedState(grid, segment, walls, activatedMask) {
  const key = segmentKey(segment);
  for (let index = 0; index < walls.length; index += 1) {
    if ((activatedMask & (1 << index)) === 0) continue;
    if (segmentKey(walls[index].source) === key) return false;
    if (segmentKey(walls[index].destination) === key) return true;
  }
  return segmentHasWall(grid, segment);
}

function solveHingedPuzzle(grid, start, walls, targets, maxMoves = 80) {
  const targetIndexByKey = new Map(targets.map((target, index) => [keyOf(target), index]));
  const allCollectedMask = (1 << targets.length) - 1;
  const initialCollectedMask = targetIndexByKey.has(keyOf(start))
    ? 1 << targetIndexByKey.get(keyOf(start))
    : 0;
  const queue = [
    {
      mouse: { ...start },
      activatedMask: 0,
      collectedMask: initialCollectedMask,
      moves: 0,
      path: [{ ...start }],
      actions: [],
    },
  ];
  const bestCosts = new Map([[`${keyOf(start)}|0|${initialCollectedMask}`, 0]]);

  while (queue.length) {
    const state = queue.shift();
    if (state.collectedMask === allCollectedMask) {
      return {
        ...state,
        triggers: state.actions.reduce(
          (total, action) => total + (action.hingedWallIds?.length ?? 0),
          0,
        ),
      };
    }
    if (state.moves >= maxMoves) continue;

    for (const dir of DIRS) {
      const next = { row: state.mouse.row + dir.row, col: state.mouse.col + dir.col };
      if (!isInside(next.row, next.col)) continue;
      const segment = edgeSegmentBetween(state.mouse, next);
      if (wallPresentForHingedState(grid, segment, walls, state.activatedMask)) continue;
      let activatedMask = state.activatedMask;
      const hingedWallIds = [];
      walls.forEach((wall, index) => {
        if (
          (activatedMask & (1 << index)) === 0 &&
          keyOf(wall.triggerFrom) === keyOf(next)
        ) {
          activatedMask |= 1 << index;
          hingedWallIds.push(wall.id);
        }
      });
      let collectedMask = state.collectedMask;
      const targetIndex = targetIndexByKey.get(keyOf(next));
      if (targetIndex !== undefined) collectedMask |= 1 << targetIndex;
      const moves = state.moves + 1;
      const key = `${keyOf(next)}|${activatedMask}|${collectedMask}`;
      if ((bestCosts.get(key) ?? Number.POSITIVE_INFINITY) <= moves) continue;
      bestCosts.set(key, moves);
      queue.push({
        mouse: next,
        activatedMask,
        collectedMask,
        moves,
        path: [...state.path, { ...next }],
        actions: [
          ...state.actions,
          { direction: dir.key, mouse: { ...next }, hingedWallIds },
        ],
      });
    }
  }

  return null;
}

function countTurns(path) {
  let turns = 0;
  let last = null;
  for (let i = 1; i < path.length; i += 1) {
    const previous = path[i - 1];
    const current = path[i];
    const dir = `${Math.sign(current.row - previous.row)},${Math.sign(current.col - previous.col)}`;
    if (last && dir !== last) turns += 1;
    last = dir;
  }
  return turns;
}

function countDeadEnds(grid) {
  let deadEnds = 0;
  for (const row of grid) {
    for (const cell of row) {
      if (!cell.active) continue;
      const openSides = DIRS.filter((dir) => !cell.walls[dir.wall]).length;
      if (openSides === 1) deadEnds += 1;
    }
  }
  return deadEnds;
}

function countRoutesToExit(grid, target, limit = 3, start = levelStart) {
  let routes = 0;
  const seen = new Set();

  function walk(cell) {
    if (routes >= limit) return;
    if (cell.row === target.row && cell.col === target.col) {
      routes += 1;
      return;
    }

    seen.add(keyOf(cell));
    for (const next of neighbors(grid, grid[cell.row][cell.col])) {
      const key = keyOf(next);
      if (!seen.has(key)) walk(next);
      if (routes >= limit) break;
    }
    seen.delete(keyOf(cell));
  }

  walk(start);
  return routes;
}

function findMeaningfulAlternative(grid, target, path, moveLimit, minDifferentEdges = 6) {
  const shortestDistance = path.length - 1;
  const shortestEdges = new Set();
  const start = path[0] ?? levelStart;

  for (let i = 1; i < path.length; i += 1) {
    shortestEdges.add(edgeKey(path[i - 1], path[i]));
  }

  for (const blockedEdge of shortestEdges) {
    const alternate = findShortestPath(
      grid,
      target,
      new Set([blockedEdge]),
      start,
    );
    if (!alternate.length) continue;

    const alternateDistance = alternate.length - 1;
    if (alternateDistance > moveLimit) continue;

    const alternateEdges = new Set();
    for (let i = 1; i < alternate.length; i += 1) {
      alternateEdges.add(edgeKey(alternate[i - 1], alternate[i]));
    }

    let differentEdges = 0;
    for (const edge of alternateEdges) {
      if (!shortestEdges.has(edge)) differentEdges += 1;
    }

    if (differentEdges >= minDifferentEdges) return alternate;
  }

  return null;
}

function findOverBudgetTrickPath(grid, target, path, moveLimit, minDifferentEdges = 4) {
  const pathKeys = new Set(path.map(keyOf));
  const goalDistance = (cell) => Math.abs(cell.row - target.row) + Math.abs(cell.col - target.col);
  let best = null;

  const latestUsefulBranch = Math.max(
    1,
    Math.floor((path.length - 1) * (ROWS <= 7 ? 1 : 0.78)),
  );
  for (let pathIndex = 0; pathIndex < latestUsefulBranch; pathIndex += 1) {
    const branchOrigin = path[pathIndex];
    const branchEntries = neighbors(grid, grid[branchOrigin.row][branchOrigin.col]).filter(
      (next) => !pathKeys.has(keyOf(next)) && goalDistance(next) <= goalDistance(branchOrigin),
    );
    for (const entry of branchEntries) {
      const queue = [{ cell: { ...entry }, route: [{ ...entry }] }];
      const seen = new Set([keyOf(entry)]);
      let deepest = queue[0];
      while (queue.length) {
        const current = queue.shift();
        if (current.route.length > deepest.route.length) deepest = current;
        for (const next of neighbors(grid, grid[current.cell.row][current.cell.col])) {
          const nextKey = keyOf(next);
          if (pathKeys.has(nextKey) || seen.has(nextKey)) continue;
          seen.add(nextKey);
          queue.push({
            cell: { row: next.row, col: next.col },
            route: [...current.route, { row: next.row, col: next.col }],
          });
        }
      }

      const outward = deepest.route;
      if (outward.length < minDifferentEdges) continue;
      const returnTrip = [...outward].reverse().slice(1);
      const trickPath = [
        ...path.slice(0, pathIndex + 1),
        ...outward,
        ...returnTrip,
        { ...branchOrigin },
        ...path.slice(pathIndex + 1),
      ];
      const distance = trickPath.length - 1;
      if (distance <= moveLimit) continue;
      const result = {
        path: trickPath,
        distance,
        excess: distance - moveLimit,
        differentEdges: outward.length,
        divergenceIndex: pathIndex + 1,
        deadEnd: { ...deepest.cell },
      };
      if (!best || result.excess < best.excess) best = result;
    }
  }
  return best;
}

function moveBudgetForVariant(path, alternatePath) {
  const shortestDistance = Math.max(0, path.length - 1);
  const alternateDistance = Math.max(shortestDistance, alternatePath.length - 1);
  const recoveryMargin = clamp(Math.ceil(shortestDistance * 0.3), 4, 7);
  return Math.max(shortestDistance + recoveryMargin, alternateDistance);
}

function configuredMoveBudget(config, distance) {
  if (Number.isFinite(config.moveBudget)) return Math.floor(config.moveBudget);
  if (Number.isFinite(config.moveMarginRatio)) {
    return distance + Math.max(2, Math.ceil(distance * config.moveMarginRatio));
  }
  return null;
}

function analyzeDeceptiveBranches(grid, path, target) {
  const pathKeys = new Set(path.map(keyOf));
  let solutionJunctions = 0;
  let falseBranches = 0;
  let deepFalseBranches = 0;
  let falseBranchCells = 0;
  let maxFalseBranchDepth = 0;
  let earlyDeepBranches = 0;
  let goalFacingBranches = 0;
  let misleadingBranches = 0;
  let misleadingBranchCells = 0;
  let nearGoalTraps = 0;

  for (let pathIndex = 0; pathIndex < path.length; pathIndex += 1) {
    const pathCell = path[pathIndex];
    const branchEntries = neighbors(grid, grid[pathCell.row][pathCell.col]).filter(
      (neighbor) => !pathKeys.has(keyOf(neighbor)),
    );
    if (branchEntries.length) solutionJunctions += 1;

    for (const entry of branchEntries) {
      const queue = [{ row: entry.row, col: entry.col, depth: 1 }];
      const seen = new Set([keyOf(pathCell), keyOf(entry)]);
      let branchCells = 0;
      let branchDepth = 0;
      let branchGoalDistance = Number.POSITIVE_INFINITY;

      while (queue.length) {
        const current = queue.shift();
        branchCells += 1;
        branchDepth = Math.max(branchDepth, current.depth);
        branchGoalDistance = Math.min(
          branchGoalDistance,
          Math.abs(current.row - target.row) + Math.abs(current.col - target.col),
        );
        for (const next of neighbors(grid, grid[current.row][current.col])) {
          const nextKey = keyOf(next);
          if (pathKeys.has(nextKey) || seen.has(nextKey)) continue;
          seen.add(nextKey);
          queue.push({ row: next.row, col: next.col, depth: current.depth + 1 });
        }
      }

      falseBranches += 1;
      falseBranchCells += branchCells;
      maxFalseBranchDepth = Math.max(maxFalseBranchDepth, branchDepth);
      if (branchDepth >= 4) {
        deepFalseBranches += 1;
        if (pathIndex < path.length * 0.65) earlyDeepBranches += 1;
      }

      const pathDistance = Math.abs(pathCell.row - target.row) + Math.abs(pathCell.col - target.col);
      const entryDistance = Math.abs(entry.row - target.row) + Math.abs(entry.col - target.col);
      if (branchDepth >= 3 && entryDistance < pathDistance) goalFacingBranches += 1;

      const correctNext = path[pathIndex + 1];
      const correctDistance = correctNext
        ? Math.abs(correctNext.row - target.row) + Math.abs(correctNext.col - target.col)
        : -1;
      if (branchDepth >= 2 && correctNext && entryDistance <= correctDistance) {
        misleadingBranches += 1;
        misleadingBranchCells += branchCells;
      }
      if (branchDepth >= 3 && branchGoalDistance <= 1) nearGoalTraps += 1;
    }
  }

  const greedyMoves = simulateGreedyMazeSolver(grid, path[0], target);
  const greedyPenalty = greedyMoves - (path.length - 1);
  const startGoalManhattan =
    Math.abs(path[0].row - target.row) + Math.abs(path[0].col - target.col);
  const pathRows = path.map((cell) => cell.row);
  const pathCols = path.map((cell) => cell.col);
  let maxStraightRun = 0;
  let currentStraightRun = 0;
  let previousDirection = null;

  for (let index = 1; index < path.length; index += 1) {
    const direction = `${path[index].row - path[index - 1].row},${path[index].col - path[index - 1].col}`;
    currentStraightRun = direction === previousDirection ? currentStraightRun + 1 : 1;
    maxStraightRun = Math.max(maxStraightRun, currentStraightRun);
    previousDirection = direction;
  }

  return {
    solutionJunctions,
    falseBranches,
    deepFalseBranches,
    falseBranchCells,
    maxFalseBranchDepth,
    earlyDeepBranches,
    goalFacingBranches,
    misleadingBranches,
    misleadingBranchCells,
    nearGoalTraps,
    greedyMoves,
    greedyPenalty,
    startGoalManhattan,
    maxStraightRun,
    pathRowSpan: Math.max(...pathRows) - Math.min(...pathRows) + 1,
    pathColSpan: Math.max(...pathCols) - Math.min(...pathCols) + 1,
  };
}

function simulateGreedyMazeSolver(grid, start, target) {
  const visited = new Set([keyOf(start)]);
  const stack = [{ cell: { ...start }, options: null }];
  let moves = 0;

  while (stack.length) {
    const frame = stack[stack.length - 1];
    if (frame.cell.row === target.row && frame.cell.col === target.col) return moves;

    if (frame.options === null) {
      frame.options = neighbors(grid, grid[frame.cell.row][frame.cell.col])
        .filter((neighbor) => !visited.has(keyOf(neighbor)))
        .sort((first, second) => {
          const firstDistance = Math.abs(first.row - target.row) + Math.abs(first.col - target.col);
          const secondDistance = Math.abs(second.row - target.row) + Math.abs(second.col - target.col);
          if (firstDistance !== secondDistance) return firstDistance - secondDistance;
          return keyOf(first).localeCompare(keyOf(second));
        });
    }

    const next = frame.options.shift();
    if (next) {
      visited.add(keyOf(next));
      stack.push({ cell: { row: next.row, col: next.col }, options: null });
      moves += 1;
      continue;
    }

    stack.pop();
    if (stack.length) moves += 1;
  }

  return Number.POSITIVE_INFINITY;
}

function extremeDifficultyScore(profile) {
  return (
    profile.solutionJunctions * 16 +
    profile.falseBranches * 10 +
    profile.deepFalseBranches * 24 +
    profile.maxFalseBranchDepth * 12 +
    profile.goalFacingBranches * 30 +
    profile.misleadingBranches * 55 +
    profile.misleadingBranchCells * 4 +
    profile.nearGoalTraps * 90 +
    Math.min(profile.greedyPenalty, 80) * 5 +
    Math.max(0, 12 - profile.startGoalManhattan) * 18
  );
}

function passesExtremeDifficulty(config, profile) {
  if (!profile) return true;
  const rules = [
    ["solutionJunctions", "minSolutionJunctions", "maxSolutionJunctions"],
    ["falseBranches", "minFalseBranches", "maxFalseBranches"],
    ["deepFalseBranches", "minDeepFalseBranches", "maxDeepFalseBranches"],
    ["falseBranchCells", "minFalseBranchCells", "maxFalseBranchCells"],
    ["maxFalseBranchDepth", "minFalseBranchDepth", "maxFalseBranchDepth"],
    ["earlyDeepBranches", "minEarlyDeepBranches", "maxEarlyDeepBranches"],
    ["goalFacingBranches", "minGoalFacingBranches", "maxGoalFacingBranches"],
    ["misleadingBranches", "minMisleadingBranches", "maxMisleadingBranches"],
    ["misleadingBranchCells", "minMisleadingBranchCells", "maxMisleadingBranchCells"],
    ["nearGoalTraps", "minNearGoalTraps", "maxNearGoalTraps"],
    ["greedyPenalty", "minGreedyPenalty", "maxGreedyPenalty"],
    ["maxStraightRun", "minStraightRun", "maxStraightRun"],
    ["pathRowSpan", "minPathRowSpan", "maxPathRowSpan"],
    ["pathColSpan", "minPathColSpan", "maxPathColSpan"],
  ];
  if (rules.some(([metric, minimum]) => config[minimum] !== undefined && profile[metric] < config[minimum])) {
    return false;
  }
  if (rules.some(([metric, , maximum]) => config[maximum] !== undefined && profile[metric] > config[maximum])) {
    return false;
  }
  return config.maxGoalManhattan === undefined || profile.startGoalManhattan <= config.maxGoalManhattan;
}

function chooseExitAndValidate(grid, config, variantIndex, start, rng) {
  const singleRoute = config.singleRoute === true;
  let hardestResult = null;
  const exits = shuffle(
    Array.from({ length: ROWS * COLS }, (_, index) => ({
      row: Math.floor(index / COLS),
      col: index % COLS,
    })).filter(
      (candidate) =>
        isInside(candidate.row, candidate.col) &&
        (candidate.row !== start.row || candidate.col !== start.col) &&
        (candidate.row * 3 + candidate.col * 2) % VARIANTS_PER_LEVEL === variantIndex,
    ),
    rng,
  );

  for (const candidate of exits) {
    const path = findShortestPath(grid, candidate, new Set(), start);
    if (!path.length) continue;

    const distance = path.length - 1;
    const configuredBudget = configuredMoveBudget(config, distance);
    const turns = countTurns(path);
    const deadEnds = countDeadEnds(grid);
    const routes = countRoutesToExit(grid, candidate, 3, start);
    const alternatePath = singleRoute
      ? null
      : findMeaningfulAlternative(
          grid,
          candidate,
          path,
          configuredBudget ?? config.moveLimit,
          config.minAlternateEdges ?? 6,
        );
    const finalMoveLimit = singleRoute
      ? distance + (config.moveMargin ?? 1)
      : configuredBudget ?? moveBudgetForVariant(path, alternatePath ?? path);
    const trickPath = findOverBudgetTrickPath(
      grid,
      candidate,
      path,
      finalMoveLimit,
      config.minTrickDifferentEdges ?? (ROWS <= 5 ? 1 : ROWS <= 7 ? 2 : 3),
    );
    const difficultyProfile = config.minSolutionJunctions || config.maxSolutionJunctions
      ? analyzeDeceptiveBranches(grid, path, candidate)
      : null;
    const routeRulesPass = singleRoute
      ? routes === 1
      : routes >= 2 && routes <= (config.maxRoutes ?? Number.POSITIVE_INFINITY) && Boolean(alternatePath);

    if (
      distance >= config.minPath &&
      distance <= config.maxPath &&
      turns >= (config.minTurns ?? 4) &&
      turns <= (config.maxTurns ?? Number.POSITIVE_INFINITY) &&
      deadEnds >= (config.minDeadEnds ?? 5) &&
      deadEnds <= (config.maxDeadEnds ?? 38) &&
      routeRulesPass &&
      Boolean(trickPath) &&
      passesExtremeDifficulty(config, difficultyProfile)
    ) {
      const result = {
        exit: candidate,
        path,
        alternatePath,
        trickPath: trickPath.path,
        trickPathProfile: trickPath,
        difficultyProfile,
        moveLimit: finalMoveLimit,
      };
      if (!singleRoute) return result;
      const score = extremeDifficultyScore(difficultyProfile);
      if (!hardestResult || score > hardestResult.difficultyScore) {
        hardestResult = { ...result, difficultyScore: score };
      }
    }
  }

  return hardestResult;
}

function cheeseRouteOptions(grid, start, targets) {
  const pathCache = new Map();
  const pathBetween = (from, to) => {
    const cacheKey = `${keyOf(from)}>${keyOf(to)}`;
    if (!pathCache.has(cacheKey)) {
      pathCache.set(cacheKey, findShortestPathFrom(grid, from, to));
    }
    return pathCache.get(cacheKey);
  };
  const routes = [];

  function visit(order, remaining, path, current) {
    if (!remaining.length) {
      routes.push({ order: order.map((target) => ({ ...target })), path });
      return;
    }
    for (let index = 0; index < remaining.length; index += 1) {
      const target = remaining[index];
      const segment = pathBetween(current, target);
      if (!segment.length) continue;
      visit(
        [...order, target],
        remaining.filter((_, targetIndex) => targetIndex !== index),
        joinPaths(path, segment),
        target,
      );
    }
  }

  visit([], targets, [{ ...start }], start);
  return routes.sort((first, second) => first.path.length - second.path.length);
}

function chooseCheeseTargetsAndValidate(grid, config, variantIndex, start, rng) {
  const cheeseCount = clamp(Math.floor(config.cheeseCount ?? 1), 2, MAX_CHEESES_PER_LEVEL);
  const candidates = shuffle(
    Array.from({ length: ROWS * COLS }, (_, index) => ({
      row: Math.floor(index / COLS),
      col: index % COLS,
    })).filter(
      (candidate) =>
        isInside(candidate.row, candidate.col) &&
        keyOf(candidate) !== keyOf(start) &&
        (candidate.row * 3 + candidate.col * 2) % VARIANTS_PER_LEVEL !== variantIndex,
    ),
    rng,
  );
  const candidateLimit = cheeseCount === 3 ? 18 : Math.min(30, candidates.length);
  const usableCandidates = candidates.slice(0, candidateLimit);
  const targetSets = [];
  function collectTargetSets(startIndex, selected) {
    if (selected.length === cheeseCount) {
      targetSets.push(selected.map((target) => ({ ...target })));
      return;
    }
    for (
      let index = startIndex;
      index <= usableCandidates.length - (cheeseCount - selected.length);
      index += 1
    ) {
      collectTargetSets(index + 1, [...selected, usableCandidates[index]]);
    }
  }
  collectTargetSets(0, []);

  for (const targets of shuffle(targetSets, rng)) {
    let targetsSeparated = true;
    for (let firstIndex = 0; firstIndex < targets.length; firstIndex += 1) {
      for (let secondIndex = firstIndex + 1; secondIndex < targets.length; secondIndex += 1) {
        const first = targets[firstIndex];
        const second = targets[secondIndex];
        const separation = Math.abs(first.row - second.row) + Math.abs(first.col - second.col);
        const betweenPath = findShortestPathFrom(grid, first, second);
        if (
          separation < (config.minCheeseSeparation ?? 4) ||
          !betweenPath.length ||
          betweenPath.length - 1 < (config.minCheeseDistance ?? 5)
        ) {
          targetsSeparated = false;
          break;
        }
      }
      if (!targetsSeparated) break;
    }
    if (!targetsSeparated) continue;

    const routes = cheeseRouteOptions(grid, start, targets);
    if (routes.length < 2) continue;
    const optimal = routes[0];
    const alternate = routes.find(
      (route) => route.order.map(keyOf).join("|") !== optimal.order.map(keyOf).join("|"),
    );
    if (!alternate) continue;
    const optimalDistance = optimal.path.length - 1;
    const orderPenalty = alternate.path.length - optimal.path.length;
    if (
      optimalDistance < config.minPath ||
      optimalDistance > config.maxPath ||
      alternate.path.length - 1 > optimalDistance + config.moveMargin ||
      orderPenalty < (config.minOrderPenalty ?? 1) ||
      orderPenalty > (config.maxOrderPenalty ?? Number.POSITIVE_INFINITY) ||
      countTurns(optimal.path) < config.minTurns ||
      countDeadEnds(grid) < config.minDeadEnds
    ) {
      continue;
    }

    const moveLimit = optimalDistance + config.moveMargin;
    const finalTarget = optimal.order[optimal.order.length - 1];
    const trickPath = findOverBudgetTrickPath(
      grid,
      finalTarget,
      optimal.path,
      moveLimit,
      config.minTrickDifferentEdges ?? 3,
    );
    if (!trickPath) continue;

    return {
      exit: { ...optimal.order[0] },
      exits: optimal.order.map((target) => ({ ...target })),
      path: optimal.path,
      alternatePath: alternate.path,
      trickPath: trickPath.path,
      trickPathProfile: trickPath,
      difficultyProfile: null,
      orderPenalty,
      moveLimit,
    };
  }

  return null;
}

function solveCarrotSearchPuzzle(
  grid,
  start,
  patches,
  requiredPatchIds,
  {
    searchablePatchIds = requiredPatchIds,
    initialInspectedIds = new Set(),
    initialSealedTunnelPatchIds = new Set(),
    maxActions = 120,
  } = {},
) {
  if (!grid?.length || !start || !patches?.length) return null;
  const patchIndexById = new Map(patches.map((patch, index) => [patch.id, index]));
  const patchIndexByCell = new Map(patches.map((patch, index) => [keyOf(patch), index]));
  const requiredIds = new Set(requiredPatchIds);
  const searchableIds = new Set(searchablePatchIds);
  const requiredMask = patches.reduce(
    (mask, patch, index) => mask | (requiredIds.has(patch.id) ? 1 << index : 0),
    0,
  );
  const falseMask = patches.reduce(
    (mask, patch, index) => mask | (!patch.hasCarrot ? 1 << index : 0),
    0,
  );
  const initialSearchedMask = patches.reduce(
    (mask, patch, index) => mask | (initialInspectedIds.has(patch.id) ? 1 << index : 0),
    0,
  );
  const initialSealedMask = patches.reduce(
    (mask, patch, index) =>
      mask | (initialSealedTunnelPatchIds.has(patch.id) ? 1 << index : 0),
    0,
  );
  const stateKey = (state) =>
    `${keyOf(state.mouse)}|${state.searchedMask}|${state.sealedMask}`;
  const queue = [{
    mouse: { ...start },
    searchedMask: initialSearchedMask,
    sealedMask: initialSealedMask,
    path: [{ ...start }],
    actions: [],
    order: [],
  }];
  const seen = new Set([stateKey(queue[0])]);

  const enqueue = (state) => {
    if (state.actions.length > maxActions) return;
    const identity = stateKey(state);
    if (seen.has(identity)) return;
    seen.add(identity);
    queue.push(state);
  };

  for (let queueIndex = 0; queueIndex < queue.length; queueIndex += 1) {
    const state = queue[queueIndex];
    if ((state.searchedMask & requiredMask) === requiredMask) return state;
    if (state.actions.length >= maxActions) continue;

    for (const direction of DIRS) {
      const patchCell = {
        row: state.mouse.row + direction.row,
        col: state.mouse.col + direction.col,
      };
      const patchIndex = patchIndexByCell.get(keyOf(patchCell));
      if (patchIndex === undefined) continue;
      const patch = patches[patchIndex];
      const patchBit = 1 << patchIndex;
      if (
        state.searchedMask & patchBit ||
        !searchableIds.has(patch.id) ||
        !hasOpenPassageBetween(grid, state.mouse, patch)
      ) {
        continue;
      }
      enqueue({
        mouse: { ...state.mouse },
        searchedMask: state.searchedMask | patchBit,
        sealedMask: state.sealedMask,
        path: [...state.path, { ...state.mouse }],
        actions: [
          ...state.actions,
          {
            type: "carrot",
            patchId: patch.id,
            hasCarrot: Boolean(patch.hasCarrot),
            direction: direction.key,
            inputTarget: { row: patch.row, col: patch.col },
            mouseTarget: { ...state.mouse },
          },
        ],
        order: [...state.order, { ...patch }],
      });
    }

    const mazeCell = grid[state.mouse.row]?.[state.mouse.col];
    if (!mazeCell) continue;
    for (const next of neighbors(grid, mazeCell)) {
      const nextPatchIndex = patchIndexByCell.get(keyOf(next));
      if (
        nextPatchIndex !== undefined &&
        !(state.searchedMask & (1 << nextPatchIndex))
      ) {
        continue;
      }
      const direction = DIRS.find(
        (candidate) =>
          state.mouse.row + candidate.row === next.row &&
          state.mouse.col + candidate.col === next.col,
      );
      if (!direction) continue;
      const baseAction = {
        type: "move",
        direction: direction.key,
        inputTarget: { row: next.row, col: next.col },
        mouseTarget: { row: next.row, col: next.col },
      };
      const enteredFalseTunnel =
        nextPatchIndex !== undefined &&
        Boolean(falseMask & (1 << nextPatchIndex)) &&
        Boolean(state.searchedMask & (1 << nextPatchIndex)) &&
        !Boolean(state.sealedMask & (1 << nextPatchIndex));
      if (!enteredFalseTunnel) {
        enqueue({
          ...state,
          mouse: { row: next.row, col: next.col },
          path: [...state.path, { row: next.row, col: next.col }],
          actions: [...state.actions, baseAction],
        });
        continue;
      }

      const activeFalseMask = state.searchedMask & falseMask & ~state.sealedMask;
      const destinations = patches.filter((patch, index) =>
        index !== nextPatchIndex && Boolean(activeFalseMask & (1 << index)),
      );
      if (!destinations.length) continue;

      for (const destination of destinations) {
        const destinationIndex = patchIndexById.get(destination.id);
        let sealedMask = state.sealedMask | (1 << destinationIndex);
        const remainingActiveMask = activeFalseMask & ~sealedMask;
        if ((remainingActiveMask & (remainingActiveMask - 1)) === 0) {
          sealedMask |= remainingActiveMask;
        }
        enqueue({
          ...state,
          mouse: { row: destination.row, col: destination.col },
          sealedMask,
          path: [...state.path, { row: next.row, col: next.col }],
          actions: [
            ...state.actions,
            {
              ...baseAction,
              tunnelDestination: {
                row: destination.row,
                col: destination.col,
                patchId: destination.id,
              },
            },
          ],
        });
      }
    }
  }

  return null;
}

function carrotMovementTurns(path) {
  const movementPath = path.filter(
    (cell, index) => index === 0 || keyOf(cell) !== keyOf(path[index - 1]),
  );
  return countTurns(movementPath);
}

function chooseCarrotSearchPuzzleAndValidate(grid, config, variantIndex, start, rng) {
  const carrotCount = clamp(Math.floor(config.carrotCount ?? 2), 1, 2);
  const patchCount = clamp(
    Math.floor(config.carrotPatchCount ?? carrotCount + 2),
    carrotCount,
    MAX_CARROT_PATCHES_PER_LEVEL,
  );
  const candidates = objectivePlacementCandidates(start, variantIndex, rng).filter((candidate) => {
    const path = findShortestPathFrom(grid, start, candidate);
    return path.length - 1 >= 4;
  });
  const minimumSeparation = config.minCarrotSeparation ?? 3;
  const minimumLuckGap = config.minCarrotLuckGap ?? 4;

  for (let placementAttempt = 0; placementAttempt < 420; placementAttempt += 1) {
    const patches = shuffle(candidates, rng).slice(0, patchCount);
    if (patches.length !== patchCount) continue;
    const wellSeparated = patches.every((first, firstIndex) =>
      patches.every((second, secondIndex) =>
        firstIndex === secondIndex ||
        findShortestPathFrom(grid, first, second).length - 1 >= minimumSeparation,
      ),
    );
    if (!wellSeparated) continue;

    const realKeys = new Set(patches.slice(0, carrotCount).map(keyOf));
    const carrotPatches = patches.map((patch, index) => ({
      id: `carrot-patch-${index}`,
      row: patch.row,
      col: patch.col,
      hasCarrot: realKeys.has(keyOf(patch)),
    }));
    const realTargets = carrotPatches.filter((patch) => patch.hasCarrot);
    const falseTargets = carrotPatches.filter((patch) => !patch.hasCarrot);
    const realIds = realTargets.map((patch) => patch.id);
    const optimal = solveCarrotSearchPuzzle(
      grid,
      start,
      carrotPatches,
      realIds,
      { searchablePatchIds: realIds },
    );
    if (!optimal) continue;
    const optimalDistance = optimal.actions.length;
    if (
      optimalDistance < config.minPath ||
      optimalDistance > config.maxPath ||
      carrotMovementTurns(optimal.path) < config.minTurns ||
      countDeadEnds(grid) < config.minDeadEnds
    ) {
      continue;
    }

    const oneFalseRoutes = falseTargets
      .map((falseTarget) => {
        const requiredIds = [...realIds, falseTarget.id];
        return solveCarrotSearchPuzzle(
          grid,
          start,
          carrotPatches,
          requiredIds,
          { searchablePatchIds: requiredIds },
        );
      })
      .filter(Boolean);
    if (oneFalseRoutes.length !== falseTargets.length) continue;
    const supportedRoute = oneFalseRoutes.reduce((longest, route) =>
      route.actions.length > longest.actions.length ? route : longest,
    );
    const supportedDistance = supportedRoute.actions.length;
    const allPatchIds = carrotPatches.map((patch) => patch.id);
    const allPatchesRoute = solveCarrotSearchPuzzle(
      grid,
      start,
      carrotPatches,
      allPatchIds,
      { searchablePatchIds: allPatchIds },
    );
    if (!allPatchesRoute) continue;
    const allPatchesDistance = allPatchesRoute.actions.length;
    if (allPatchesDistance - supportedDistance < minimumLuckGap) continue;
    if (allPatchesDistance <= supportedDistance + config.moveMargin) continue;

    return {
      exit: null,
      exits: [],
      carrotPatches,
      carrotSolution: {
        carrotCount,
        patchCount,
        supportedFalseChecks: 1,
        optimalDistance,
        supportedDistance,
        allPatchesDistance,
      },
      path: optimal.path,
      alternatePath: supportedRoute.path,
      trickPath: allPatchesRoute.path,
      objectiveSolution: optimal,
      carrotAlternateSolution: supportedRoute,
      carrotAllPatchesSolution: allPatchesRoute,
      trickPathProfile: null,
      difficultyProfile: null,
      moveLimit: supportedDistance + config.moveMargin,
    };
  }

  return null;
}

function objectivePlacementCandidates(start, variantIndex, rng) {
  return shuffle(
    Array.from({ length: ROWS * COLS }, (_, index) => ({
      row: Math.floor(index / COLS),
      col: index % COLS,
    })).filter(
      (candidate) =>
        isInside(candidate.row, candidate.col) &&
        keyOf(candidate) !== keyOf(start) &&
        (candidate.row * 3 + candidate.col * 2) % VARIANTS_PER_LEVEL !== variantIndex,
    ),
    rng,
  );
}

function pieQuarterBlueprint(row, col) {
  return [
    {
      id: "top-left",
      row,
      col,
      approach: { row: row - 1, col },
      direction: "down",
    },
    {
      id: "top-right",
      row,
      col: col + 1,
      approach: { row, col: col + 2 },
      direction: "left",
    },
    {
      id: "bottom-right",
      row: row + 1,
      col: col + 1,
      approach: { row: row + 2, col: col + 1 },
      direction: "up",
    },
    {
      id: "bottom-left",
      row: row + 1,
      col,
      approach: { row: row + 1, col: col - 1 },
      direction: "right",
    },
  ];
}

function pieFootprintCells(pieData = pie) {
  return pieData?.quarters?.map(({ row, col }) => ({ row, col })) ?? [];
}

function pieFootprintKeys(pieData = pie) {
  return new Set(pieFootprintCells(pieData).map(keyOf));
}

function configurePieGrid(grid, pieData) {
  const footprint = pieFootprintKeys(pieData);
  for (const quarter of pieData.quarters) {
    for (const dir of DIRS) {
      const neighbor = { row: quarter.row + dir.row, col: quarter.col + dir.col };
      if (!isInside(neighbor.row, neighbor.col)) continue;
      setSegmentWall(grid, edgeSegmentBetween(quarter, neighbor), !footprint.has(keyOf(neighbor)));
    }
  }
  for (const quarter of pieData.quarters) {
    setSegmentWall(grid, edgeSegmentBetween(quarter, quarter.approach), false);
  }
  return grid;
}

function solvePiePuzzle(
  grid,
  start,
  pieData,
  maxDistance = 80,
  initialEatenQuarterIds = new Set(),
  blockedKeys = new Set(),
) {
  if (!pieData?.quarters?.length) return null;
  const footprint = pieFootprintKeys(pieData);
  const allEatenMask = (1 << pieData.quarters.length) - 1;
  const initialMask = pieData.quarters.reduce(
    (mask, quarter, index) =>
      mask | (initialEatenQuarterIds.has(quarter.id) ? 1 << index : 0),
    0,
  );
  const queue = [{
    mouse: { ...start },
    eatenMask: initialMask,
    path: [{ ...start }],
    actions: [],
  }];
  const seen = new Set([`${keyOf(start)}|${initialMask}`]);

  while (queue.length) {
    const state = queue.shift();
    if (state.eatenMask === allEatenMask) return state;
    if (state.actions.length >= maxDistance) continue;

    for (const next of neighbors(grid, grid[state.mouse.row][state.mouse.col])) {
      if (footprint.has(keyOf(next)) || blockedKeys.has(keyOf(next))) continue;
      const nextState = {
        mouse: { row: next.row, col: next.col },
        eatenMask: state.eatenMask,
        path: [...state.path, { row: next.row, col: next.col }],
        actions: [...state.actions, { type: "move", direction: next.dir }],
      };
      const stateKey = `${keyOf(nextState.mouse)}|${nextState.eatenMask}`;
      if (seen.has(stateKey)) continue;
      seen.add(stateKey);
      queue.push(nextState);
    }

    pieData.quarters.forEach((quarter, index) => {
      if (
        state.eatenMask & (1 << index) ||
        keyOf(state.mouse) !== keyOf(quarter.approach)
      ) {
        return;
      }
      const dir = DIRS.find((candidate) => candidate.key === quarter.direction);
      if (!dir || grid[state.mouse.row][state.mouse.col].walls[dir.wall]) return;
      const nextMask = state.eatenMask | (1 << index);
      const nextState = {
        mouse: { ...state.mouse },
        eatenMask: nextMask,
        path: [...state.path, { ...state.mouse }],
        actions: [
          ...state.actions,
          { type: "bite", quarterId: quarter.id, direction: quarter.direction },
        ],
      };
      const stateKey = `${keyOf(nextState.mouse)}|${nextMask}`;
      if (seen.has(stateKey)) return;
      seen.add(stateKey);
      queue.push(nextState);
    });
  }

  return null;
}

function choosePiePuzzleAndValidate(grid, config, variantIndex, start, rng) {
  const milkCount = clamp(Math.floor(config.milkCount ?? 0), 0, MAX_MILK_BOTTLES_PER_LEVEL);
  const cheeseCount = clamp(Math.floor(config.cheeseCount ?? 0), 0, MAX_CHEESES_PER_LEVEL);
  if (
    config.pieCount !== 1 ||
    4 + milkCount + cheeseCount > MAX_OBJECTIVES_PER_LEVEL
  ) {
    return null;
  }
  const anchors = shuffle(
    Array.from({ length: ROWS * COLS }, (_, index) => ({
      row: Math.floor(index / COLS),
      col: index % COLS,
    })).filter(({ row, col }) => {
      if (row < 2 || row > ROWS - 4 || col < 2 || col > COLS - 4) return false;
      const quarters = pieQuarterBlueprint(row, col);
      return (
        quarters.every((quarter) =>
          isInside(quarter.row, quarter.col) &&
          isInside(quarter.approach.row, quarter.approach.col),
        ) &&
        quarters.every((quarter) => keyOf(quarter.approach) !== keyOf(start)) &&
        Math.abs(start.row - row) + Math.abs(start.col - col) >= 5 &&
        (row * 3 + col * 2) % VARIANTS_PER_LEVEL !== variantIndex
      );
    }),
    rng,
  );

  for (const anchor of anchors) {
    const pieData = {
      id: "pie-0",
      row: anchor.row,
      col: anchor.col,
      quarters: pieQuarterBlueprint(anchor.row, anchor.col),
    };
    const candidateGrid = configurePieGrid(cloneMazeGrid(grid), pieData);
    const pieSolution = solvePiePuzzle(candidateGrid, start, pieData, config.maxPath + 20);
    if (!pieSolution) continue;

    const footprint = pieFootprintKeys(pieData);
    const approaches = new Set(pieData.quarters.map((quarter) => keyOf(quarter.approach)));
    const objectiveCandidates = objectivePlacementCandidates(start, variantIndex, rng).filter(
      (candidate) => !footprint.has(keyOf(candidate)) && !approaches.has(keyOf(candidate)),
    );
    const placementAttempts = milkCount + cheeseCount ? 120 : 1;

    for (let placementAttempt = 0; placementAttempt < placementAttempts; placementAttempt += 1) {
      const shuffled = shuffle(objectiveCandidates, rng);
      const bottles = shuffled.slice(0, milkCount).map((cell, index) => ({
        id: `milk-${index}`,
        row: cell.row,
        col: cell.col,
      }));
      const occupied = new Set(bottles.map(keyOf));
      const cheeses = shuffled
        .slice(milkCount)
        .filter((cell) => !occupied.has(keyOf(cell)))
        .slice(0, cheeseCount)
        .map((cell) => ({ ...cell }));
      if (bottles.length !== milkCount || cheeses.length !== cheeseCount) continue;

      const remainingSolution = solveMilkPuzzle(
        candidateGrid,
        pieSolution.mouse,
        bottles,
        cheeses,
        config.maxPath + 24,
      );
      if (!remainingSolution) continue;
      const solvedBottles = bottles.map((bottle, index) => {
        const encodedDirection = remainingSolution.bottleStates[index];
        const direction = DIRS[encodedDirection - 1]?.key;
        return { ...bottle, solutionDirection: direction };
      });
      if (solvedBottles.some((bottle) => {
        const spill = bottleSpillForDirection(bottle, bottle.solutionDirection);
        return !spill || footprint.has(keyOf(spill));
      })) {
        continue;
      }

      const nonPieSolution = solveMilkPuzzle(
        candidateGrid,
        start,
        bottles,
        cheeses,
        config.maxPath + 24,
        new Set(),
        new Set(),
        footprint,
      );
      if (!nonPieSolution) continue;
      const fallenBottleKeys = new Set(bottles.map(keyOf));
      const pieAfterOtherObjectives = solvePiePuzzle(
        candidateGrid,
        nonPieSolution.mouse,
        pieData,
        config.maxPath + 20,
        new Set(),
        fallenBottleKeys,
      );
      if (!pieAfterOtherObjectives) continue;

      const path = [...pieSolution.path, ...remainingSolution.path.slice(1)];
      const actions = [...pieSolution.actions, ...remainingSolution.actions];
      const distance = actions.length;
      const orderFlexiblePath = [
        ...nonPieSolution.path,
        ...pieAfterOtherObjectives.path.slice(1),
      ];
      const orderFlexibleActions = [
        ...nonPieSolution.actions,
        ...pieAfterOtherObjectives.actions,
      ];
      const orderFlexibleDistance = orderFlexibleActions.length;
      if (orderFlexibleDistance > config.maxPath + 24) continue;
      const movementPath = path.filter(
        (cell, index, route) => index === 0 || keyOf(cell) !== keyOf(route[index - 1]),
      );
      if (
        distance < config.minPath ||
        distance > config.maxPath ||
        countTurns(movementPath) < config.minTurns ||
        countDeadEnds(candidateGrid) < config.minDeadEnds ||
        pieSolution.actions.filter((action) => action.type === "bite").length !== 4
      ) {
        continue;
      }
      return {
        grid: candidateGrid,
        exit: cheeses[0] ? { ...cheeses[0] } : null,
        exits: cheeses.map((target) => ({ ...target })),
        milkBottles: solvedBottles,
        pie: pieData,
        pieSolution,
        objectiveSolution: remainingSolution,
        path,
        actions,
        alternatePath: orderFlexiblePath,
        orderFlexibleActions,
        trickPath: null,
        difficultyProfile: null,
        moveLimit: Math.max(distance, orderFlexibleDistance) + config.moveMargin,
      };
    }
  }
  return null;
}

function chooseMilkPuzzleAndValidate(grid, config, variantIndex, start, rng) {
  const milkCount = clamp(
    Math.floor(config.milkCount ?? 1),
    1,
    MAX_MILK_BOTTLES_PER_LEVEL,
  );
  const cheeseCount = clamp(Math.floor(config.cheeseCount ?? 0), 0, MAX_CHEESES_PER_LEVEL);
  if (milkCount + cheeseCount > MAX_OBJECTIVES_PER_LEVEL) return null;
  const candidates = objectivePlacementCandidates(start, variantIndex, rng);

  for (let placementAttempt = 0; placementAttempt < 180; placementAttempt += 1) {
    const shuffled = shuffle(candidates, rng);
    const bottles = shuffled.slice(0, milkCount).map((cell, index) => ({
      id: `milk-${index}`,
      row: cell.row,
      col: cell.col,
    }));
    const occupied = new Set(bottles.map(keyOf));
    const cheeses = shuffled
      .slice(milkCount)
      .filter((cell) => !occupied.has(keyOf(cell)))
      .slice(0, cheeseCount)
      .map((cell) => ({ ...cell }));
    if (cheeses.length !== cheeseCount) continue;
    const solution = solveMilkPuzzle(grid, start, bottles, cheeses, config.maxPath + 12);
    if (!solution) continue;
    const distance = solution.actions.length;
    if (distance < config.minPath || distance > config.maxPath) continue;
    const knockCount = solution.actions.filter((action) => action.type === "knock").length;
    if (knockCount !== milkCount || countDeadEnds(grid) < config.minDeadEnds) continue;
    const solvedBottles = bottles.map((bottle, index) => {
      const encodedDirection = solution.bottleStates[index];
      const direction = DIRS[encodedDirection - 1]?.key;
      return { ...bottle, solutionDirection: direction };
    });
    const spilledMilkTargets = solvedBottles.map((bottle) => {
      const direction = DIRS.find((candidate) => candidate.key === bottle.solutionDirection);
      return {
        row: bottle.row + direction.row,
        col: bottle.col + direction.col,
      };
    });
    const objectiveSpread = carObjectiveSpread(
      grid,
      start,
      [...cheeses, ...spilledMilkTargets],
    );
    if (
      !objectiveSpread ||
      objectiveSpread.minStartDistance < (config.minObjectiveStartDistance ?? 0) ||
      objectiveSpread.minPairSeparation < (config.minObjectiveSeparation ?? 0) ||
      objectiveSpread.minPairDistance < (config.minObjectivePathDistance ?? 0) ||
      objectiveSpread.rowSpan < (config.minObjectiveRowSpan ?? 0) ||
      objectiveSpread.colSpan < (config.minObjectiveColSpan ?? 0) ||
      objectiveSpread.detourBeyondFarthest < (config.minObjectiveDetour ?? 0) ||
      objectiveSpread.passThroughObjectives >
        (config.maxPassThroughObjectives ?? Number.POSITIVE_INFINITY)
    ) {
      continue;
    }
    const moveLimit = distance + (config.moveMargin ?? Math.max(6, Math.ceil(distance * 0.3)));
    return {
      exit: cheeses[0] ? { ...cheeses[0] } : null,
      exits: cheeses.map((target) => ({ ...target })),
      milkBottles: solvedBottles,
      path: solution.path,
      actions: solution.actions,
      objectiveSolution: solution,
      alternatePath: solution.path,
      trickPath: null,
      difficultyProfile: null,
      objectiveSpread,
      moveLimit,
    };
  }
  return null;
}

function carObjectiveSpread(grid, start, targets) {
  if (!targets.length) return null;
  const directDistances = new Map();
  const pairDistances = new Map();
  let minPairDistance = Number.POSITIVE_INFINITY;
  let minPairSeparation = Number.POSITIVE_INFINITY;
  let passThroughObjectives = 0;

  for (const target of targets) {
    const path = findShortestPathFrom(grid, start, target);
    if (!path.length) return null;
    directDistances.set(keyOf(target), path.length - 1);
  }

  for (let firstIndex = 0; firstIndex < targets.length; firstIndex += 1) {
    const first = targets[firstIndex];
    for (let secondIndex = firstIndex + 1; secondIndex < targets.length; secondIndex += 1) {
      const second = targets[secondIndex];
      const path = findShortestPathFrom(grid, first, second);
      if (!path.length) return null;
      const distance = path.length - 1;
      pairDistances.set(`${keyOf(first)}>${keyOf(second)}`, distance);
      pairDistances.set(`${keyOf(second)}>${keyOf(first)}`, distance);
      minPairDistance = Math.min(minPairDistance, distance);
      minPairSeparation = Math.min(
        minPairSeparation,
        Math.abs(first.row - second.row) + Math.abs(first.col - second.col),
      );
    }
  }

  for (const target of targets) {
    const targetDistance = directDistances.get(keyOf(target));
    const liesOnWayToAnotherTarget = targets.some((other) => {
      if (keyOf(other) === keyOf(target)) return false;
      const betweenDistance = pairDistances.get(`${keyOf(target)}>${keyOf(other)}`);
      return targetDistance + betweenDistance === directDistances.get(keyOf(other));
    });
    if (liesOnWayToAnotherTarget) passThroughObjectives += 1;
  }

  let optimalDistance = Number.POSITIVE_INFINITY;
  function measureOrders(current, remaining, distance) {
    if (!remaining.length) {
      optimalDistance = Math.min(optimalDistance, distance);
      return;
    }
    for (let index = 0; index < remaining.length; index += 1) {
      const target = remaining[index];
      const segmentDistance = current
        ? pairDistances.get(`${keyOf(current)}>${keyOf(target)}`)
        : directDistances.get(keyOf(target));
      measureOrders(
        target,
        remaining.filter((_, targetIndex) => targetIndex !== index),
        distance + segmentDistance,
      );
    }
  }
  measureOrders(null, targets, 0);
  const furthestDirectDistance = Math.max(...directDistances.values());
  const rows = targets.map((target) => target.row);
  const cols = targets.map((target) => target.col);

  return {
    minStartDistance: Math.min(...directDistances.values()),
    minPairDistance,
    minPairSeparation,
    rowSpan: Math.max(...rows) - Math.min(...rows),
    colSpan: Math.max(...cols) - Math.min(...cols),
    detourBeyondFarthest: optimalDistance - furthestDirectDistance,
    passThroughObjectives,
  };
}

function chooseCarPuzzleAndValidate(grid, config, variantIndex, start, rng) {
  const cheeseCount = clamp(Math.floor(config.cheeseCount ?? 1), 1, MAX_CHEESES_PER_LEVEL);
  const candidates = objectivePlacementCandidates(start, variantIndex, rng);
  for (let placementAttempt = 0; placementAttempt < 220; placementAttempt += 1) {
    const shuffled = shuffle(candidates, rng);
    const carStart = shuffled.find((cell) => {
      if (
        cell.row === 0 ||
        cell.row === ROWS - 1 ||
        cell.col === 0 ||
        cell.col === COLS - 1
      ) {
        return false;
      }
      const path = findShortestPathFrom(grid, cell, start);
      return path.length - 1 >= 7;
    });
    if (!carStart) continue;
    const cheeses = shuffled
      .filter((cell) => keyOf(cell) !== keyOf(carStart))
      .slice(0, cheeseCount)
      .map((cell) => ({ ...cell }));
    if (cheeses.length !== cheeseCount) continue;
    const spread = carObjectiveSpread(grid, start, cheeses);
    if (
      !spread ||
      spread.minPairSeparation < (config.minCheeseSeparation ?? 0) ||
      spread.minPairDistance < (config.minCheeseDistance ?? 0) ||
      spread.rowSpan < (config.minObjectiveRowSpan ?? 0) ||
      spread.colSpan < (config.minObjectiveColSpan ?? 0) ||
      spread.detourBeyondFarthest < (config.minObjectiveDetour ?? 0) ||
      spread.passThroughObjectives >
        (config.maxPassThroughObjectives ?? Number.POSITIVE_INFINITY)
    ) {
      continue;
    }
    const solution = solveCarPuzzle(grid, start, carStart, cheeses, config.maxPath + 14);
    if (!solution) continue;
    const distance = solution.actions.length;
    if (distance < config.minPath || distance > config.maxPath) continue;
    if (countTurns(solution.path) < config.minTurns || countDeadEnds(grid) < config.minDeadEnds) {
      continue;
    }
    return {
      exit: { ...cheeses[0] },
      exits: cheeses,
      car: { id: "catcher", row: carStart.row, col: carStart.col },
      carSolution: solution,
      path: solution.path,
      alternatePath: solution.path,
      trickPath: null,
      difficultyProfile: null,
      objectiveSpread: spread,
      moveLimit: distance + (config.moveMargin ?? 7),
    };
  }
  return null;
}

function findPathAvoidingCells(grid, start, target, blockedCells) {
  const queue = [{ cell: { ...start }, path: [{ ...start }] }];
  const seen = new Set([keyOf(start)]);
  while (queue.length) {
    const current = queue.shift();
    if (keyOf(current.cell) === keyOf(target)) return current.path;
    for (const next of neighbors(grid, grid[current.cell.row][current.cell.col])) {
      const nextKey = keyOf(next);
      if (blockedCells.has(nextKey) || seen.has(nextKey)) continue;
      seen.add(nextKey);
      queue.push({
        cell: { row: next.row, col: next.col },
        path: [...current.path, { row: next.row, col: next.col }],
      });
    }
  }
  return [];
}

function rockResult(config, cheeses, rocks, solution, hidden = false, alternatePath = null) {
  const primaryCheese = cheeses[0];
  const distance = solution.path.length - 1;
  return {
    exit: { ...primaryCheese },
    exits: cheeses.map((cheese) => ({ ...cheese })),
    rocks: rocks.map((rock, index) => ({ id: index, row: rock.row, col: rock.col })),
    hiddenCheeseKeys: hidden ? [keyOf(primaryCheese)] : [],
    path: solution.path,
    alternatePath,
    difficultyProfile: null,
    rockSolution: solution,
    moveLimit: distance + config.moveMargin,
  };
}

function solveRockObjectiveSet(grid, config, start, primaryCheese, rocks, candidates, rng) {
  const cheeseCount = clamp(
    Math.floor(config.cheeseCount ?? 1),
    1,
    MAX_CHEESES_PER_LEVEL,
  );
  const blockedKeys = new Set([
    keyOf(start),
    keyOf(primaryCheese),
    ...rocks.map(keyOf),
  ]);
  const extraCandidates = candidates.filter((candidate) => !blockedKeys.has(keyOf(candidate)));
  const placementAttempts = cheeseCount === 1 ? 1 : Math.min(90, extraCandidates.length * 2);

  for (let placementAttempt = 0; placementAttempt < placementAttempts; placementAttempt += 1) {
    const extras = cheeseCount === 1
      ? []
      : shuffle(extraCandidates, rng).slice(0, cheeseCount - 1);
    if (extras.length !== cheeseCount - 1) continue;
    const cheeses = [{ ...primaryCheese }, ...extras.map((cheese) => ({ ...cheese }))];
    const solution = solveRockPuzzle(grid, start, rocks, cheeses, config.maxPath);
    if (!solution || solution.pushes < 1) continue;
    const distance = solution.path.length - 1;
    if (
      distance < config.minPath ||
      distance > config.maxPath ||
      countTurns(solution.path) < config.minTurns
    ) {
      continue;
    }
    return { cheeses, solution };
  }

  return null;
}

function chooseRockPuzzleAndValidate(grid, config, variantIndex, start, rng) {
  const rockCount = clamp(Math.floor(config.rockCount ?? 1), 1, MAX_ROCKS_PER_LEVEL);
  if (countDeadEnds(grid) < config.minDeadEnds) return null;
  const candidates = shuffle(
    Array.from({ length: ROWS * COLS }, (_, index) => ({
      row: Math.floor(index / COLS),
      col: index % COLS,
    })).filter(
      (candidate) =>
        isInside(candidate.row, candidate.col) &&
        keyOf(candidate) !== keyOf(start) &&
        (candidate.row * 3 + candidate.col * 2) % VARIANTS_PER_LEVEL === variantIndex,
    ),
    rng,
  );

  if (config.rockMode === "blocker") {
    for (const cheese of candidates) {
      const directPath = findShortestPathFrom(grid, start, cheese);
      if (directPath.length < 9) continue;
      for (const rockCell of shuffle(directPath.slice(3, -3), rng)) {
        const mandatoryRock = { row: rockCell.row, col: rockCell.col };
        const initialSolution = solveRockPuzzle(
          grid,
          start,
          [mandatoryRock],
          [cheese],
          config.maxPath,
        );
        if (!initialSolution || initialSolution.pushes < 1) continue;
        const solutionCells = new Set(initialSolution.path.map(keyOf));
        const decoyCandidates = shuffle(
          candidates.filter((candidate) => {
            const candidateKey = keyOf(candidate);
            return (
              candidateKey !== keyOf(cheese) &&
              candidateKey !== keyOf(start) &&
              candidateKey !== keyOf(mandatoryRock) &&
              !solutionCells.has(candidateKey) &&
              neighbors(grid, grid[candidate.row][candidate.col]).length >= 2
            );
          }),
          rng,
        );
        const rocks = [mandatoryRock, ...decoyCandidates.slice(0, rockCount - 1)];
        if (rocks.length !== rockCount) continue;
        const objectiveSet = solveRockObjectiveSet(
          grid,
          config,
          start,
          cheese,
          rocks,
          candidates,
          rng,
        );
        if (!objectiveSet) continue;
        const { cheeses, solution } = objectiveSet;
        const detour = findPathAvoidingCells(grid, start, cheese, new Set([keyOf(rockCell)]));
        if (
          (detour.length && detour.length - solution.path.length < config.minDetourPenalty)
        ) {
          continue;
        }
        return rockResult(
          config,
          cheeses,
          rocks,
          solution,
          false,
          detour.length ? detour : null,
        );
      }
    }
    return null;
  }

  for (const cheese of candidates) {
    const targetRock = { row: cheese.row, col: cheese.col };
    let rocks = [targetRock];
    let initialSolution = solveRockPuzzle(grid, start, rocks, [cheese], config.maxPath);
    if (!initialSolution || initialSolution.pushes < 1) continue;

    if (config.rockMode === "search") {
      const solutionCells = new Set(initialSolution.path.map(keyOf));
      const decoyCandidates = shuffle(
        Array.from({ length: ROWS * COLS }, (_, index) => ({
          row: Math.floor(index / COLS),
          col: index % COLS,
        })).filter((candidate) => {
          if (!isInside(candidate.row, candidate.col)) return false;
          if (keyOf(candidate) === keyOf(start) || solutionCells.has(keyOf(candidate))) return false;
          return neighbors(grid, grid[candidate.row][candidate.col]).length >= 2;
        }),
        rng,
      );
      rocks = [targetRock, ...decoyCandidates.slice(0, rockCount - 1)];
      if (rocks.length !== rockCount) continue;
      initialSolution = solveRockPuzzle(grid, start, rocks, [cheese], config.maxPath);
      if (!initialSolution || initialSolution.pushes < 1) continue;
    }

    const objectiveSet = solveRockObjectiveSet(
      grid,
      config,
      start,
      cheese,
      rocks,
      candidates,
      rng,
    );
    if (!objectiveSet) continue;
    return rockResult(config, objectiveSet.cheeses, rocks, objectiveSet.solution, true);
  }

  return null;
}

function chooseHingedWallPuzzleAndValidate(grid, config, variantIndex, start, rng) {
  const hingedWallCount = clamp(
    Math.floor(config.hingedWallCount ?? 1),
    1,
    MAX_HINGED_WALLS_PER_LEVEL,
  );
  if (countDeadEnds(grid) < config.minDeadEnds) return null;
  const candidates = shuffle(
    Array.from({ length: ROWS * COLS }, (_, index) => ({
      row: Math.floor(index / COLS),
      col: index % COLS,
    })).filter(
      (candidate) =>
        isInside(candidate.row, candidate.col) &&
        keyOf(candidate) !== keyOf(start) &&
        (candidate.row * 3 + candidate.col * 2) % VARIANTS_PER_LEVEL === variantIndex,
    ),
    rng,
  );

  for (const cheese of candidates) {
    const initialPath = findShortestPathFrom(grid, start, cheese);
    if (initialPath.length < 8) continue;

    const transformedGrid = cloneMazeGrid(grid);
    const hinged = [];
    const usedSegments = new Set();
    const usedTriggerCells = new Set();
    const combinedPath = [{ ...start }];
    let currentStart = { ...start };
    let totalDetourPenalty = 0;
    let failed = false;

    for (let wallIndex = 0; wallIndex < hingedWallCount; wallIndex += 1) {
      const route = findShortestPathFrom(transformedGrid, currentStart, cheese);
      if (route.length < 6) {
        failed = true;
        break;
      }

      const edgeIndices = shuffle(
        Array.from({ length: Math.max(0, route.length - 4) }, (_, index) => index + 2),
        rng,
      );
      let selected = null;

      for (const edgeIndex of edgeIndices) {
        const triggerFrom = route[edgeIndex];
        const triggerTo = route[edgeIndex + 1];
        const destination = edgeSegmentBetween(triggerFrom, triggerTo);
        if (
          usedSegments.has(segmentKey(destination)) ||
          usedTriggerCells.has(keyOf(triggerFrom))
        ) {
          continue;
        }

        const sources = shuffle(perpendicularHingeSources(destination), rng).filter(
          ({ source }) =>
            segmentHasWall(transformedGrid, source) &&
            !usedSegments.has(segmentKey(source)),
        );

        for (const { source, hinge } of sources) {
          if (!hingedSweepClearsCell(source, destination, hinge, triggerFrom)) continue;
          const nextGrid = cloneMazeGrid(transformedGrid);
          setSegmentWall(nextGrid, source, false);
          setSegmentWall(nextGrid, destination, true);
          const detour = findShortestPathFrom(nextGrid, triggerFrom, cheese);
          if (!detour.length) continue;
          const originalRemainingDistance = route.length - 1 - edgeIndex;
          const detourPenalty = detour.length - 1 - originalRemainingDistance;
          if (detourPenalty < config.minHingedDetour) continue;
          selected = {
            source,
            destination,
            hinge,
            triggerFrom: { ...triggerFrom },
            routePrefix: route.slice(0, edgeIndex + 1),
            nextGrid,
            detourPenalty,
          };
          break;
        }
        if (selected) break;
      }

      if (!selected) {
        failed = true;
        break;
      }

      combinedPath.push(...selected.routePrefix.slice(1).map((cell) => ({ ...cell })));
      hinged.push({
        id: wallIndex,
        source: { ...selected.source },
        destination: { ...selected.destination },
        hinge: { ...selected.hinge },
        triggerFrom: { ...selected.triggerFrom },
      });
      usedSegments.add(segmentKey(selected.source));
      usedSegments.add(segmentKey(selected.destination));
      usedTriggerCells.add(keyOf(selected.triggerFrom));
      totalDetourPenalty += selected.detourPenalty;
      currentStart = { ...selected.triggerFrom };
      for (let row = 0; row < ROWS; row += 1) {
        for (let col = 0; col < COLS; col += 1) {
          transformedGrid[row][col].walls = { ...selected.nextGrid[row][col].walls };
        }
      }
    }

    if (failed || hinged.length !== hingedWallCount) continue;
    const finalPath = findShortestPathFrom(transformedGrid, currentStart, cheese);
    if (!finalPath.length) continue;
    combinedPath.push(...finalPath.slice(1).map((cell) => ({ ...cell })));
    const cheeseCount = clamp(
      Math.floor(config.cheeseCount ?? 1),
      1,
      MAX_CHEESES_PER_LEVEL,
    );
    const extraCandidates = candidates.filter((candidate) => keyOf(candidate) !== keyOf(cheese));
    const placementAttempts = cheeseCount === 1 ? 1 : Math.min(90, extraCandidates.length * 2);
    for (let placementAttempt = 0; placementAttempt < placementAttempts; placementAttempt += 1) {
      const extras = cheeseCount === 1
        ? []
        : shuffle(extraCandidates, rng).slice(0, cheeseCount - 1);
      if (extras.length !== cheeseCount - 1) continue;
      const cheeses = [{ ...cheese }, ...extras.map((target) => ({ ...target }))];
      const objectiveSpread = carObjectiveSpread(grid, start, cheeses);
      if (
        !objectiveSpread ||
        objectiveSpread.minStartDistance < (config.minObjectiveStartDistance ?? 0) ||
        objectiveSpread.minPairSeparation < (config.minObjectiveSeparation ?? 0) ||
        objectiveSpread.minPairDistance < (config.minObjectivePathDistance ?? 0) ||
        objectiveSpread.rowSpan < (config.minObjectiveRowSpan ?? 0) ||
        objectiveSpread.colSpan < (config.minObjectiveColSpan ?? 0) ||
        objectiveSpread.detourBeyondFarthest < (config.minObjectiveDetour ?? 0) ||
        objectiveSpread.passThroughObjectives >
          (config.maxPassThroughObjectives ?? Number.POSITIVE_INFINITY)
      ) {
        continue;
      }
      const solution = solveHingedPuzzle(grid, start, hinged, cheeses, config.maxPath + 8);
      if (!solution || solution.triggers < hingedWallCount) continue;
      const distance = solution.path.length - 1;
      if (
        distance < config.minPath ||
        distance > config.maxPath ||
        countTurns(solution.path) < config.minTurns
      ) {
        continue;
      }
      return {
        exit: { ...cheeses[0] },
        exits: cheeses,
        hingedWalls: hinged,
        path: solution.path,
        alternatePath: solution.path,
        difficultyProfile: null,
        objectiveSpread,
        hingedSolution: {
          path: solution.path,
          wallRoute: combinedPath,
          triggers: solution.triggers,
          detourPenalty: totalDetourPenalty,
        },
        moveLimit: distance + config.moveMargin,
      };
    }
  }

  return null;
}

function cloneLevelVariant(variant) {
  if (typeof globalThis.structuredClone === "function") {
    return globalThis.structuredClone(variant);
  }
  return JSON.parse(JSON.stringify(variant));
}

function failureCountForCurrentLevel() {
  return Math.max(0, levelFailureCounts[level - 1] ?? 0);
}

function moveRewardForCurrentFailure() {
  const rewardIndex = clamp(failureCountForCurrentLevel() - 1, 0, FAILURE_MOVE_REWARDS.length - 1);
  return FAILURE_MOVE_REWARDS[rewardIndex];
}

function rewindMarginForCurrentFailure() {
  return clamp(failureCountForCurrentLevel() - 1, 0, 2);
}

function captureTurnSnapshot() {
  const cloudVisual = currentCloudVisualState();
  return cloneLevelVariant({
    maze,
    exit,
    cheeseTargets,
    collectedCheeseKeys: [...collectedCheeseKeys],
    carrotPatches,
    inspectedCarrotPatchIds: [...inspectedCarrotPatchIds],
    collectedCarrotIds: [...collectedCarrotIds],
    milkBottles,
    collectedMilkIds: [...collectedMilkIds],
    pie,
    eatenPieQuarterIds: [...eatenPieQuarterIds],
    car,
    carFacingDirection,
    cockroachMovesSinceAction,
    cockroachNextTrigger,
    cockroachActionsUsed,
    cockroachDefeated,
    catPawMovesSinceStrike,
    catPawNextTrigger,
    catPawThreat,
    catPawStrikePending,
    mouseCapturedByCat,
    crowMovesSinceStrike,
    crowNextTrigger,
    crowThreat,
    crowStrikePending,
    mouseCapturedByCrow,
    helperRequestedForRun,
    helperMouse,
    helperFacingDirection,
    helperCargo,
    helperResting,
    helperCaptured,
    helperMode,
    helperTask,
    helperPlayerTrail,
    helperPlannerTurn,
    helperRecoveryTurns,
    helperDistractionCooldowns,
    helperDecoyHistory,
    helperLastDecision,
    helperTestedRockIds: [...helperTestedRockIds],
    helperRockSafetyCache: [...helperRockSafetyCache.entries()],
    helperTunnelCooldownTurns,
    cloud: cloud
      ? {
          ...cloud,
          row: cloudVisual?.row ?? cloud.row,
          col: cloudVisual?.col ?? cloud.col,
        }
      : null,
    cloudIdleStepsRemaining,
    waterMoveCount,
    floodedWaterKeys: [...floodedWaterKeys],
    waterOrigin,
    rockPositions,
    hiddenCheeseKeys: [...hiddenCheeseKeys],
    hingedWalls,
    tunnels,
    rotatingCircuits,
    fragileTiles,
    crackedFragileTileKeys: [...crackedFragileTileKeys],
    collapsedFragileTileKeys: [...collapsedFragileTileKeys],
    spiderWebs,
    brokenSpiderWebIds: [...brokenSpiderWebIds],
    mouseTrappedWebId,
    mouseSpiderWebTrapSettled,
    mouse,
    mouseFacingDirection,
    movesLeft,
    powerInventory,
    crystalForecastReservation,
  });
}

function resetTurnHistory() {
  turnHistory = [captureTurnSnapshot()];
}

function recordTurnSnapshot() {
  turnHistory.push(captureTurnSnapshot());
  if (turnHistory.length > REWIND_HISTORY_LIMIT) turnHistory.shift();
}

function beginTrackedTurn(target) {
  recordTurnSnapshot();
  commitCrystalForecastAction(target);
}

function drawRewindStatic(timestamp) {
  if (rewindOverlayEl.hidden) {
    rewindStaticAnimationFrame = null;
    return;
  }
  if (timestamp - rewindStaticLastFrame >= REWIND_STATIC_FRAME_MS) {
    const bounds = rewindOverlayEl.getBoundingClientRect();
    const width = Math.max(96, Math.min(240, Math.ceil(bounds.width / 3)));
    const height = Math.max(160, Math.min(420, Math.ceil(bounds.height / 3)));
    if (rewindStaticEl.width !== width || rewindStaticEl.height !== height) {
      rewindStaticEl.width = width;
      rewindStaticEl.height = height;
    }
    const context = rewindStaticEl.getContext("2d", { alpha: true });
    const pixels = context.createImageData(width, height);
    for (let index = 0; index < pixels.data.length; index += 4) {
      const noise = Math.random();
      const light = noise > 0.82 ? 245 : noise > 0.46 ? 148 : 42;
      pixels.data[index] = Math.round(light * 0.72);
      pixels.data[index + 1] = Math.min(255, light + 32);
      pixels.data[index + 2] = Math.min(255, light + 25);
      pixels.data[index + 3] = 26 + Math.floor(Math.random() * 82);
    }
    context.putImageData(pixels, 0, 0);
    context.fillStyle = `rgba(218, 255, 250, ${0.08 + Math.random() * 0.12})`;
    for (let band = 0; band < 4; band += 1) {
      context.fillRect(0, Math.random() * height, width, 1 + Math.random() * 3);
    }
    rewindStaticLastFrame = timestamp;
  }
  rewindStaticAnimationFrame = requestAnimationFrame(drawRewindStatic);
}

function startRewindOverlay(totalSteps) {
  if (rewindStaticAnimationFrame !== null) {
    cancelAnimationFrame(rewindStaticAnimationFrame);
  }
  rewindOverlayEl.hidden = false;
  rewindOverlayEl.dataset.phase = "intro";
  rewindStepLabelEl.textContent = totalSteps > 1 ? `REWIND 0/${totalSteps}` : "REWIND";
  rewindStaticLastFrame = 0;
  rewindStaticAnimationFrame = requestAnimationFrame(drawRewindStatic);
}

function updateRewindOverlay(step, totalSteps) {
  rewindOverlayEl.dataset.phase = "playing";
  rewindStepLabelEl.textContent = totalSteps > 1 ? `REWIND ${step}/${totalSteps}` : "REWIND";
}

function settleRewindOverlay() {
  rewindOverlayEl.dataset.phase = "settle";
}

function stopRewindOverlay() {
  if (rewindStaticAnimationFrame !== null) {
    cancelAnimationFrame(rewindStaticAnimationFrame);
  }
  rewindStaticAnimationFrame = null;
  rewindStaticLastFrame = 0;
  rewindOverlayEl.hidden = true;
  delete rewindOverlayEl.dataset.phase;
}

function waitForRewindDelay(duration) {
  return new Promise((resolve) => setTimeout(resolve, duration));
}

function rewindDirectionBetween(from, to, fallback = "left") {
  if (!from || !to) return fallback;
  if (to.col > from.col) return "right";
  if (to.col < from.col) return "left";
  if (to.row < from.row) return "up";
  if (to.row > from.row) return "down";
  return fallback;
}

function interpolateRewindCell(from, to, progress) {
  if (!from || !to) return null;
  const eased = easeMouseMotion(progress);
  return {
    row: from.row + (to.row - from.row) * eased,
    col: from.col + (to.col - from.col) * eased,
  };
}

function syntheticRewindFailureAnimation(kind) {
  if (kind === "cat") {
    const options = catPawThreatOptions();
    const threat = (catPawThreatContains(catPawThreat, mouse) ? catPawThreat : null) ??
      options.find((option) => catPawThreatContains(option, mouse)) ??
      chooseCatPawThreat() ??
      options[0];
    if (!threat) return null;
    return {
      kind,
      animation: {
        threat: cloneLevelVariant(threat),
        caught: true,
        caughtHelper: false,
        helperCaptureCell: null,
        helperCaptureCommitted: false,
        caughtCar: false,
        caughtCockroach: false,
        queuedDirection: null,
        progress: 1,
        startedAt: null,
      },
    };
  }
  if (kind === "crow") {
    const options = crowThreatOptions();
    const threat = (crowThreatContains(crowThreat, mouse) ? crowThreat : null) ??
      options.find((option) => crowThreatContains(option, mouse)) ??
      chooseCrowThreat() ??
      options[0];
    if (!threat) return null;
    return {
      kind,
      animation: {
        threat: cloneLevelVariant(threat),
        flightDiagonal: cloneLevelVariant(CROW_FLIGHT_DIAGONALS[0]),
        caught: true,
        caughtHelper: false,
        helperCaptureCell: null,
        caughtCar: false,
        caughtCockroach: false,
        caughtCell: { ...mouse },
        targetedCell: { ...mouse },
        blockedByCloud: false,
        queuedDirection: null,
        progress: 1,
        startedAt: null,
      },
    };
  }
  if (kind === "catcher" && car) {
    return {
      kind,
      animation: {
        progress: 1,
        startedAt: null,
        direction: carDirectionBetween(car, mouse, carFacingDirection),
        car: { ...car },
        target: { ...mouse },
      },
    };
  }
  if (kind === "hole") {
    return {
      kind,
      animation: {
        cell: { ...mouse },
        progress: 1,
        startedAt: null,
      },
    };
  }
  return null;
}

function applyRewindFailureAnimationFrame(replay, progress) {
  const animation = cloneLevelVariant({
    ...replay.animation,
    progress,
    startedAt: null,
  });
  if (replay.kind === "cat") {
    catPawAnimation = animation;
    catPawThreat = cloneLevelVariant(animation.threat);
    mouseCapturedByCat = false;
  } else if (replay.kind === "crow") {
    crowAnimation = animation;
    crowThreat = cloneLevelVariant(animation.threat);
    mouseCapturedByCrow = false;
  } else if (replay.kind === "catcher") {
    carCaptureAnimation = animation;
  } else if (replay.kind === "hole") {
    fragileFallAnimation = animation;
    syncFragileDebugDataset();
  }
}

function clearRewindFailureAnimationFrame(kind) {
  if (kind === "cat") {
    catPawAnimation = null;
    catPawAnimationFrame = null;
  } else if (kind === "crow") {
    crowAnimation = null;
    crowAnimationFrame = null;
  } else if (kind === "catcher") {
    carCaptureAnimation = null;
    carCaptureAnimationFrame = null;
  } else if (kind === "hole") {
    fragileFallAnimation = null;
    fragileFallAnimationFrame = null;
    syncFragileDebugDataset();
  }
}

function animateRewindFailureCause(replay, token) {
  if (!replay) return Promise.resolve(true);
  if (!canAnimateMouseMotion()) {
    clearRewindFailureAnimationFrame(replay.kind);
    return Promise.resolve(true);
  }
  return new Promise((resolve) => {
    let startedAt = null;
    const animate = (timestamp) => {
      if (token !== rewindAnimationToken) {
        clearRewindFailureAnimationFrame(replay.kind);
        resolve(false);
        return;
      }
      if (startedAt === null) startedAt = timestamp;
      const elapsed = clamp(
        (timestamp - startedAt) / REWIND_FAILURE_CAUSE_DURATION_MS,
        0,
        1,
      );
      applyRewindFailureAnimationFrame(replay, 1 - smoothStep(elapsed));
      drawMaze();
      if (elapsed < 1) {
        requestAnimationFrame(animate);
        return;
      }
      clearRewindFailureAnimationFrame(replay.kind);
      drawMaze();
      resolve(true);
    };
    requestAnimationFrame(animate);
  });
}

function animateRewindTransition(fromSnapshot, toSnapshot, token, step, totalSteps) {
  applyTurnSnapshot(toSnapshot);
  rewindVisualTransition = {
    fromMouse: fromSnapshot.mouse,
    toMouse: toSnapshot.mouse,
    fromCar: fromSnapshot.car,
    toCar: toSnapshot.car,
    fromHelper: fromSnapshot.helperMouse,
    toHelper: toSnapshot.helperMouse,
    progress: 0,
  };
  mouseFacingDirection = rewindDirectionBetween(
    rewindVisualTransition.fromMouse,
    rewindVisualTransition.toMouse,
    toSnapshot.mouseFacingDirection,
  );
  if (rewindVisualTransition.fromHelper && rewindVisualTransition.toHelper) {
    helperFacingDirection = rewindDirectionBetween(
      rewindVisualTransition.fromHelper,
      rewindVisualTransition.toHelper,
      toSnapshot.helperFacingDirection,
    );
  }
  if (rewindVisualTransition.fromCar && rewindVisualTransition.toCar) {
    carFacingDirection = rewindDirectionBetween(
      rewindVisualTransition.fromCar,
      rewindVisualTransition.toCar,
      toSnapshot.carFacingDirection,
    );
  }
  updateRewindOverlay(step, totalSteps);
  gameOver = true;
  render();

  if (!canAnimateMouseMotion()) {
    rewindVisualTransition = null;
    applyTurnSnapshot(toSnapshot);
    render();
    return Promise.resolve(true);
  }

  return new Promise((resolve) => {
    let startedAt = null;
    const animate = (timestamp) => {
      if (token !== rewindAnimationToken) {
        rewindVisualTransition = null;
        resolve(false);
        return;
      }
      if (startedAt === null) startedAt = timestamp;
      rewindVisualTransition.progress = clamp(
        (timestamp - startedAt) / REWIND_STEP_DURATION_MS,
        0,
        1,
      );
      drawMaze();
      if (rewindVisualTransition.progress < 1) {
        requestAnimationFrame(animate);
        return;
      }
      rewindVisualTransition = null;
      applyTurnSnapshot(toSnapshot);
      gameOver = true;
      render();
      resolve(true);
    };
    requestAnimationFrame(animate);
  });
}

function clearRewindPlayback() {
  rewindAnimationToken += 1;
  rewindAnimationActive = false;
  rewindVisualTransition = null;
  rewindFailureAnimation = null;
  stopRewindOverlay();
  mazeEl.classList.remove("rewinding");
  mazeEl.setAttribute("aria-busy", "false");
}

