  helperPlannerTurn = restored.helperPlannerTurn;
  helperRecoveryTurns = restored.helperRecoveryTurns;
  helperDistractionCooldowns = restored.helperDistractionCooldowns;
  helperDecoyHistory = restored.helperDecoyHistory;
  helperIntentCueUntil = 0;
  helperLastDecision = restored.helperLastDecision;
  helperTestedRockIds = new Set(restored.helperTestedRockIds);
  helperRockSafetyCache = new Map(restored.helperRockSafetyCache);
  helperTunnelCooldownTurns = restored.helperTunnelCooldownTurns;
  cloud = restored.cloud;
  cloudIdleStepsRemaining = restored.cloudIdleStepsRemaining;
  waterMoveCount = restored.waterMoveCount;
