function schedulePowerIntroTutorial(callback, delay) {
  const timer = setTimeout(() => {
    powerIntroTutorialTimers = powerIntroTutorialTimers.filter(
      (candidate) => candidate !== timer,
    );
    callback();
  }, delay);
  powerIntroTutorialTimers.push(timer);
}

