const testLevelFromUrl = (() => {
  try {
    if (!globalThis.location?.search || typeof URLSearchParams !== "function") return null;
    const value = Number(new URLSearchParams(globalThis.location.search).get("testLevel"));
    return Number.isInteger(value) && value >= 1 && value <= LEVEL_CONFIGS.length
      ? value
      : null;
  } catch {
    return null;
  }
})();
const testVariantFromUrl = (() => {
  try {
    if (!globalThis.location?.search || typeof URLSearchParams !== "function") return null;
    const value = Number(new URLSearchParams(globalThis.location.search).get("testVariant"));
    return Number.isInteger(value) && value >= 1 && value <= VARIANTS_PER_LEVEL
      ? value - 1
      : null;
  } catch {
    return null;
  }
})();
const testUnlockFromUrl = worldTestUnlockQuery();
const testPowerFromUrl = (() => {
  try {
    if (!globalThis.location?.search || typeof URLSearchParams !== "function") return null;
    const value = new URLSearchParams(globalThis.location.search).get("testPower");
    return value && POWER_CONFIGS[value] ? value : null;
  } catch {
    return null;
  }
})();
const testMovesFromUrl = (() => {
  try {
    if (!globalThis.location?.search || typeof URLSearchParams !== "function") return null;
    const rawValue = new URLSearchParams(globalThis.location.search).get("testMoves");
    if (rawValue === null) return null;
    const value = Number(rawValue);
    return Number.isInteger(value) && value >= 0 ? value : null;
  } catch {
    return null;
  }
})();
const testHelperFromUrl = (() => {
  try {
    if (!globalThis.location?.search || typeof URLSearchParams !== "function") return false;
    return new URLSearchParams(globalThis.location.search).get("testHelper") === "1";
  } catch {
    return false;
  }
})();
const testFailureFromUrl = (() => {
  try {
    if (!globalThis.location?.search || typeof URLSearchParams !== "function") return null;
    const value = new URLSearchParams(globalThis.location.search).get("testFailure");
    return new Set(["moves", "cat", "crow", "catcher", "hole", "water", "blocked"]).has(value)
      ? value
      : null;
  } catch {
    return null;
  }
})();
const previewAllObjectivesFromUrl = (() => {
  try {
    if (!globalThis.location?.search || typeof URLSearchParams !== "function") return false;
    return new URLSearchParams(globalThis.location.search).get("previewObjectives") === "all";
  } catch {
    return false;
  }
})();

function previewAllObjectiveTypes() {
  if (!previewAllObjectivesFromUrl) return;

  const objectivePreview = [
    ["cheeseObjective", "cheeseRemaining", "1"],
    ["milkObjective", "milkRemaining", "1"],
    ["pieObjective", "pieRemaining", "4"],
    ["carrotObjective", "carrotRemaining", "2"],
  ];
  for (const [itemId, countId, count] of objectivePreview) {
    const item = document.getElementById(itemId);
    const counter = document.getElementById(countId);
    item?.removeAttribute("hidden");
    if (counter) counter.textContent = count;
    const image = item?.querySelector("img[data-src]");
    if (image && !image.getAttribute("src")) image.setAttribute("src", image.dataset.src);
  }
  document.getElementById("cheeseProgress")?.setAttribute(
    "aria-label",
    "1 cheese, 1 milk, 4 pie quarters and 2 carrots remaining"
  );
}
if (testUnlockFromUrl !== null) {
  worldProgress.unlockedLevel = testUnlockFromUrl;
  worldProgress.completedLevels = Array.from(
    { length: LEVEL_CONFIGS.length },
    (_, index) => index < testUnlockFromUrl - 1,
  );
}
if (testLevelFromUrl !== null && testPowerFromUrl) {
  powerInventory[testPowerFromUrl] = Math.max(1, powerInventory[testPowerFromUrl]);
  syncPowerAvailability();
}
if (testLevelFromUrl !== null) {
  worldProgress.unlockedLevel = Math.max(worldProgress.unlockedLevel, testLevelFromUrl);
  level = testLevelFromUrl;
  if (testVariantFromUrl !== null) {
    levelVariantStates[testLevelFromUrl - 1].current = testVariantFromUrl;
    levelVariantStates[testLevelFromUrl - 1].remaining = [];
  }
  void startWorldLevel(testLevelFromUrl, { withHelper: testHelperFromUrl }).then(() => {
    if (testMovesFromUrl !== null) {
      movesLeft = Math.min(movesLeft, testMovesFromUrl);
      render();
    }
    previewAllObjectiveTypes();
    if (testFailureFromUrl) {
      const testFailureMessages = {
        moves: "The mouse ran out of energy and needs a short rest.",
        cat: "The cat's paw swept the mouse out of the maze.",
        crow: "The crow carried the mouse out of the maze.",
        catcher: "The remote-control catcher trapped the mouse in its net.",
        hole: "The mouse fell through the fragile floor.",
        water: "The rising water reached the mouse.",
        blocked: "The fragile floor closed every route to the remaining objectives.",
      };
      clearLevelIntroAnimation();
      if (testFailureFromUrl === "moves") {
        movesLeft = 0;
        render();
      }
      loseLevel(testFailureMessages[testFailureFromUrl], testFailureFromUrl);
    }
    globalThis.__mouseMazeTest = {
      move,
      crystalAudit: () => {
        const path = currentCrystalPath();
        const forecast = buildCrystalForecast(path.slice(1, movesLeft + 1));
        return {
          path: path.map((cell) => ({ row: cell.row, col: cell.col })),
          frameCount: forecast.frames.length,
          failure: forecast.failure,
          complete: forecast.complete,
          carCaptures: forecast.frames.filter((frame) => frame.events.carCapture).length,
          hazardCaptures: forecast.frames.filter((frame) => frame.events.hazardCapture).length,
        };
      },
      state: () => ({
        mouse: { ...mouse },
        helper: helperMouse ? { ...helperMouse } : null,
        helperCargo: helperCargo ? { ...helperCargo } : null,
        helperResting,
        helperCaptured,
        helperMode,
        helperTask: helperTask ? { ...helperTask } : null,
        helperIntent: helperLikelyPlayerIntent(mouse)?.key ?? null,
        helperDecision: helperLastDecision
          ? {
              ...helperLastDecision,
              from: { ...helperLastDecision.from },
              to: { ...helperLastDecision.to },
            }
          : null,
        helperDistractionCooldowns: { ...helperDistractionCooldowns },
        helperTestedRocks: [...helperTestedRockIds],
        helperTunnelCooldownTurns,
        movesLeft,
        failureRecovery: {
          failuresOnLevel: failureCountForCurrentLevel(),
          moveReward: moveRewardForCurrentFailure(),
          rescueMode: failureRescueMode,
          rescueUsed: rewardedRecoveryUsed,
          historyLength: turnHistory.length,
          rewinding: rewindAnimationActive,
        },
        shortestPath: shortestPath.map((cell) => ({ row: cell.row, col: cell.col })),
        cheeses: cheeseTargets.map((cell) => ({ row: cell.row, col: cell.col })),
        carrotPatches: carrotPatches.map((patch) => ({ ...patch })),
        inspectedCarrots: [...inspectedCarrotPatchIds],
        collectedCarrots: [...collectedCarrotIds],
        milkBottles: milkBottles.map((bottle) => ({
          id: bottle.id,
          row: bottle.row,
          col: bottle.col,
          knocked: bottle.knocked,
          spill: bottle.spill ? { ...bottle.spill } : null,
        })),
        collectedCheeses: [...collectedCheeseKeys],
        rocks: rockPositions.map((rock) => ({ ...rock })),
        pie: pie
          ? {
              row: pie.row,
              col: pie.col,
              quarters: pie.quarters.map((quarter) => ({ ...quarter })),
            }
          : null,
        eatenPieQuarters: [...eatenPieQuarterIds],
        remainingObjectives: remainingObjectiveCount(),
        fishingTargets: getFishingCatchTargets().map((target) => ({
          ...target,
          mouseDestination: target.mouseDestination
            ? { ...target.mouseDestination }
            : null,
        })),
        rocketTargets: getRocketTargets().map((target) => ({
          ...target,
          mouseDestination: target.mouseDestination
            ? { ...target.mouseDestination }
            : null,
        })),
        tornadoUnlocked: isPowerUnlocked("tornado"),
        tornadoTutorialActive,
        cockroach: {
          movesSinceAction: cockroachMovesSinceAction,
          nextTrigger: cockroachNextTrigger,
          actionsUsed: cockroachActionsUsed,
          animating: Boolean(cockroachAnimation),
        },
        catPaw: {
          movesSinceStrike: catPawMovesSinceStrike,
          nextTrigger: catPawNextTrigger,
          movesUntilStrike: catPawMovesUntilStrike(),
          threat: catPawThreat
            ? { ...catPawThreat, cells: catPawThreat.cells.map((cell) => ({ ...cell })) }
            : null,
          striking: Boolean(catPawAnimation),
        },
        crow: {
          active: Boolean(currentLevelConfig().crowMode),
          movesSinceStrike: crowMovesSinceStrike,
          nextTrigger: crowNextTrigger,
          movesUntilStrike: crowMovesUntilStrike(),
          threat: crowThreat
            ? { ...crowThreat, cells: crowThreat.cells.map((cell) => ({ ...cell })) }
            : null,
          striking: Boolean(crowAnimation),
          mouseProtected: cloudCoversCell(mouse),
        },
        tunnels: tunnels.map((tunnel) => ({
          id: tunnel.id,
          row: tunnel.row,
          col: tunnel.col,
          sealed: tunnel.sealed,
        })),
        water: {
          active: waterIsActive(),
          origin: { ...waterOrigin },
          moveCount: waterMoveCount,
          flooded: [...floodedWaterKeys],
          warning: waterWarningKeys(),
        },
        tunnelTutorialActive: Boolean(tunnelTutorial),
        tunnelTravelActive: Boolean(tunnelAnimation),
        activeVariantIndex,
      }),
      triggerFailure: (kind = "moves") => {
        const messages = {
          moves: "The mouse ran out of energy and needs a short rest.",
          cat: "The cat's paw swept the mouse out of the maze.",
          crow: "The crow carried the mouse out of the maze.",
          catcher: "The remote-control catcher trapped the mouse in its net.",
          hole: "The mouse fell through the fragile floor.",
          water: "The rising water reached the mouse.",
          blocked: "The fragile floor closed every route to the remaining objectives.",
        };
        if (!messages[kind]) return false;
        clearLevelIntroAnimation();
        if (kind === "moves") movesLeft = 0;
        loseLevel(messages[kind], kind);
        return true;
      },
    };
    mazeEl.dataset.testShortestPath = JSON.stringify(shortestPath);
    mazeEl.dataset.testCheeses = JSON.stringify(cheeseTargets);
    mazeEl.dataset.testCarrots = JSON.stringify(carrotPatches);
    mazeEl.dataset.testPie = JSON.stringify(pie);
    mazeEl.dataset.testVariant = String(activeVariantIndex);
    mazeEl.dataset.testCrystalAudit = JSON.stringify(
      globalThis.__mouseMazeTest.crystalAudit(),
    );
    mazeEl.dataset.testAdversities = JSON.stringify(
      Object.entries(ADVERSITY_MODE_PROPERTIES)
        .filter(([, properties]) => properties.some((property) => activeLevelConfig[property]))
        .map(([adversity]) => adversity),
    );
  });
} else if (testUnlockFromUrl !== null) {
  renderWorldMap();
}
